            logBatchProfile(req, profile);
        } else {
            try self.batchInternal(req, null, .{ .document_child_range_dispatcher = dispatcher });
        }
    }

    fn projectedBatchLsmAdmissionBytes(req: types.BatchRequest) u64 {
        var payload_bytes: u64 = 0;
        var operations: u64 = 0;
        for (req.writes) |write| {
            payload_bytes +|= @intCast(write.key.len);
            payload_bytes +|= @intCast(write.value.len);
            operations +|= 1;
        }
        for (req.deletes) |key| {
            payload_bytes +|= @intCast(key.len);
            operations +|= 1;
        }
        for (req.transforms) |transform| {
            payload_bytes +|= @intCast(transform.key.len);
            operations +|= 1;
            for (transform.operations) |operation| {
                payload_bytes +|= @intCast(operation.path.len);
                if (operation.value_json) |value| payload_bytes +|= @intCast(value.len);
                operations +|= 1;
            }
        }
        for (req.graph_writes) |write| {
            payload_bytes +|= @intCast(write.index_name.len);
            payload_bytes +|= @intCast(write.source.len);
            payload_bytes +|= @intCast(write.target.len);
            payload_bytes +|= @intCast(write.edge_type.len);
            payload_bytes +|= @intCast(write.metadata_json.len);
            operations +|= 1;
        }
        for (req.graph_deletes) |delete| {
            payload_bytes +|= @intCast(delete.index_name.len);
            payload_bytes +|= @intCast(delete.source.len);
            payload_bytes +|= @intCast(delete.target.len);
            payload_bytes +|= @intCast(delete.edge_type.len);
            operations +|= 1;
        }
        for (req.predicates) |predicate| payload_bytes +|= @intCast(predicate.key.len);

        // Primary rows are accompanied by internal identity/timestamp/replay
        // records, allocator capacity, and the memtable hash index. Two times
        // encoded payload plus a per-operation allowance is deliberately a
        // conservative preflight; the backend still performs the exact guard
        // immediately before WAL append.
        return (payload_bytes *| 2) +| (operations *| 512);
    }

    pub fn drainDocumentArtifactChildRangeOutbox(
        self: *DB,
        dispatcher: DocumentArtifactChildRangeDispatcher,
        limit: usize,
    ) anyerror!DocumentArtifactChildRangeOutboxDrainResult {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        try self.enforceHAWriteGate();

        const prefix = try internal_keys.documentChildRangeOutboxRootPrefixAlloc(self.alloc);
        defer self.alloc.free(prefix);

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();
        const scanned = try self.core.scanStorePrefix(self.alloc, prefix);
        self.core.unlockApply();
        apply_mutex_held = false;
        defer docstore_mod.DocStore.freeResults(self.alloc, scanned);

        var result = DocumentArtifactChildRangeOutboxDrainResult{};
        const max_entries = if (limit == 0 or limit > scanned.len) scanned.len else limit;
        for (scanned[0..max_entries]) |entry| {
            result.scanned += 1;
            var parsed = try std.json.parseFromSlice(DocumentArtifactChildRangeOutboxRecord, self.alloc, entry.value, .{
                .allocate = .alloc_always,
            });
            defer parsed.deinit();
            if (parsed.value.version != 1) return error.InvalidDocumentChildRangeOutboxRecord;
            try dispatcher.applyDispatch(self.alloc, .{
                .owner_group_id = parsed.value.owner_group_id,
                .doc_key = parsed.value.doc_key,
                .artifact_name = parsed.value.artifact_name,
                .child_batch = parsed.value.child_batch,
            });
            result.dispatched += 1;
            try self.deleteDocumentArtifactChildRangeOutboxEntry(entry.key);
            result.deleted += 1;
        }
        return result;
    }

    fn deleteDocumentArtifactChildRangeOutboxEntry(self: *DB, key: []const u8) !void {
        try self.enforceHAWriteGate();
        lockApply(self);
        defer self.core.unlockApply();
        const deletes = [_][]const u8{key};
        try self.core.store.putBatch(&.{}, deletes[0..]);
    }

    pub fn batchWithoutRangeValidation(self: *DB, req: types.BatchRequest) anyerror!void {
        try self.batchInternal(req, null, .{ .validate_range_ownership = false });
    }

    pub fn batchReplicatedApply(self: *DB, req: types.BatchRequest) anyerror!void {
        try self.batchReplicatedApplyWithMarker(req, null);
    }

    fn batchReplicatedApplyWithMarker(self: *DB, req: types.BatchRequest, applied_lsn_marker: ?u64) anyerror!void {
        var apply_req = req;
        apply_req.sync_level = .write;
        try self.batchInternal(apply_req, null, .{
            .validate_range_ownership = false,
            .wait_for_sync_level = false,
            .bypass_ha_write_gate = true,
            .ha_applied_lsn_marker = applied_lsn_marker,
        });
    }

    fn setSchemaReplicatedApplyWithMarker(self: *DB, table_schema: schema_mod.TableSchema, applied_lsn_marker: ?u64) anyerror!void {
        try self.core.setSchema(table_schema);
        if (applied_lsn_marker) |lsn| try self.markHAReplicationRecordApplied(lsn);
    }

    pub fn applyHAReplicationRecord(self: *DB, record: ha_replication_record_mod.RecordView) anyerror!void {
        if (try self.haReplicationRecordAlreadyApplied(record)) return;

        switch (record.kind) {
            .batch_mutation => {
                var decoded = try ha_effects_mod.decodeBatchMutationRequest(self.alloc, record);
                defer decoded.deinit();
                try self.batchReplicatedApplyWithMarker(decoded.value.request, record.lsn);
            },
            .metadata_mutation => {
                const decoded_schema = try ha_effects_mod.decodeSchemaMetadataMutation(self.alloc, record);
                defer schema_mod.freeSchema(self.alloc, decoded_schema);
                try self.setSchemaReplicatedApplyWithMarker(decoded_schema, record.lsn);
            },
            .derived_effect => {
                _ = try self.applyHADerivedEffectRecord(record);
                try self.markHAReplicationRecordApplied(record.lsn);
            },
            .backup_start,
            .backup_end,
            .checkpoint,
            .manifest,
            .truncate,
            .timeline_switch,
            => try self.markHAReplicationRecordApplied(record.lsn),
            _ => return error.HAReplicationRecordApplyUnsupported,
        }
    }

    pub fn applyHADerivedEffectRecord(self: *DB, record: ha_replication_record_mod.RecordView) anyerror!u64 {
        var ctx = self.batchContext();
        return try appendReplicatedHADerivedEffectContext(&ctx, record);
    }

    pub fn haAppliedReplicationLsn(self: *DB) anyerror!u64 {
        return try readHAAppliedReplicationLsn(self.alloc, self.core.store);
    }

    fn haReplicationRecordAlreadyApplied(self: *DB, record: ha_replication_record_mod.RecordView) !bool {
        if (record.lsn == 0) return false;
        return (try self.haAppliedReplicationLsn()) >= record.lsn;
    }

    fn markHAReplicationRecordApplied(self: *DB, lsn: u64) !void {
        if (lsn == 0) return;
        const current = try self.haAppliedReplicationLsn();
        if (current >= lsn) return;
        var value_buf: [ha_applied_lsn_value_len]u8 = undefined;
        const marker = haAppliedReplicationLsnWrite(lsn, &value_buf);
        try self.core.store.putBatch(&.{marker}, &.{});
    }

    pub fn applyHAReplicationRecordCallback(ctx: *anyopaque, record: ha_replication_record_mod.RecordView) anyerror!void {
        const self: *DB = @ptrCast(@alignCast(ctx));
        try self.applyHAReplicationRecord(record);
    }

    pub fn applyDocumentArtifactChildRangeBatch(self: *DB, child_batch: DocumentArtifactChildRangeApplyBatch) anyerror!u64 {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        try self.enforceHAWriteGate();
        if (child_batch.artifact_writes.len == 0 and
            child_batch.artifact_delete_keys.len == 0 and
            child_batch.documents.len == 0 and
            child_batch.dense_embeddings.len == 0 and
            child_batch.sparse_embeddings.len == 0 and
            child_batch.generated_enrichment_refs.len == 0)
        {
            return 0;
        }

        try self.executor.failIfUnhealthy();

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer store_writes.deinit(self.alloc);
        var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer delete_keys.deinit(self.alloc);
        var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_keys.items) |key| self.alloc.free(key);
            owned_store_keys.deinit(self.alloc);
        }
        var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_values.items) |value| self.alloc.free(value);
            owned_store_values.deinit(self.alloc);
        }
        var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_delete_keys.items) |key| self.alloc.free(key);
            owned_delete_keys.deinit(self.alloc);
        }
        var changed_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (changed_artifact_keys.items) |key| self.alloc.free(key);
            changed_artifact_keys.deinit(self.alloc);
        }
        var materialized_graph_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (materialized_graph_artifact_writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            materialized_graph_artifact_writes.deinit(self.alloc);
        }

        for (child_batch.artifact_writes) |write| {
            try store_writes.append(self.alloc, .{
                .key = write.key,
                .value = write.value,
            });
            try appendUniqueOwnedKey(self.alloc, &changed_artifact_keys, write.key);
        }
        for (child_batch.artifact_delete_keys) |key| {
            try delete_keys.append(self.alloc, key);
            if (internal_keys.isAssetArtifactKey(key) or internal_keys.isGraphEdgeArtifactKey(key)) {
                try appendUniqueOwnedKey(self.alloc, &changed_artifact_keys, key);
            }
        }

        try appendPrecomputedGraphSourceArtifacts(
            self,
            child_batch.artifact_writes,
            child_batch.artifact_delete_keys,
            &materialized_graph_artifact_writes,
            &store_writes,
            &delete_keys,
            &owned_delete_keys,
            &changed_artifact_keys,
        );

        if (child_batch.artifact_writes.len > 0 or materialized_graph_artifact_writes.items.len > 0) {
            try self.core.appendArtifactPresenceMarker(&store_writes);
        }
        try appendAssetArtifactSourceIndexMutations(
            self.alloc,
            &store_writes,
            child_batch.artifact_delete_keys,
            &delete_keys,
            &owned_store_keys,
            &owned_store_values,
            &owned_delete_keys,
        );

        const sequence = self.core.reserveDerivedAppendSequence();
        const derived_seed = derived_types.DerivedBatch{
            .sequence = sequence,
            .documents = child_batch.documents,
            .deleted_keys = child_batch.artifact_delete_keys,
            .changed_artifact_keys = changed_artifact_keys.items,
            .dense_embeddings = child_batch.dense_embeddings,
            .sparse_embeddings = child_batch.sparse_embeddings,
            .generated_enrichment_refs = child_batch.generated_enrichment_refs,
        };
        var derived_batch = try derived_types.cloneBatch(self.alloc, derived_seed);
        defer derived_types.deinitDerivedBatch(self.alloc, &derived_batch);
        derived_batch.sequence = sequence;

        var sync_targets = try collectManagedSyncTargets(self.alloc, self.core.index_manager, derived_batch);
        defer sync_targets.deinit(self.alloc);
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), derived_batch, sequence);
        defer self.alloc.free(replay_payload);

        try appendDenseArtifactCounterMutations(
            self.alloc,
            self.core.store,
            self.core.index_manager,
            &store_writes,
            delete_keys.items,
            &owned_store_keys,
            &owned_store_values,
        );
        try self.core.store.putBatchWithReplay(
            self.backend_runtime.io(),
            store_writes.items,
            delete_keys.items,
            .{
                .sequence = sequence,
                .payload = replay_payload,
            },
        );
        self.mirrorHAReplayPayloadBestEffort(replay_payload);
        if (shouldAppendSplitDelta(self)) {
            try self.core.appendSplitDelta(currentTimeNs(), store_writes.items, delete_keys.items);
        }

        self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
        self.core.unlockApply();
        apply_mutex_held = false;

        var pressure_ctx = self.batchContext();
        try self.markPrecomputedEnrichmentAppliedForSync(child_batch.sync_level, sequence);
        try applyDerivedBacklogPressureContext(&pressure_ctx, sequence, child_batch.sync_level, sync_targets);
        if (self.executor.hasWorkers()) {
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, child_batch.sync_level, sequence, sync_targets);
            try self.waitForSyncLevel(child_batch.sync_level, sequence, sync_targets);
        } else {
            if (syncLevelRequiresDerivedVisibility(child_batch.sync_level)) {
                if (child_batch.sync_level == .full_text) {
                    try applyDerivedBatchTargetsProfiled(self, derived_batch, sync_targets.full_text_indexes, null);
                } else {
                    try applyDerivedBatchProfiled(self, derived_batch, null);
                }
            }
            try self.waitForSyncLevel(child_batch.sync_level, sequence, sync_targets);
        }
        if (self.enrichment_runtime) |runtime| runtime.notifySequence(sequence);
        self.notifyResolverReplayRuntimes(sequence);
        return sequence;
    }

    fn batchInternal(self: *DB, req: types.BatchRequest, profile: ?*BatchProfile, opts: BatchExecutionOptions) anyerror!void {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        if (!opts.bypass_ha_write_gate and self.denseRepairWriteBackpressured()) return error.DenseRepairBackpressure;
        if (!opts.bypass_ha_write_gate) try self.enforceHAWriteGate();
        if (!opts.bypass_ha_write_gate) try self.preflightHABatchSyncCommit();
        const total_start_ns = monotonicTimeNs();
        defer {
            if (profile) |active_profile| {
                active_profile.total_ns += monotonicTimeNs() - total_start_ns;
            }
        }

        try self.executor.failIfUnhealthy();

        // Global LSM throttling must happen before the DB apply lock. Derived
        // and maintenance workers may need that lock to publish or flush the
        // state that releases aggregate pressure. The backend commit performs
        // the final projected check before WAL append, so this non-reserving
        // preflight is an early wait, not the durability guard.
        if (self.core.index_manager.resource_manager) |manager| {
            try manager.awaitAdmission(.lsm_in_memory_state, projectedBatchLsmAdmissionBytes(req));
        }

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        if (self.bulk_ingest_coalescer.active and !self.flushing_bulk_ingest_coalescer) {
            if (self.bulk_ingest_coalescer.hasPending()) {
                self.core.unlockApply();
                apply_mutex_held = false;
                try self.flushBulkIngestCoalescerWithSyncLevel(req.sync_level, profile);
                lockApply(self);
                apply_mutex_held = true;
            }
        }

        const resolve_transforms_start_ns = monotonicTimeNs();
        var effective_ops = try coalesceKeyValueRequest(self, types.BatchWrite, req.writes, req.deletes, req.transforms);
        defer effective_ops.deinit(self.alloc);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.resolve_transforms_ns, resolve_transforms_start_ns);

        const merge_effective_req_start_ns = monotonicTimeNs();

        const effective_req: types.BatchRequest = .{
            .writes = effective_ops.writes,
            .deletes = effective_ops.deletes,
            .graph_writes = req.graph_writes,
            .graph_deletes = req.graph_deletes,
            .transforms = &.{},
            .predicates = req.predicates,
            .timestamp_ns = req.timestamp_ns,
            .sync_level = req.sync_level,
        };
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.merge_effective_req_ns, merge_effective_req_start_ns);

        if (effective_req.predicates.len > 0) {
            const predicates_start_ns = monotonicTimeNs();
            var predicates = std.ArrayListUnmanaged(transactions_mod.VersionPredicate).empty;
            defer predicates.deinit(self.alloc);
            for (effective_req.predicates) |predicate| {
                try predicates.append(self.alloc, .{
                    .key = predicate.key,
                    .expected_version = predicate.expected_version,
                });
            }
            try self.core.checkVersionPredicates(predicates.items, null);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.predicates_ns, predicates_start_ns);
        }

        if (opts.validate_range_ownership) {
            const validate_range_start_ns = monotonicTimeNs();
            try self.core.validateBatchRangeOwnership(effective_req);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.validate_range_ns, validate_range_start_ns);
        }

        const extract_writes_start_ns = monotonicTimeNs();
        var extracted = try self.alloc.alloc(mapper.ExtractedWrite, effective_req.writes.len);
        var extracted_initialized: usize = 0;
        defer {
            for (extracted[0..extracted_initialized]) |*item| item.deinit(self.alloc);
            self.alloc.free(extracted);
        }

        var store_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer store_writes.deinit(self.alloc);
        var owned_store_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_keys.items) |key| self.alloc.free(key);
            owned_store_keys.deinit(self.alloc);
        }
        var owned_store_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_store_values.items) |value| self.alloc.free(value);
            owned_store_values.deinit(self.alloc);
        }
        const vector_field_names_start_ns = monotonicTimeNs();
        const vector_store_field_names = try self.core.index_manager.vectorStoreFieldNamesAlloc(self.alloc);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_vector_field_names_ns, vector_field_names_start_ns);
        defer {
            for (vector_store_field_names) |field| self.alloc.free(field);
            if (vector_store_field_names.len > 0) self.alloc.free(vector_store_field_names);
        }
        var timestamp_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (timestamp_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            timestamp_writes.deinit(self.alloc);
        }
        var explicit_embedding_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (explicit_embedding_artifact_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            explicit_embedding_artifact_writes.deinit(self.alloc);
        }
        var explicit_graph_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (explicit_graph_artifact_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            explicit_graph_artifact_writes.deinit(self.alloc);
        }
        var delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer delete_keys.deinit(self.alloc);
        var owned_delete_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_delete_keys.items) |key| self.alloc.free(key);
            owned_delete_keys.deinit(self.alloc);
        }
        var graph_artifact_clears = std.ArrayListUnmanaged(GraphArtifactClear).empty;
        defer {
            for (graph_artifact_clears.items) |*item| item.deinit(self.alloc);
            graph_artifact_clears.deinit(self.alloc);
        }
        var timestamp_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (timestamp_delete_keys.items) |key| self.alloc.free(@constCast(key));
            timestamp_delete_keys.deinit(self.alloc);
        }
        var overwritten_flags = try self.alloc.alloc(bool, effective_req.writes.len);
        defer self.alloc.free(overwritten_flags);
        @memset(overwritten_flags, false);
        var overwrite_probe_entries = std.ArrayListUnmanaged(OverwriteProbeEntry).empty;
        defer overwrite_probe_entries.deinit(self.alloc);
        var identity_upsert_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer identity_upsert_keys.deinit(self.alloc);
        var identity_upsert_write_indexes = std.ArrayListUnmanaged(usize).empty;
        defer identity_upsert_write_indexes.deinit(self.alloc);
        var identity_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (identity_writes.items) |item| {
                self.alloc.free(@constCast(item.key));
                self.alloc.free(@constCast(item.value));
            }
            identity_writes.deinit(self.alloc);
        }
        var identity_visibility_deletes = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (identity_visibility_deletes.items) |key| self.alloc.free(key);
            identity_visibility_deletes.deinit(self.alloc);
        }

        const batch_timestamp_ns = if (effective_req.timestamp_ns != 0) effective_req.timestamp_ns else currentTimeNs();

        for (effective_req.writes, 0..) |write, i| {
            if (isMetadataKey(write.key)) {
                extracted[i] = .{
                    .cleaned_value = null,
                    .graph_writes = &.{},
                    .mentioned_graph_indexes = &.{},
                    .dense_embeddings = &.{},
                    .sparse_embeddings = &.{},
                };
                extracted_initialized += 1;
                try store_writes.append(self.alloc, .{
                    .key = write.key,
                    .value = write.value,
                });
                continue;
            }
            const mapper_extract_start_ns = monotonicTimeNs();
            extracted[i] = try mapper.extractWrite(self.alloc, write.key, write.value);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_mapper_ns, mapper_extract_start_ns);
            const graph_field_extract_start_ns = monotonicTimeNs();
            try augmentExtractedWriteWithGraphFieldEdges(self, self.alloc, write.key, write.value, &extracted[i]);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_graph_fields_ns, graph_field_extract_start_ns);
            const index_field_embeddings_start_ns = monotonicTimeNs();
            try self.core.index_manager.appendIndexFieldEmbeddingsToExtractedWrite(self.alloc, write.key, write.value, &extracted[i]);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_index_field_embeddings_ns, index_field_embeddings_start_ns);
            extracted_initialized += 1;
            const embedding_artifacts_start_ns = monotonicTimeNs();
            for (extracted[i].dense_embeddings) |*embedding| {
                if (embedding.artifact_key != null) continue;
                embedding.artifact_key = try appendEmbeddingArtifactWrite(
                    self.alloc,
                    &explicit_embedding_artifact_writes,
                    write.key,
                    write.key,
                    embedding.index_name,
                    "_embeddings",
                    null,
                    null,
                    embedding.vector,
                );
            }
            for (extracted[i].sparse_embeddings) |*embedding| {
                if (embedding.artifact_key != null) continue;
                embedding.artifact_key = try appendSparseEmbeddingArtifactWrite(
                    self.alloc,
                    &explicit_embedding_artifact_writes,
                    write.key,
                    embedding.index_name,
                    null,
                    embedding.indices,
                    embedding.values,
                );
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_embedding_artifacts_ns, embedding_artifacts_start_ns);
            const graph_artifacts_start_ns = monotonicTimeNs();
            for (extracted[i].graph_writes) |graph_write| {
                try appendGraphEdgeArtifactWrite(self.alloc, &explicit_graph_artifact_writes, graph_write);
            }
            for (extracted[i].mentioned_graph_indexes) |index_name| {
                try graph_artifact_clears.append(self.alloc, .{
                    .doc_key = try self.alloc.dupe(u8, write.key),
                    .index_name = try self.alloc.dupe(u8, index_name),
                });
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_graph_artifacts_ns, graph_artifacts_start_ns);
            if (extracted[i].cleaned_value) |cleaned| {
                try validateDocumentExtractionInlineSources(self, cleaned);
                const strip_store_value_start_ns = monotonicTimeNs();
                const store_value = try strippedStoredDocumentValueAlloc(
                    self.alloc,
                    cleaned,
                    vector_store_field_names,
                    &owned_store_values,
                );
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_strip_store_value_ns, strip_store_value_start_ns);
                const store_key = try internal_keys.documentKeyAlloc(self.alloc, write.key);
                try owned_store_keys.append(self.alloc, store_key);
                try overwrite_probe_entries.append(self.alloc, .{
                    .key = store_key,
                    .write_index = i,
                });
                try store_writes.append(self.alloc, .{
                    .key = store_key,
                    .value = store_value,
                });
                try identity_upsert_keys.append(self.alloc, write.key);
                try identity_upsert_write_indexes.append(self.alloc, i);
                if (shouldWriteTimestamp(write.key)) {
                    const timestamp_start_ns = monotonicTimeNs();
                    const write_timestamp_ns = try resolveWriteTimestampNs(self, batch_timestamp_ns, write.value);
                    const timestamp_key = try makeTimestampKey(self.alloc, write.key);
                    const timestamp_value = try encodeTimestampValue(self.alloc, write_timestamp_ns);
                    try timestamp_writes.append(self.alloc, .{
                        .key = timestamp_key,
                        .value = timestamp_value,
                    });
                    if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_timestamp_ns, timestamp_start_ns);
                }
            }
        }
        if (profile) |active_profile| {
            active_profile.identity_upsert_keys += @intCast(identity_upsert_keys.items.len);
            active_profile.identity_delete_keys += @intCast(effective_req.deletes.len);
        }
        const identity_capacity_start_ns = monotonicTimeNs();
        if (!self.bulk_ingest_identity_all_new or effective_req.deletes.len != 0) {
            try self.failIfIdentityOrdinalExhaustedForNewUpserts(identity_upsert_keys.items);
        }
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.identity_capacity_check_ns, identity_capacity_start_ns);

        var assume_all_new_identity_upserts = false;
        if (self.bulk_ingest_identity_all_new and effective_req.deletes.len == 0 and identity_upsert_keys.items.len > 0) {
            assume_all_new_identity_upserts = try self.rememberBulkIngestAllNewIdentityUpserts(identity_upsert_keys.items);
            if (!assume_all_new_identity_upserts) self.clearBulkIngestIdentityAllNewLocked();
        }

        if (!assume_all_new_identity_upserts and overwrite_probe_entries.items.len > 0) {
            const overwrite_probe_start_ns = monotonicTimeNs();
            std.sort.pdq(OverwriteProbeEntry, overwrite_probe_entries.items, {}, overwriteProbeLessThan);
            const probe_keys = try self.alloc.alloc([]const u8, overwrite_probe_entries.items.len);
            defer self.alloc.free(probe_keys);
            const probe_values = try self.alloc.alloc(?[]const u8, overwrite_probe_entries.items.len);
            defer self.alloc.free(probe_values);
            for (overwrite_probe_entries.items, 0..) |entry, i| {
                probe_keys[i] = entry.key;
            }
            var overwrite_probe_txn = try self.core.store.beginProbeTxn();
            defer overwrite_probe_txn.abort();
            try overwrite_probe_txn.getManySorted(probe_keys, probe_values);
            for (overwrite_probe_entries.items, 0..) |entry, i| {
                overwritten_flags[entry.write_index] = probe_values[i] != null;
            }
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.overwrite_probe_ns, overwrite_probe_start_ns);
        }

        for (effective_req.graph_writes) |graph_write| {
            try appendGraphEdgeArtifactWrite(self.alloc, &explicit_graph_artifact_writes, graph_write);
        }

        var changed_graph_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (changed_graph_artifact_keys.items) |key| self.alloc.free(key);
            changed_graph_artifact_keys.deinit(self.alloc);
        }
        for (graph_artifact_clears.items) |clear| {
            const existing = try collectGraphArtifactsForDocIndex(self.alloc, self.core.store, clear.doc_key, clear.index_name);
            defer docstore_mod.DocStore.freeResults(self.alloc, existing);
            for (existing) |entry| {
                if (containsBatchWriteKey(explicit_graph_artifact_writes.items, entry.key)) continue;
                if (containsOwnedKey(owned_delete_keys.items, entry.key)) continue;
                const owned_key = try self.alloc.dupe(u8, entry.key);
                try owned_delete_keys.append(self.alloc, owned_key);
                try delete_keys.append(self.alloc, owned_key);
                try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, entry.key);
            }
        }

        try store_writes.appendSlice(self.alloc, timestamp_writes.items);
        for (explicit_embedding_artifact_writes.items) |write| {
            try store_writes.append(self.alloc, .{
                .key = write.key,
                .value = write.value,
            });
        }
        for (explicit_graph_artifact_writes.items) |write| {
            try store_writes.append(self.alloc, .{
                .key = write.key,
                .value = write.value,
            });
            try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, write.key);
        }
        for (effective_req.graph_deletes) |delete| {
            const artifact_key = try internal_keys.graphEdgeArtifactKeyAlloc(self.alloc, delete.source, delete.index_name, delete.edge_type, delete.target);
            defer self.alloc.free(artifact_key);
            if (containsBatchWriteKey(explicit_graph_artifact_writes.items, artifact_key)) continue;
            if (containsOwnedKey(owned_delete_keys.items, artifact_key)) continue;
            const owned_key = try self.alloc.dupe(u8, artifact_key);
            try owned_delete_keys.append(self.alloc, owned_key);
            try delete_keys.append(self.alloc, owned_key);
            try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, artifact_key);
        }
        for (effective_req.deletes) |key| {
            const store_key = try internal_keys.documentKeyAlloc(self.alloc, key);
            try owned_delete_keys.append(self.alloc, store_key);
            try delete_keys.append(self.alloc, store_key);
            if (shouldWriteTimestamp(key)) {
                const timestamp_key = try makeTimestampKey(self.alloc, key);
                try timestamp_delete_keys.append(self.alloc, timestamp_key);
                try delete_keys.append(self.alloc, timestamp_key);
            }
        }
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.extract_writes_ns, extract_writes_start_ns);

        const delete_artifacts_start_ns = monotonicTimeNs();
        const deleted_artifact_keys = try collectEnrichmentArtifactDeletesForBatch(
            self,
            effective_req,
            extracted[0..extracted_initialized],
            &delete_keys,
            &owned_delete_keys,
        );
        defer self.alloc.free(deleted_artifact_keys);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.delete_artifacts_ns, delete_artifacts_start_ns);

        const use_thin_replay_fast_path =
            effective_req.sync_level != .full_text and
            effective_req.sync_level != .enrichments and
            effective_req.sync_level != .full_index and
            !splitShadowRequiresMaterializedDerivedBatch(self);
        const include_generated_enrichment_hint = use_thin_replay_fast_path and
            self.core.hasGeneratedEnrichmentTargets();

        var precomputed_generated: PrecomputedGeneratedBatch = .{};
        defer precomputed_generated.deinit(self.alloc);
        var remote_child_range_dispatches = std.ArrayListUnmanaged(DocumentChildRangeDispatchGroup).empty;
        defer {
            for (remote_child_range_dispatches.items) |*dispatch| dispatch.deinit(self.alloc);
            remote_child_range_dispatches.deinit(self.alloc);
        }
        var owned_child_range_outbox_keys = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_child_range_outbox_keys.items) |key| self.alloc.free(key);
            owned_child_range_outbox_keys.deinit(self.alloc);
        }
        var owned_child_range_outbox_values = std.ArrayListUnmanaged([]u8).empty;
        defer {
            for (owned_child_range_outbox_values.items) |value| self.alloc.free(value);
            owned_child_range_outbox_values.deinit(self.alloc);
        }
        var materialized_graph_artifact_writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
        defer {
            for (materialized_graph_artifact_writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            materialized_graph_artifact_writes.deinit(self.alloc);
        }
        if (!use_thin_replay_fast_path) {
            const precompute_generated_start_ns = monotonicTimeNs();
            precomputed_generated = try prepareGeneratedEnrichments(
                self,
                effective_req,
                extracted[0..extracted_initialized],
                generatedPrecomputeModeForSyncLevel(effective_req.sync_level),
                opts.force_generated_artifact_names,
            );

            if (opts.document_child_range_dispatcher != null) {
                try partitionRemoteDocumentChildRangeGeneratedBatch(self, &precomputed_generated, &remote_child_range_dispatches);
            }

            for (precomputed_generated.artifact_writes) |write| {
                try store_writes.append(self.alloc, .{
                    .key = write.key,
                    .value = write.value,
                });
                try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, write.key);
            }
            for (precomputed_generated.artifact_delete_keys) |key| {
                try delete_keys.append(self.alloc, key);
                if (internal_keys.isAssetArtifactKey(key)) {
                    try appendUniqueOwnedKey(self.alloc, &changed_graph_artifact_keys, key);
                }
            }
            try appendPrecomputedGraphSourceArtifacts(
                self,
                precomputed_generated.artifact_writes,
                precomputed_generated.artifact_delete_keys,
                &materialized_graph_artifact_writes,
                &store_writes,
                &delete_keys,
                &owned_delete_keys,
                &changed_graph_artifact_keys,
            );
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.precompute_generated_ns, precompute_generated_start_ns);
        }
        if (explicit_embedding_artifact_writes.items.len > 0 or
            explicit_graph_artifact_writes.items.len > 0 or
            materialized_graph_artifact_writes.items.len > 0 or
            precomputed_generated.artifact_writes.len > 0)
        {
            try self.core.appendArtifactPresenceMarker(&store_writes);
        }
        try appendAssetArtifactSourceIndexMutations(
            self.alloc,
            &store_writes,
            deleted_artifact_keys,
            &delete_keys,
            &owned_store_keys,
            &owned_store_values,
            &owned_delete_keys,
        );

        var sync_targets: ManagedSyncTargets = .{};
        defer sync_targets.deinit(self.alloc);
        var materialized_derived_batch: ?derived_types.DerivedBatch = null;
        defer if (materialized_derived_batch) |*materialized_batch| derived_types.deinitDerivedBatch(self.alloc, materialized_batch);
        const sequence = self.core.reserveDerivedAppendSequence();
        const identity_metadata_start_ns = monotonicTimeNs();
        var used_trusted_identity_path = false;
        if (effective_req.deletes.len != 0) {
            self.clearBulkIngestIdentityAllNewLocked();
        }
        if (self.bulk_ingest_identity_all_new and
            effective_req.deletes.len == 0 and
            identity_upsert_keys.items.len > 0 and
            (assume_all_new_identity_upserts or identityUpsertStoreWritesAreNew(identity_upsert_write_indexes.items, overwritten_flags)))
        {
            used_trusted_identity_path = try doc_identity.appendBatchIdentityMetadataAllNewTrustedStateWithVisibilityDeletesForNamespaceAlloc(
                self.alloc,
                self.core.identity_namespace,
                sequence,
                &identity_writes,
                &identity_visibility_deletes,
                identity_upsert_keys.items,
                &self.bulk_ingest_identity_state,
            );
            if (!used_trusted_identity_path) self.clearBulkIngestIdentityAllNewLocked();
        }
        if (!used_trusted_identity_path) {
            try doc_identity.appendBatchIdentityMetadataForNamespaceWithVisibilityDeletesAlloc(
                self.alloc,
                self.core.store,
                self.core.identity_namespace,
                sequence,
                &identity_writes,
                &identity_visibility_deletes,
                identity_upsert_keys.items,
                effective_req.deletes,
            );
        }
        if (profile) |active_profile| {
            recordProfileNs(profile, &active_profile.identity_metadata_ns, identity_metadata_start_ns);
            active_profile.identity_metadata_writes += @intCast(identity_writes.items.len);
        }
        const pending_identity_visibility_summary = try doc_identity.visibilitySummaryFromWrites(identity_writes.items);
        try store_writes.appendSlice(self.alloc, identity_writes.items);
        try appendDocumentChildRangeOutboxWrites(
            self.alloc,
            sequence,
            remote_child_range_dispatches.items,
            effective_req.sync_level,
            &store_writes,
            &owned_child_range_outbox_keys,
            &owned_child_range_outbox_values,
        );
        const build_derived_start_ns = monotonicTimeNs();
        const replay_payload = if (use_thin_replay_fast_path)
            try encodeThinReplayRecordPayload(
                self.alloc,
                effective_req,
                extracted[0..extracted_initialized],
                deleted_artifact_keys,
                changed_graph_artifact_keys.items,
                overwritten_flags,
                sequence,
                include_generated_enrichment_hint,
            )
        else blk: {
            materialized_derived_batch = try buildDerivedBatch(self.alloc, effective_req, extracted[0..extracted_initialized], deleted_artifact_keys, changed_graph_artifact_keys.items);
            for (materialized_derived_batch.?.overwritten_doc_keys) |key| self.alloc.free(@constCast(key));
            if (materialized_derived_batch.?.overwritten_doc_keys.len > 0) self.alloc.free(materialized_derived_batch.?.overwritten_doc_keys);
            materialized_derived_batch.?.overwritten_doc_keys = try buildOverwrittenDocKeys(self.alloc, effective_req.writes, overwritten_flags);
            materialized_derived_batch.?.documents = try takeOwnedSlice(derived_types.DerivedDocument, self.alloc, materialized_derived_batch.?.documents, &precomputed_generated.documents);
            materialized_derived_batch.?.dense_embeddings = try takeOwnedSlice(derived_types.DerivedDenseEmbeddingWrite, self.alloc, materialized_derived_batch.?.dense_embeddings, &precomputed_generated.dense_embeddings);
            materialized_derived_batch.?.sparse_embeddings = try takeOwnedSlice(derived_types.DerivedSparseEmbeddingWrite, self.alloc, materialized_derived_batch.?.sparse_embeddings, &precomputed_generated.sparse_embeddings);
            materialized_derived_batch.?.generated_enrichment_refs = precomputed_generated.generated_enrichment_refs;
            precomputed_generated.generated_enrichment_refs = &.{};
            materialized_derived_batch.?.sequence = sequence;
            const payload = try encodeChangeRecordPayload(&self.batchContext(), materialized_derived_batch.?, sequence);
            try attachInlineUpsertDocumentValues(self.alloc, &materialized_derived_batch.?, effective_req, extracted[0..extracted_initialized]);

            const apply_shadow_start_ns = monotonicTimeNs();
            try applyDerivedBatchToShadowIfNeeded(self, materialized_derived_batch.?);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.apply_shadow_ns, apply_shadow_start_ns);

            const collect_sync_targets_start_ns = monotonicTimeNs();
            sync_targets = try collectManagedSyncTargets(self.alloc, self.core.index_manager, materialized_derived_batch.?);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.collect_sync_targets_ns, collect_sync_targets_start_ns);
            break :blk payload;
        };
        defer self.alloc.free(replay_payload);
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.build_derived_ns, build_derived_start_ns);

        const store_write_start_ns = monotonicTimeNs();
        const store_batch_options: backend_types.BatchOptions = if (opts.store_batch_options.mode != .default)
            opts.store_batch_options
        else if (self.bulk_ingest_coalescer.active)
            .{ .mode = .bulk_ingest, .defer_commit_flush = true }
        else
            .{};
        var ha_applied_lsn_value_buf: [ha_applied_lsn_value_len]u8 = undefined;
        if (opts.ha_applied_lsn_marker) |lsn| {
            if (lsn != 0) {
                try store_writes.append(self.alloc, haAppliedReplicationLsnWrite(lsn, &ha_applied_lsn_value_buf));
            }
        }
        try appendDenseArtifactCounterMutations(
            self.alloc,
            self.core.store,
            self.core.index_manager,
            &store_writes,
            delete_keys.items,
            &owned_store_keys,
            &owned_store_values,
        );
        try delete_keys.appendSlice(self.alloc, identity_visibility_deletes.items);
        const replay_append: ?docstore_mod.DocStore.ReplayAppend = if (opts.suppress_derived_replay_append)
            null
        else
            .{
                .sequence = sequence,
                .payload = replay_payload,
            };
        try self.core.store.putBatchWithReplayWithOptions(
            self.backend_runtime.io(),
            store_writes.items,
            delete_keys.items,
            replay_append,
            store_batch_options,
        );
        if (!opts.bypass_ha_write_gate) {
            try self.mirrorHABatchMutationCommit(effective_req);
            try self.mirrorHAReplayPayloadCommit(replay_payload);
        }
        if (pending_identity_visibility_summary) |summary| {
            self.identity_visibility_summary_cache = summary;
            self.clearLiveDocSetCache();
            self.clearNonVisibleDocSetCache();
        }
        if (profile) |active_profile| {
            recordProfileNs(profile, &active_profile.store_write_ns, store_write_start_ns);
            active_profile.store_write_count += @intCast(store_writes.items.len);
            active_profile.store_delete_count += @intCast(delete_keys.items.len);
        }
        if (shouldAppendSplitDelta(self)) {
            const split_delta_start_ns = monotonicTimeNs();
            try self.core.appendSplitDelta(batch_timestamp_ns, store_writes.items, delete_keys.items);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.split_delta_ns, split_delta_start_ns);
        }

        if (!opts.suppress_derived_replay_append) {
            const append_replay_journal_start_ns = monotonicTimeNs();
            self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.append_replay_journal_ns, append_replay_journal_start_ns);
        }
        self.core.unlockApply();
        apply_mutex_held = false;
        if (opts.document_child_range_dispatcher) |dispatcher| {
            _ = try self.drainDocumentArtifactChildRangeOutbox(dispatcher, 0);
        }
        if (!opts.suppress_derived_replay_append) {
            var pressure_ctx = self.batchContext();
            const backlog_pressure_start_ns = monotonicTimeNs();
            try self.markPrecomputedEnrichmentAppliedForSync(effective_req.sync_level, sequence);
            try applyDerivedBacklogPressureContext(&pressure_ctx, sequence, effective_req.sync_level, sync_targets);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.backlog_pressure_ns, backlog_pressure_start_ns);
        }
        const wait_sync_start_ns = monotonicTimeNs();
        if (!opts.suppress_derived_replay_append and self.executor.hasWorkers()) {
            const notify_executor_start_ns = monotonicTimeNs();
            notifyExecutorForSyncLevelWithDenseBulkDeferral(self.async_context, self.executor, effective_req.sync_level, sequence, sync_targets);
            if (profile) |active_profile| recordProfileNs(profile, &active_profile.executor_notify_ns, notify_executor_start_ns);
            if (opts.wait_for_sync_level) {
                const sync_wait_start_ns = monotonicTimeNs();
                try self.waitForSyncLevel(effective_req.sync_level, sequence, sync_targets);
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.sync_wait_ns, sync_wait_start_ns);
            }
        } else {
            if (opts.wait_for_sync_level and syncLevelRequiresDerivedVisibility(effective_req.sync_level)) {
                const derived_apply_start_ns = monotonicTimeNs();
                if (effective_req.sync_level == .full_text) {
                    try applyDerivedBatchTargetsProfiled(self, materialized_derived_batch.?, sync_targets.full_text_indexes, profile);
                } else {
                    try applyDerivedBatchProfiled(self, materialized_derived_batch.?, profile);
                }
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.derived_apply_ns, derived_apply_start_ns);
            }
            if (opts.wait_for_sync_level) {
                const sync_wait_start_ns = monotonicTimeNs();
                try self.waitForSyncLevel(effective_req.sync_level, sequence, sync_targets);
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.sync_wait_ns, sync_wait_start_ns);
            }
        }
        if (opts.wait_for_sync_level and effective_req.sync_level == .full_index and self.text_merge_runtime == null) {
            try self.drainScheduledTextMerges();
        }
        if (profile) |active_profile| recordProfileNs(profile, &active_profile.wait_sync_ns, wait_sync_start_ns);
        if (!opts.suppress_derived_replay_append) {
            if (self.enrichment_runtime) |runtime| {
                const notify_enrichment_start_ns = monotonicTimeNs();
                runtime.notifySequence(sequence);
                if (profile) |active_profile| recordProfileNs(profile, &active_profile.notify_enrichment_ns, notify_enrichment_start_ns);
            }
            self.notifyResolverReplayRuntimes(sequence);
        }
    }

    /// Inject (or clear) the cross-shard entity-resolution candidate source on
    /// an already-open DB. The serving layer (managed write cache) calls this
    /// right after a DB is opened, since managed DBs open lazily and cannot
    /// thread the source through `OpenOptions`. No-op when this DB has no
    /// resolution runtime (e.g. read-only / status opens).
    pub fn setResolutionCandidateSource(self: *DB, src: ?resolution_runtime_mod.CandidateSource) void {
        self.resolution_candidate_source = src;
        if (self.resolution_runtime) |runtime| runtime.setCandidateSource(src);
    }

    /// Inject (or clear) the cross-shard entity sink on an already-open DB. The
    /// serving layer (managed write cache) calls this right after a DB is opened,
    /// since managed DBs open lazily and cannot thread the sink through
    /// `OpenOptions`. No-op when this DB has no promotion runtime.
    pub fn setEntitySink(self: *DB, sink: ?promotion_runtime_mod.EntitySink) void {
        self.entity_sink = sink;
        if (self.promotion_runtime) |runtime| runtime.setSink(sink);
    }

    /// Inject (or clear) the source-shard promotion owner on an already-open DB.
    /// Serving-layer managed DBs use this to keep follower raft apply from
    /// turning replay into public entity-table writes.
    pub fn setPromotionOwner(self: *DB, owner: ?promotion_runtime_mod.PromotionOwner) void {
        self.promotion_owner = owner;
        if (self.promotion_runtime) |runtime| runtime.setOwner(owner);
    }

    fn failIfIdentityOrdinalExhaustedForNewUpserts(self: *DB, doc_ids: []const []const u8) !void {
        if (doc_ids.len == 0) return;

        var txn = try self.core.store.beginProbeTxn();
        defer txn.abort();

        const raw_next = txn.get(internal_keys.identity_next_ordinal_key[0..]) catch |err| switch (err) {
            error.NotFound => return,
            else => return err,
        };
        if (raw_next.len != @sizeOf(doc_identity.DocOrdinal)) return error.InvalidDocIdentity;
        const next_ordinal = std.mem.readInt(doc_identity.DocOrdinal, raw_next[0..4], .big);
        if (next_ordinal != 0 and next_ordinal < std.math.maxInt(doc_identity.DocOrdinal)) return;

        var seen = std.StringHashMapUnmanaged(void).empty;
        defer seen.deinit(self.alloc);
        for (doc_ids) |doc_id| {
            if (seen.contains(doc_id)) continue;
            try seen.put(self.alloc, doc_id, {});
            if (try doc_identity.lookupOrdinalTxn(self.alloc, &txn, doc_id) != null) continue;
            return error.DocOrdinalExhausted;
        }
    }

    fn configureBulkIngestIdentityAllNewLocked(self: *DB) !void {
        self.clearBulkIngestIdentityAllNewLocked();
        if (!try self.primaryUserNamespaceIsEmptyLocked()) return;
        if (try doc_identity.loadAllNewTrustedStateForNamespace(self.core.store, self.core.identity_namespace)) |state| {
            self.bulk_ingest_identity_state = state;
            self.identity_visibility_summary_cache = state.visibility_summary;
            self.clearLiveDocSetCache();
            self.clearNonVisibleDocSetCache();
            self.bulk_ingest_identity_all_new = true;
        }
    }

    fn clearBulkIngestIdentityAllNewLocked(self: *DB) void {
        self.bulk_ingest_identity_all_new = false;
        self.bulk_ingest_identity_state.deinit(self.alloc);
        self.clearBulkIngestSeenDocKeysLocked();
    }

    fn clearBulkIngestSeenDocKeysLocked(self: *DB) void {
        var it = self.bulk_ingest_seen_doc_keys.keyIterator();
        while (it.next()) |key_ptr| self.alloc.free(@constCast(key_ptr.*));
        self.bulk_ingest_seen_doc_keys.clearRetainingCapacity();
    }

    fn clearActiveIndexRepairsLocked(self: *DB) void {
        var it = self.active_index_repairs.keyIterator();
        while (it.next()) |key_ptr| self.alloc.free(@constCast(key_ptr.*));
        self.active_index_repairs.clearRetainingCapacity();
    }

    const RepairShadowCleanupWork = struct {
        manager: *index_manager_mod.IndexManager,

        fn run(ptr: *anyopaque) anyerror!void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            while (true) {
                work.manager.cleanupInactiveRepairShadowRoots();
                if (work.manager.repair_cleanup_state.cmpxchgStrong(1, 0, .acq_rel, .acquire) == null) return;
                if (work.manager.repair_cleanup_state.cmpxchgStrong(2, 1, .acq_rel, .acquire) == null) continue;
            }
        }

        fn deinit(ptr: *anyopaque) void {
            const work: *@This() = @ptrCast(@alignCast(ptr));
            std.heap.page_allocator.destroy(work);
        }
    };

    fn scheduleInactiveRepairShadowCleanup(self: *DB) void {
        if (self.core.index_manager.repair_cleanup_state.cmpxchgStrong(0, 1, .acq_rel, .acquire) != null) {
            _ = self.core.index_manager.repair_cleanup_state.cmpxchgStrong(1, 2, .acq_rel, .acquire);
            return;
        }
        const work = std.heap.page_allocator.create(RepairShadowCleanupWork) catch {
            self.core.index_manager.repair_cleanup_state.store(0, .release);
            return;
        };
        work.* = .{ .manager = self.core.index_manager };
        self.backend_runtime.durable_jobs.submit(.{
            .owner_id = self.repair_cleanup_owner_id,
            .class = .cleanup,
            .ptr = work,
            .run = RepairShadowCleanupWork.run,
            .deinit = RepairShadowCleanupWork.deinit,
        }) catch |err| {
            std.heap.page_allocator.destroy(work);
            self.core.index_manager.repair_cleanup_state.store(0, .release);
            std.log.warn("deferred index-generation cleanup was not scheduled err={s}", .{@errorName(err)});
        };
    }

    fn beginIndexRepairLease(self: *DB, index_name: []const u8) !bool {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        if (self.active_index_repairs.contains(index_name)) return false;
        const owned = try self.alloc.dupe(u8, index_name);
        errdefer self.alloc.free(owned);
        try self.active_index_repairs.put(self.alloc, owned, false);
        return true;
    }

    fn activeIndexRepairCancellationRequested(self: *DB, index_name: []const u8) bool {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        return self.active_index_repairs.get(index_name) orelse false;
    }

    fn requestActiveIndexRepairCancellation(self: *DB, index_name: []const u8) bool {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        const requested = self.active_index_repairs.getPtr(index_name) orelse return false;
        requested.* = true;
        return true;
    }

    fn endIndexRepairLease(self: *DB, index_name: []const u8) void {
        lockAtomic(&self.index_repair_mutex);
        defer self.index_repair_mutex.unlock();
        if (self.active_index_repairs.fetchRemove(index_name)) |removed| {
            self.alloc.free(@constCast(removed.key));
        }
    }

    fn primaryUserNamespaceIsEmptyLocked(self: *DB) !bool {
        var txn = try self.core.store.beginCurrentScanTxn();
        defer txn.abort();
        var cur = try txn.openCursor();
        defer cur.close();

        const lower = [_]u8{internal_keys.user_namespace};
        const first = (try cur.seekAtOrAfter(lower[0..])) orelse return true;
        return first.key.len == 0 or first.key[0] != internal_keys.user_namespace;
    }

    fn rememberBulkIngestAllNewIdentityUpserts(self: *DB, doc_ids: []const []const u8) !bool {
        var batch_seen = std.StringHashMapUnmanaged(void).empty;
        defer batch_seen.deinit(self.alloc);
        for (doc_ids) |doc_id| {
            if (self.bulk_ingest_seen_doc_keys.contains(doc_id)) return false;
            if (batch_seen.contains(doc_id)) return false;
            try batch_seen.put(self.alloc, doc_id, {});
        }

        for (doc_ids) |doc_id| {
            const owned = try self.alloc.dupe(u8, doc_id);
            errdefer self.alloc.free(owned);
            try self.bulk_ingest_seen_doc_keys.put(self.alloc, owned, {});
        }
        return true;
    }

    fn identityUpsertStoreWritesAreNew(write_indexes: []const usize, overwritten_flags: []const bool) bool {
        for (write_indexes) |write_index| {
            if (write_index >= overwritten_flags.len) return false;
            if (overwritten_flags[write_index]) return false;
        }
        return true;
    }

    fn CoalescedKeyValueRequest(comptime T: type) type {
        return struct {
            const Entry = struct {
                key: []const u8,
                value: ?[]const u8 = null,
                kind: enum { write, delete },
                owned_key: bool = false,
                owned_value: bool = false,
            };

            entries: []Entry = &.{},
            writes: []T = &.{},
            deletes: [][]const u8 = &.{},

            fn deinit(self: *@This(), alloc: Allocator) void {
                for (self.entries) |entry| {
                    if (entry.owned_key) alloc.free(@constCast(entry.key));
                    if (entry.owned_value) alloc.free(@constCast(entry.value.?));
                }
                if (self.entries.len > 0) alloc.free(self.entries);
                if (self.writes.len > 0) alloc.free(self.writes);
                if (self.deletes.len > 0) alloc.free(self.deletes);
                self.* = .{};
            }
        };
    }

    const BulkIngestCoalescer = struct {
        const Stats = struct {
            active_session: std.atomic.Value(u8) = .init(0),
            staged_keys: AtomicU64 = .init(0),
            stage_batches: AtomicU64 = .init(0),
            stage_writes: AtomicU64 = .init(0),
            stage_deletes: AtomicU64 = .init(0),
            stage_transforms: AtomicU64 = .init(0),
            flush_calls: AtomicU64 = .init(0),
            flushed_keys: AtomicU64 = .init(0),

            fn snapshot(self: *const @This()) types.BulkCoalescingStats {
                return .{
                    .active_session = self.active_session.load(.monotonic) != 0,
                    .staged_keys = self.staged_keys.load(.monotonic),
                    .stage_batches = self.stage_batches.load(.monotonic),
                    .stage_writes = self.stage_writes.load(.monotonic),
                    .stage_deletes = self.stage_deletes.load(.monotonic),
                    .stage_transforms = self.stage_transforms.load(.monotonic),
                    .flush_calls = self.flush_calls.load(.monotonic),
                    .flushed_keys = self.flushed_keys.load(.monotonic),
                };
            }
        };

        const Entry = struct {
            key: []u8,
            value: ?[]u8 = null,
            kind: enum { write, delete },
        };

        const RequestView = struct {
            writes: []types.BatchWrite = &.{},
            deletes: [][]const u8 = &.{},

            fn deinit(self: @This(), alloc: Allocator) void {
                if (self.writes.len > 0) alloc.free(self.writes);
                if (self.deletes.len > 0) alloc.free(self.deletes);
            }
        };

        active: bool = false,
        entries: std.ArrayListUnmanaged(Entry) = .empty,
        positions: std.StringHashMapUnmanaged(usize) = .empty,
        stats: Stats = .{},

        fn begin(self: *@This()) void {
            self.active = true;
            self.stats.active_session.store(1, .monotonic);
        }

        fn deinit(self: *@This(), alloc: Allocator) void {
            self.clear(alloc);
            self.entries.deinit(alloc);
            self.positions.deinit(alloc);
            self.* = .{};
        }

        fn clear(self: *@This(), alloc: Allocator) void {
            self.resetPending(alloc);
            self.active = false;
            self.stats.active_session.store(0, .monotonic);
        }

        fn resetPending(self: *@This(), alloc: Allocator) void {
            for (self.entries.items) |entry| {
                alloc.free(entry.key);
                if (entry.value) |value| alloc.free(value);
            }
            self.entries.clearRetainingCapacity();
            self.positions.clearRetainingCapacity();
            self.stats.staged_keys.store(0, .monotonic);
        }

        fn hasPending(self: *const @This()) bool {
            return self.entries.items.len > 0;
        }

        fn snapshotRequestView(self: *const @This(), alloc: Allocator) !RequestView {
            var result = RequestView{};
            errdefer result.deinit(alloc);

            var write_count: usize = 0;
            var delete_count: usize = 0;
            for (self.entries.items) |entry| {
                switch (entry.kind) {
                    .write => write_count += 1,
                    .delete => delete_count += 1,
                }
            }

            if (write_count > 0) result.writes = try alloc.alloc(types.BatchWrite, write_count);
            if (delete_count > 0) result.deletes = try alloc.alloc([]const u8, delete_count);

            var write_index: usize = 0;
            var delete_index: usize = 0;
            for (self.entries.items) |entry| {
                switch (entry.kind) {
                    .write => {
                        result.writes[write_index] = .{
                            .key = entry.key,
                            .value = entry.value.?,
                        };
                        write_index += 1;
                    },
                    .delete => {
                        result.deletes[delete_index] = entry.key;
                        delete_index += 1;
                    },
                }
            }
            return result;
        }

        fn stageBatch(self: *@This(), db: *DB, req: types.BatchRequest) !void {
            std.debug.assert(self.active);
            _ = self.stats.stage_batches.fetchAdd(1, .monotonic);
            _ = self.stats.stage_writes.fetchAdd(@intCast(req.writes.len), .monotonic);
            _ = self.stats.stage_deletes.fetchAdd(@intCast(req.deletes.len), .monotonic);
            _ = self.stats.stage_transforms.fetchAdd(@intCast(req.transforms.len), .monotonic);

            for (req.writes) |write| {
                try self.stageWrite(db.alloc, write.key, write.value);
            }
            for (req.deletes) |key| {
                try self.stageDelete(db.alloc, key);
            }
            for (req.transforms) |transform| {
                try self.stageTransform(db, transform);
            }
            self.stats.staged_keys.store(@intCast(self.entries.items.len), .monotonic);
        }

        fn stageWrite(self: *@This(), alloc: Allocator, key: []const u8, value: []const u8) !void {
            const gop = try self.positions.getOrPut(alloc, key);
            if (!gop.found_existing) {
                const owned_key = try alloc.dupe(u8, key);
                errdefer alloc.free(owned_key);
                const owned_value = try alloc.dupe(u8, value);
                errdefer alloc.free(owned_value);
                gop.key_ptr.* = owned_key;
                gop.value_ptr.* = self.entries.items.len;
                try self.entries.append(alloc, .{
                    .key = owned_key,
                    .value = owned_value,
                    .kind = .write,
                });
                return;
            }

            const entry = &self.entries.items[gop.value_ptr.*];
            if (entry.value) |existing| alloc.free(existing);
            entry.value = try alloc.dupe(u8, value);
            entry.kind = .write;
        }

        fn stageDelete(self: *@This(), alloc: Allocator, key: []const u8) !void {
            const gop = try self.positions.getOrPut(alloc, key);
            if (!gop.found_existing) {
                const owned_key = try alloc.dupe(u8, key);
                errdefer alloc.free(owned_key);
                gop.key_ptr.* = owned_key;
                gop.value_ptr.* = self.entries.items.len;
                try self.entries.append(alloc, .{
                    .key = owned_key,
                    .kind = .delete,
                });
                return;
            }

            const entry = &self.entries.items[gop.value_ptr.*];
            if (entry.value) |existing| {
                alloc.free(existing);
                entry.value = null;
            }
            entry.kind = .delete;
        }

        fn stageTransform(self: *@This(), db: *DB, transform: types.DocumentTransform) !void {
            const existing = if (self.positions.get(transform.key)) |entry_index|
                switch (self.entries.items[entry_index].kind) {
                    .write => self.entries.items[entry_index].value,
                    .delete => null,
                }
            else
                try db.get(db.alloc, transform.key);
            defer if (self.positions.get(transform.key) == null) {
                if (existing) |body| db.alloc.free(body);
            };

            const resolved = try transform_mod.resolveDocumentTransform(db.alloc, existing, transform) orelse return;
            errdefer db.alloc.free(resolved);
            try self.stageWriteOwned(db.alloc, transform.key, resolved);
        }

        fn stageWriteOwned(self: *@This(), alloc: Allocator, key: []const u8, owned_value: []u8) !void {
            const gop = try self.positions.getOrPut(alloc, key);
            if (!gop.found_existing) {
                const owned_key = try alloc.dupe(u8, key);
                errdefer alloc.free(owned_key);
                gop.key_ptr.* = owned_key;
                gop.value_ptr.* = self.entries.items.len;
                try self.entries.append(alloc, .{
                    .key = owned_key,
                    .value = owned_value,
                    .kind = .write,
                });
                return;
            }

            const entry = &self.entries.items[gop.value_ptr.*];
            if (entry.value) |existing| alloc.free(existing);
            entry.value = owned_value;
            entry.kind = .write;
        }
    };

    fn resetCoalescedEntryToDelete(comptime T: type, entry: *CoalescedKeyValueRequest(T).Entry) void {
        if (entry.owned_value) {
            // Caller frees previous owned value before switching the entry.
            entry.owned_value = false;
        }
        entry.value = null;
        entry.kind = .delete;
    }

    fn setCoalescedEntryToBorrowedWrite(comptime T: type, entry: *CoalescedKeyValueRequest(T).Entry, write: T) void {
        entry.key = write.key;
        entry.value = write.value;
        entry.kind = .write;
        entry.owned_key = false;
        entry.owned_value = false;
    }

    fn setCoalescedEntryToOwnedWrite(
        comptime T: type,
        alloc: Allocator,
        entry: *CoalescedKeyValueRequest(T).Entry,
        key: []const u8,
        value: []u8,
    ) !void {
        if (!entry.owned_key) {
            entry.key = try alloc.dupe(u8, key);
            entry.owned_key = true;
        }
        entry.value = value;
        entry.kind = .write;
        entry.owned_value = true;
    }

    fn coalesceKeyValueRequest(
        self: *DB,
        comptime T: type,
        writes: []const T,
        deletes: []const []const u8,
        transforms: []const types.DocumentTransform,
    ) !CoalescedKeyValueRequest(T) {
        var result = CoalescedKeyValueRequest(T){};
        var order = std.ArrayListUnmanaged(CoalescedKeyValueRequest(T).Entry).empty;
        errdefer {
            result.entries = order.items;
            order.items = &.{};
            order.capacity = 0;
            result.deinit(self.alloc);
        }
        defer order.deinit(self.alloc);

        var positions = std.StringHashMapUnmanaged(usize){};
        defer positions.deinit(self.alloc);

        for (writes) |write| {
            const gop = try positions.getOrPut(self.alloc, write.key);
            if (!gop.found_existing) {
                gop.value_ptr.* = order.items.len;
                try order.append(self.alloc, .{
                    .key = write.key,
                    .value = write.value,
                    .kind = .write,
                });
                continue;
            }
            const entry = &order.items[gop.value_ptr.*];
            if (entry.owned_value) self.alloc.free(@constCast(entry.value.?));
            if (entry.owned_key) self.alloc.free(@constCast(entry.key));
            setCoalescedEntryToBorrowedWrite(T, entry, write);
        }

        for (deletes) |key| {
            const gop = try positions.getOrPut(self.alloc, key);
            if (!gop.found_existing) {
                gop.value_ptr.* = order.items.len;
                try order.append(self.alloc, .{
                    .key = key,
                    .kind = .delete,
                });
                continue;
            }
            const entry = &order.items[gop.value_ptr.*];
            if (entry.owned_value) self.alloc.free(@constCast(entry.value.?));
            entry.owned_value = false;
            resetCoalescedEntryToDelete(T, entry);
        }

        for (transforms) |transform| {
            const maybe_index = positions.get(transform.key);
            const base_json = blk: {
                if (maybe_index) |entry_index| {
                    const entry = order.items[entry_index];
                    break :blk if (entry.kind == .write) entry.value.? else null;
                }
                break :blk try self.get(self.alloc, transform.key);
            };
            defer if (maybe_index == null) {
                if (base_json) |body| self.alloc.free(body);
            };

            const resolved = try transform_mod.resolveDocumentTransform(self.alloc, base_json, transform) orelse {
                if (maybe_index == null) continue;
                const entry = order.items[maybe_index.?];
                if (entry.kind == .delete) continue;
                continue;
            };
            errdefer self.alloc.free(resolved);

            const gop = try positions.getOrPut(self.alloc, transform.key);
            if (!gop.found_existing) {
                gop.value_ptr.* = order.items.len;
                try order.append(self.alloc, .{
                    .key = try self.alloc.dupe(u8, transform.key),
                    .value = resolved,
                    .kind = .write,
                    .owned_key = true,
                    .owned_value = true,
                });
                continue;
            }

            const entry = &order.items[gop.value_ptr.*];
            if (entry.owned_value) self.alloc.free(@constCast(entry.value.?));
            try setCoalescedEntryToOwnedWrite(T, self.alloc, entry, transform.key, resolved);
        }

        var write_count: usize = 0;
        var delete_count: usize = 0;
        for (order.items) |entry| {
            switch (entry.kind) {
                .write => write_count += 1,
                .delete => delete_count += 1,
            }
        }

        const final_entries = try order.toOwnedSlice(self.alloc);
        result.entries = final_entries;
        if (write_count > 0) result.writes = try self.alloc.alloc(T, write_count);
        if (delete_count > 0) result.deletes = try self.alloc.alloc([]const u8, delete_count);

        var write_index: usize = 0;
        var delete_index: usize = 0;
        for (final_entries) |entry| {
            switch (entry.kind) {
                .write => {
                    result.writes[write_index] = .{
                        .key = entry.key,
                        .value = entry.value.?,
                    };
                    write_index += 1;
                },
                .delete => {
                    result.deletes[delete_index] = entry.key;
                    delete_index += 1;
                },
            }
        }
        return result;
    }

    fn flushBulkIngestCoalescerWithSyncLevel(self: *DB, sync_level: types.SyncLevel, profile: ?*BatchProfile) anyerror!void {
        if (!self.bulk_ingest_coalescer.active or !self.bulk_ingest_coalescer.hasPending()) return;
        _ = self.bulk_ingest_coalescer.stats.flush_calls.fetchAdd(1, .monotonic);
        _ = self.bulk_ingest_coalescer.stats.flushed_keys.fetchAdd(@intCast(self.bulk_ingest_coalescer.entries.items.len), .monotonic);

        lockApply(self);
        var view = try self.bulk_ingest_coalescer.snapshotRequestView(self.alloc);
        self.core.unlockApply();
        defer view.deinit(self.alloc);

        self.flushing_bulk_ingest_coalescer = true;
        defer self.flushing_bulk_ingest_coalescer = false;

        try self.batchInternal(.{
            .writes = view.writes,
            .deletes = view.deletes,
            .sync_level = sync_level,
        }, profile, .{ .store_batch_options = .{ .mode = .bulk_ingest, .defer_commit_flush = true } });

        lockApply(self);
        defer self.core.unlockApply();
        self.bulk_ingest_coalescer.resetPending(self.alloc);
        self.bulk_ingest_coalescer.active = true;
    }

    pub fn get(self: *DB, alloc: Allocator, key: []const u8) !?[]u8 {
        const store_key = try encodeStoreLookupKeyAlloc(alloc, key);
        defer alloc.free(store_key);
        return try self.core.getStoreValue(alloc, store_key);
    }

    pub fn getGroupCreatedAtMillis(self: *DB, alloc: Allocator, group_id: u64) !?u64 {
        const key = try groupCreatedAtMetadataKeyAlloc(alloc, group_id);
        defer alloc.free(key);
        const raw = try self.get(alloc, key) orelse return null;
        defer alloc.free(raw);
        return try std.fmt.parseInt(u64, raw, 10);
    }

    pub fn ensureGroupCreatedAtMillis(self: *DB, alloc: Allocator, group_id: u64, now_ms: u64) !u64 {
        if (try self.getGroupCreatedAtMillis(alloc, group_id)) |created_at_millis| return created_at_millis;

        const key = try groupCreatedAtMetadataKeyAlloc(alloc, group_id);
        defer alloc.free(key);
        const encoded = try std.fmt.allocPrint(alloc, "{d}", .{now_ms});
        defer alloc.free(encoded);

        try self.batch(.{
            .writes = &.{
                .{
                    .key = key,
                    .value = encoded,
                },
            },
        });
        return now_ms;
    }

    pub fn getArtifact(self: *DB, alloc: Allocator, artifact_id: []const u8) !?types.ArtifactRecord {
        var artifact_ref = (try artifact_ids.decodeArtifactPublicIdAlloc(alloc, artifact_id)) orelse return error.InvalidArgument;
        errdefer artifact_ref.deinit(alloc);

        const internal_key = try artifact_ids.internalKeyForArtifactRefAlloc(alloc, artifact_ref);
        defer alloc.free(internal_key);

        const value = try self.core.getStoreValue(alloc, internal_key) orelse return null;
        errdefer alloc.free(value);

        return .{
            .id = try alloc.dupe(u8, artifact_id),
            .value = value,
            .artifact_ref = artifact_ref,
        };
    }

    pub fn getDocumentArtifactManifest(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !?types.DocumentArtifactManifest {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const manifest_key = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", artifact_name);
        defer alloc.free(manifest_key);
        const manifest = try self.core.getStoreValue(alloc, manifest_key) orelse return null;
        errdefer alloc.free(manifest);

        const state_key = try assetStateKeyAlloc(alloc, doc_key, artifact_name);
        defer alloc.free(state_key);
        const state = self.core.getStoreValue(alloc, state_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        errdefer if (state) |value| alloc.free(value);

        return try documentArtifactManifestFromJsonAlloc(alloc, doc_key, artifact_name, manifest, state);
    }

    pub fn listDocumentArtifactManifests(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
    ) !types.DocumentArtifactManifestList {
        lockApplyShared(self);
        defer self.core.unlockApplyShared();

        const prefix = try internal_keys.artifactTypePrefixAlloc(alloc, doc_key, "asset");
        defer alloc.free(prefix);
        const rows = try self.core.scanStorePrefix(alloc, prefix);
        defer docstore_mod.DocStore.freeResults(alloc, rows);

        var artifacts = std.ArrayListUnmanaged(types.DocumentArtifactManifest).empty;
        errdefer {
            for (artifacts.items) |*artifact| artifact.deinit(alloc);
            artifacts.deinit(alloc);
        }

        for (rows) |row| {
            var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, row.key)) orelse continue;
            defer artifact_ref.deinit(alloc);
            if (artifact_ref.kind != .asset) continue;
            if (artifact_ref.unit_id != null) continue;
            if (!std.mem.eql(u8, artifact_ref.document_id, doc_key)) continue;

            const state_key = try assetStateKeyAlloc(alloc, doc_key, artifact_ref.name);
            defer alloc.free(state_key);
            const state = self.core.getStoreValue(alloc, state_key) catch |err| switch (err) {
                error.NotFound => null,
                else => return err,
            };
            errdefer if (state) |value| alloc.free(value);

            const manifest_json = try alloc.dupe(u8, row.value);
            errdefer alloc.free(manifest_json);
            try artifacts.append(
                alloc,
                try documentArtifactManifestFromJsonAlloc(alloc, doc_key, artifact_ref.name, manifest_json, state),
            );
        }

        return .{
            .document_id = try alloc.dupe(u8, doc_key),
            .artifacts = try artifacts.toOwnedSlice(alloc),
        };
    }

    pub fn updateDocumentArtifactChildRangePlacement(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
        update: types.DocumentArtifactChildRangePlacementUpdate,
    ) !bool {
        if (openModeRequiresReadOnlyBackends(self.open_mode)) return error.ReadOnly;
        try self.enforceHAWriteGate();
        try self.executor.failIfUnhealthy();

        lockApply(self);
        var apply_mutex_held = true;
        errdefer if (apply_mutex_held) self.core.unlockApply();

        const manifest_key = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", artifact_name);
        defer alloc.free(manifest_key);
        const manifest = try self.core.getStoreValue(alloc, manifest_key) orelse {
            self.core.unlockApply();
            apply_mutex_held = false;
            return false;
        };
        defer alloc.free(manifest);

        var arena = std.heap.ArenaAllocator.init(alloc);
        defer arena.deinit();
        const arena_alloc = arena.allocator();
        var manifest_value = try std.json.parseFromSliceLeaky(std.json.Value, arena_alloc, manifest, .{ .allocate = .alloc_always });
        if (manifest_value != .object) return error.InvalidArgument;
        const child_ranges = manifest_value.object.getPtr("child_ranges") orelse return error.InvalidArgument;
        if (child_ranges.* != .array) return error.InvalidArgument;

        var changed = false;
        for (child_ranges.array.items) |*item| {
            if (item.* != .object) return error.InvalidArgument;
            const range_id = item.object.get("range_id") orelse return error.InvalidArgument;
            if (range_id != .string) return error.InvalidArgument;
            if (!std.mem.eql(u8, range_id.string, update.range_id)) continue;

            try putLeakyJsonStringField(arena_alloc, &item.object, "placement", update.placement);
            if (update.owner_group_id) |owner_group_id| try putLeakyJsonU64Field(arena_alloc, &item.object, "owner_group_id", owner_group_id);
            if (update.placement_generation) |placement_generation| try putLeakyJsonU64Field(arena_alloc, &item.object, "placement_generation", placement_generation);
            if (update.route_status) |route_status| try putLeakyJsonStringField(arena_alloc, &item.object, "route_status", route_status);
            if (update.split_eligible) |split_eligible| try item.object.put(arena_alloc, "split_eligible", .{ .bool = split_eligible });
            changed = true;
            break;
        }

        if (!changed) {
            self.core.unlockApply();
            apply_mutex_held = false;
            return false;
        }

        const updated_manifest = try std.json.Stringify.valueAlloc(alloc, manifest_value, .{});
        defer alloc.free(updated_manifest);

        const sequence = self.core.reserveDerivedAppendSequence();
        const changed_artifact_keys = [_][]const u8{manifest_key};
        const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), .{
            .sequence = sequence,
            .changed_artifact_keys = changed_artifact_keys[0..],
        }, sequence);
        defer alloc.free(replay_payload);

        const writes = [_]docstore_mod.KVPair{.{
            .key = manifest_key,
            .value = updated_manifest,
        }};
        try self.core.store.putBatchWithReplay(self.backend_runtime.io(), writes[0..], &.{}, .{
            .sequence = sequence,
            .payload = replay_payload,
        });
        self.mirrorHAReplayPayloadBestEffort(replay_payload);
        self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
        self.core.unlockApply();
        apply_mutex_held = false;

        if (self.executor.hasWorkers()) {
            self.executor.forceSequence(sequence);
        } else {
            self.executor.notifySequence(sequence);
        }
        self.notifyResolverReplayRuntimes(sequence);
        return true;
    }

    pub fn reprocessDocumentArtifact(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !bool {
        var cfg = (try self.getEnrichment(alloc, .asset, artifact_name)) orelse return false;
        defer cfg.deinit(alloc);
        var producer_cfg = try asset_producer_mod.parseProducerConfig(alloc, cfg.producer_json);
        defer producer_cfg.deinit(alloc);
        if (producer_cfg.type != .document_extraction) return error.InvalidArgument;

        const value = try self.get(alloc, doc_key) orelse return false;
        defer alloc.free(value);

        const writes = [_]types.BatchWrite{.{ .key = doc_key, .value = value }};
        const force_artifacts = [_][]const u8{artifact_name};
        try self.batchInternal(.{
            .writes = &writes,
            .sync_level = .full_index,
        }, null, .{
            .force_generated_artifact_names = &force_artifacts,
        });
        return true;
    }

    pub fn reprocessDocumentEmbeddingArtifact(
        self: *DB,
        alloc: Allocator,
        doc_key: []const u8,
        artifact_name: []const u8,
    ) !bool {
        const issue = types.ArtifactRepairIssue{
            .artifact_kind = .embedding,
            .doc_key = doc_key,
            .artifact_name = artifact_name,
        };
        return self.reprocessEmbeddingArtifactIssue(alloc, issue) catch |err| switch (err) {
            error.NotFound => false,
            else => return err,
        };
    }

    fn reprocessEmbeddingArtifactIssue(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
    ) !bool {
        var cfg = (try self.getEnrichment(alloc, .embedding, issue.artifact_name)) orelse return false;
        defer cfg.deinit(alloc);

        const source_doc_key = if (issue.parent_doc_key.len > 0) issue.parent_doc_key else issue.doc_key;
        const value = try self.get(alloc, source_doc_key) orelse return error.NotFound;
        defer alloc.free(value);

        const writes = [_]types.BatchWrite{.{ .key = source_doc_key, .value = value }};
        const force_artifacts = [_][]const u8{issue.artifact_name};
        try self.batchInternal(.{
            .writes = &writes,
            .sync_level = .full_index,
        }, null, .{
            .force_generated_artifact_names = &force_artifacts,
        });
        return true;
    }

    fn repairIssueKeyForIssueAlloc(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) ![]u8 {
        _ = self;
        return try artifactRepairIssueKeyForIssueAlloc(alloc, issue);
    }

    fn repairIssueKindKeyForIssueAlloc(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) ![]u8 {
        _ = self;
        return try artifactRepairIssueKindKeyForIssueAlloc(alloc, issue);
    }

    fn encodeArtifactRepairIssueAlloc(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) ![]u8 {
        _ = self;
        return try encodeArtifactRepairIssueValueAlloc(alloc, issue);
    }

    fn decodeArtifactRepairIssueAlloc(self: *DB, alloc: Allocator, raw: []const u8) !types.ArtifactRepairIssue {
        _ = self;
        return try decodeArtifactRepairIssueValueAlloc(alloc, raw);
    }

    fn loadArtifactRepairIssueByKey(self: *DB, alloc: Allocator, key: []const u8) !?types.ArtifactRepairIssue {
        return try loadArtifactRepairIssueFromStoreByKey(alloc, self.core.store, key);
    }

    fn loadArtifactRepairSummaryCountByKey(self: *DB, alloc: Allocator, key: []const u8) !?u64 {
        const raw = self.core.store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return null,
            else => return err,
        };
        defer alloc.free(raw);
        if (raw.len != @sizeOf(u64)) return error.InvalidArtifactPayload;
        return std.mem.readInt(u64, raw[0..8], .little);
    }

    fn artifactRepairSummaryReady(self: *DB, alloc: Allocator) !bool {
        const ready_key = try internal_keys.artifactRepairSummaryReadyKeyAlloc(alloc);
        defer alloc.free(ready_key);
        const ready = self.core.store.get(alloc, ready_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        alloc.free(ready);
        return true;
    }

    fn loadArtifactRepairSummaryCountOrScan(
        self: *DB,
        alloc: Allocator,
        key: []const u8,
    ) !u64 {
        if (try self.artifactRepairSummaryReady(alloc)) {
            return (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) orelse 0;
        }
        return (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) orelse 0;
    }

    fn scanArtifactRepairIssueCountBounded(self: *DB, alloc: Allocator, index_name: ?[]const u8) !u64 {
        const prefix = try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);

        const ScanState = struct {
            const scan_limit: usize = 1024;

            alloc: Allocator,
            index_name: ?[]const u8,
            count: u64 = 0,
            scanned: usize = 0,

            fn scanEntry(ctx: ?*anyopaque, _: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                var issue = try decodeArtifactRepairIssueValueAlloc(state.alloc, value);
                defer issue.deinit(state.alloc);
                state.scanned += 1;
                if (state.index_name == null or std.mem.eql(u8, issue.index_name, state.index_name.?)) {
                    state.count += 1;
                }
                if (state.scanned >= scan_limit) return .stop;
                return .@"continue";
            }
        };

        var state = ScanState{ .alloc = alloc, .index_name = index_name };
        try self.core.store.scanWithContext(prefix, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);
        return state.count;
    }

    const ArtifactRepairSummarySnapshot = struct {
        ready: bool,
        count: u64,
        repair_scan_count: u64 = 0,
    };

    fn artifactRepairSummaryRootSnapshot(self: *DB, alloc: Allocator) !ArtifactRepairSummarySnapshot {
        const ready = try self.artifactRepairSummaryReady(alloc);
        const key = if (ready)
            try internal_keys.artifactRepairSummaryRootKeyAlloc(alloc)
        else
            try internal_keys.artifactRepairSummaryRebuildRootKeyAlloc(alloc);
        defer alloc.free(key);
        return .{
            .ready = ready,
            .count = (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) orelse if (ready) 0 else try self.scanArtifactRepairIssueCountBounded(alloc, null),
        };
    }

    fn artifactRepairSummaryRootCount(self: *DB, alloc: Allocator) !u64 {
        return (try self.artifactRepairSummaryRootSnapshot(alloc)).count;
    }

    fn artifactRepairSummaryIndexSnapshot(self: *DB, alloc: Allocator, index_name: []const u8, ready: bool) !ArtifactRepairSummarySnapshot {
        const key = if (ready)
            try internal_keys.artifactRepairSummaryIndexKeyAlloc(alloc, index_name)
        else
            try internal_keys.artifactRepairSummaryRebuildIndexKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        if (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) |count| {
            return .{ .ready = ready, .count = count };
        }
        if (ready) return .{ .ready = true, .count = 0 };
        const scanned_count = try self.scanArtifactRepairIssueCountBounded(alloc, index_name);
        return .{ .ready = false, .count = scanned_count, .repair_scan_count = scanned_count };
    }

    const ArtifactRepairIndexFallbackCounts = struct {
        alloc: Allocator,
        counts: std.StringHashMapUnmanaged(u64) = .empty,
        loaded: bool = false,

        fn deinit(self: *@This()) void {
            var it = self.counts.iterator();
            while (it.next()) |entry| self.alloc.free(entry.key_ptr.*);
            self.counts.deinit(self.alloc);
        }
    };

    fn ensureArtifactRepairIndexFallbackCounts(self: *DB, alloc: Allocator, fallback: *ArtifactRepairIndexFallbackCounts) !void {
        if (fallback.loaded) return;
        fallback.loaded = true;

        const prefix = try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);

        const ScanState = struct {
            const scan_limit: usize = 1024;

            alloc: Allocator,
            counts: *std.StringHashMapUnmanaged(u64),
            scanned: usize = 0,

            fn scanEntry(ctx: ?*anyopaque, _: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                var issue = try decodeArtifactRepairIssueValueAlloc(state.alloc, value);
                defer issue.deinit(state.alloc);
                state.scanned += 1;
                const result = try state.counts.getOrPut(state.alloc, issue.index_name);
                if (!result.found_existing) {
                    result.key_ptr.* = try state.alloc.dupe(u8, issue.index_name);
                    result.value_ptr.* = 0;
                }
                result.value_ptr.* += 1;
                if (state.scanned >= scan_limit) return .stop;
                return .@"continue";
            }
        };

        var state = ScanState{ .alloc = alloc, .counts = &fallback.counts };
        try self.core.store.scanWithContext(prefix, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);
    }

    fn artifactRepairSummaryIndexSnapshotForStats(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        ready: bool,
        fallback: *ArtifactRepairIndexFallbackCounts,
    ) !ArtifactRepairSummarySnapshot {
        if (ready) return try self.artifactRepairSummaryIndexSnapshot(alloc, index_name, true);

        const key = try internal_keys.artifactRepairSummaryRebuildIndexKeyAlloc(alloc, index_name);
        defer alloc.free(key);
        if (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) |count| {
            return .{ .ready = false, .count = count };
        }

        try self.ensureArtifactRepairIndexFallbackCounts(alloc, fallback);
        const scanned_count = fallback.counts.get(index_name) orelse 0;
        return .{ .ready = false, .count = scanned_count, .repair_scan_count = scanned_count };
    }

    fn artifactRepairSummaryIndexCount(self: *DB, alloc: Allocator, index_name: []const u8) !u64 {
        return (try self.artifactRepairSummaryIndexSnapshot(alloc, index_name, try self.artifactRepairSummaryReady(alloc))).count;
    }

    fn appendArtifactRepairSummaryWrite(
        self: *DB,
        alloc: Allocator,
        writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
        deletes: *std.ArrayListUnmanaged([]const u8),
        key: []const u8,
        delta: i64,
    ) !void {
        const existing = (try self.loadArtifactRepairSummaryCountByKey(alloc, key)) orelse 0;
        const updated = if (delta >= 0) existing +| @as(u64, @intCast(delta)) else existing -| @as(u64, @intCast(-delta));
        if (updated == 0) {
            try deletes.append(alloc, key);
            return;
        }
        const value = try alloc.alloc(u8, @sizeOf(u64));
        std.mem.writeInt(u64, value[0..8], updated, .little);
        try writes.append(alloc, .{ .key = key, .value = value });
    }

    fn appendKeysForPrefixDelete(
        self: *DB,
        alloc: Allocator,
        deletes: *std.ArrayListUnmanaged([]const u8),
        owned_keys: *std.ArrayListUnmanaged([]const u8),
        prefix: []const u8,
    ) !void {
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);
        const ScanState = struct {
            alloc: Allocator,
            deletes: *std.ArrayListUnmanaged([]const u8),
            owned_keys: *std.ArrayListUnmanaged([]const u8),

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                const key_copy = try state.alloc.dupe(u8, key);
                errdefer state.alloc.free(key_copy);
                const owned_len = state.owned_keys.items.len;
                try state.owned_keys.append(state.alloc, key_copy);
                errdefer state.owned_keys.shrinkRetainingCapacity(owned_len);
                try state.deletes.append(state.alloc, key_copy);
                return .@"continue";
            }
        };
        var state = ScanState{ .alloc = alloc, .deletes = deletes, .owned_keys = owned_keys };
        try self.core.store.scanWithContext(prefix, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);
    }

    fn appendArtifactRepairSummaryRebuildInvalidation(
        self: *DB,
        alloc: Allocator,
        writes: ?*std.ArrayListUnmanaged(docstore_mod.KVPair),
        deletes: *std.ArrayListUnmanaged([]const u8),
        owned_keys: *std.ArrayListUnmanaged([]const u8),
    ) !void {
        const progress_key = try internal_keys.artifactRepairSummaryProgressKeyAlloc(alloc);
        errdefer alloc.free(progress_key);
        const owned_len = owned_keys.items.len;
        try owned_keys.append(alloc, progress_key);
        errdefer owned_keys.shrinkRetainingCapacity(owned_len);
        if (writes) |out| {
            const dirty_value = try alloc.dupe(u8, artifact_repair_summary_dirty_marker);
            errdefer alloc.free(dirty_value);
            try out.append(alloc, .{ .key = progress_key, .value = dirty_value });
        } else {
            try deletes.append(alloc, progress_key);
        }

        const rebuild_prefix = try internal_keys.artifactRepairSummaryRebuildRootKeyAlloc(alloc);
        defer alloc.free(rebuild_prefix);
        try self.appendKeysForPrefixDelete(alloc, deletes, owned_keys, rebuild_prefix);
    }

    fn appendArtifactRepairSummaryDirty(
        self: *DB,
        alloc: Allocator,
        writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
        deletes: *std.ArrayListUnmanaged([]const u8),
        owned_delete_keys: *std.ArrayListUnmanaged([]const u8),
    ) !void {
        const ready_key = try internal_keys.artifactRepairSummaryReadyKeyAlloc(alloc);
        errdefer alloc.free(ready_key);
        const owned_len = owned_delete_keys.items.len;
        try owned_delete_keys.append(alloc, ready_key);
        errdefer owned_delete_keys.shrinkRetainingCapacity(owned_len);
        try deletes.append(alloc, ready_key);
        try self.appendArtifactRepairSummaryRebuildInvalidation(alloc, writes, deletes, owned_delete_keys);
    }

    fn saveArtifactRepairIssueWithSummary(
        self: *DB,
        alloc: Allocator,
        key: []const u8,
        issue: types.ArtifactRepairIssue,
        new_issue: bool,
    ) !void {
        const kind_key = try self.repairIssueKindKeyForIssueAlloc(alloc, issue);
        defer alloc.free(kind_key);
        const encoded = try self.encodeArtifactRepairIssueAlloc(alloc, issue);
        defer alloc.free(encoded);
        if (!new_issue) {
            const writes = [_]docstore_mod.KVPair{
                .{ .key = key, .value = encoded },
                .{ .key = kind_key, .value = encoded },
            };
            try self.core.store.putBatch(writes[0..], &.{});
            return;
        }

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (writes.items) |item| {
                if (item.value.ptr != encoded.ptr) alloc.free(@constCast(item.value));
            }
            writes.deinit(alloc);
        }
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(alloc);
        var owned_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_delete_keys.items) |owned_key| alloc.free(@constCast(owned_key));
            owned_delete_keys.deinit(alloc);
        }

        try writes.append(alloc, .{ .key = key, .value = encoded });
        try writes.append(alloc, .{ .key = kind_key, .value = encoded });
        try self.appendArtifactRepairSummaryDirty(alloc, &writes, &deletes, &owned_delete_keys);
        try self.core.store.putBatch(writes.items, deletes.items);
    }

    fn clearArtifactRepairIssueWithSummary(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !void {
        const key = try self.repairIssueKeyForIssueAlloc(alloc, issue);
        defer alloc.free(key);

        const existing = (try self.loadArtifactRepairIssueByKey(alloc, key)) orelse {
            const stale_kind_key = try self.repairIssueKindKeyForIssueAlloc(alloc, issue);
            defer alloc.free(stale_kind_key);
            try self.core.store.putBatch(&.{}, &.{stale_kind_key});
            return;
        };
        var existing_issue = existing;
        defer existing_issue.deinit(alloc);

        const kind_key = try self.repairIssueKindKeyForIssueAlloc(alloc, existing_issue);
        defer alloc.free(kind_key);

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (writes.items) |item| alloc.free(@constCast(item.value));
            writes.deinit(alloc);
        }
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(alloc);
        var owned_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (owned_delete_keys.items) |owned_key| alloc.free(@constCast(owned_key));
            owned_delete_keys.deinit(alloc);
        }

        try deletes.append(alloc, key);
        try deletes.append(alloc, kind_key);
        try self.appendArtifactRepairSummaryDirty(alloc, &writes, &deletes, &owned_delete_keys);
        try self.core.store.putBatch(writes.items, deletes.items);
    }

    fn rebuildArtifactRepairSummaryIfMissing(self: *DB, alloc: Allocator) !bool {
        if (try self.artifactRepairSummaryReady(alloc)) return false;

        const root_summary_key = try internal_keys.artifactRepairSummaryRootKeyAlloc(alloc);
        defer alloc.free(root_summary_key);
        const rebuild_root_summary_key = try internal_keys.artifactRepairSummaryRebuildRootKeyAlloc(alloc);
        defer alloc.free(rebuild_root_summary_key);
        const progress_key = try internal_keys.artifactRepairSummaryProgressKeyAlloc(alloc);
        defer alloc.free(progress_key);
        const raw_progress = self.core.store.get(alloc, progress_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        defer if (raw_progress) |value| alloc.free(value);

        if (raw_progress == null and (try self.loadArtifactRepairSummaryCountByKey(alloc, root_summary_key)) != null) {
            const ready_key = try internal_keys.artifactRepairSummaryReadyKeyAlloc(alloc);
            defer alloc.free(ready_key);
            var deletes = std.ArrayListUnmanaged([]const u8).empty;
            defer deletes.deinit(alloc);
            var owned_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
            defer {
                for (owned_delete_keys.items) |owned_key| alloc.free(@constCast(owned_key));
                owned_delete_keys.deinit(alloc);
            }
            try self.appendArtifactRepairSummaryRebuildInvalidation(alloc, null, &deletes, &owned_delete_keys);
            const writes = [_]docstore_mod.KVPair{.{ .key = ready_key, .value = "1" }};
            try self.core.store.putBatchWithReplayWithOptions(null, writes[0..], deletes.items, null, .{ .defer_commit_flush = true });
            return false;
        }
        if (raw_progress == null) {
            var deletes = std.ArrayListUnmanaged([]const u8).empty;
            defer deletes.deinit(alloc);
            var owned_delete_keys = std.ArrayListUnmanaged([]const u8).empty;
            defer {
                for (owned_delete_keys.items) |owned_key| alloc.free(@constCast(owned_key));
                owned_delete_keys.deinit(alloc);
            }
            try self.appendArtifactRepairSummaryRebuildInvalidation(alloc, null, &deletes, &owned_delete_keys);
            if (deletes.items.len != 0) {
                try self.core.store.putBatchWithReplayWithOptions(null, &.{}, deletes.items, null, .{ .defer_commit_flush = true });
            }
        }

        const prefix = try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);

        const lower = lower: {
            const progress = raw_progress orelse break :lower try alloc.dupe(u8, prefix);
            if (!std.mem.startsWith(u8, progress, prefix)) break :lower try alloc.dupe(u8, prefix);
            var lower = try alloc.alloc(u8, progress.len + 1);
            @memcpy(lower[0..progress.len], progress);
            lower[progress.len] = 0;
            break :lower lower;
        };
        defer alloc.free(lower);

        const ScanState = struct {
            const batch_limit: usize = 1024;

            alloc: Allocator,
            root_count: u64 = 0,
            per_index: std.StringHashMapUnmanaged(u64) = .empty,
            rows: usize = 0,
            last_key: ?[]u8 = null,

            fn deinit(state: *@This()) void {
                var it = state.per_index.iterator();
                while (it.next()) |entry| state.alloc.free(entry.key_ptr.*);
                state.per_index.deinit(state.alloc);
                if (state.last_key) |key| state.alloc.free(key);
            }

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                var issue = try decodeArtifactRepairIssueValueAlloc(state.alloc, value);
                defer issue.deinit(state.alloc);
                state.root_count += 1;
                state.rows += 1;
                const result = try state.per_index.getOrPut(state.alloc, issue.index_name);
                if (!result.found_existing) {
                    result.key_ptr.* = try state.alloc.dupe(u8, issue.index_name);
                    result.value_ptr.* = 0;
                }
                result.value_ptr.* += 1;
                if (state.last_key) |existing| state.alloc.free(existing);
                state.last_key = try state.alloc.dupe(u8, key);
                if (state.rows >= batch_limit) return .stop;
                return .@"continue";
            }
        };

        var state = ScanState{ .alloc = alloc };
        defer state.deinit();
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        var owned_keys = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (writes.items) |item| alloc.free(@constCast(item.value));
            for (owned_keys.items) |owned_key| alloc.free(@constCast(owned_key));
            owned_keys.deinit(alloc);
            writes.deinit(alloc);
        }
        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer deletes.deinit(alloc);

        if (state.rows < ScanState.batch_limit) {
            var publish_counts = std.StringHashMapUnmanaged(u64).empty;
            defer {
                publish_counts.deinit(alloc);
            }

            const PublishState = struct {
                alloc: Allocator,
                counts: *std.StringHashMapUnmanaged(u64),
                deletes: *std.ArrayListUnmanaged([]const u8),
                owned_keys: *std.ArrayListUnmanaged([]const u8),

                fn addCount(ctx: *@This(), live_key: []u8, value: u64) !void {
                    errdefer ctx.alloc.free(live_key);
                    const result = try ctx.counts.getOrPut(ctx.alloc, live_key);
                    if (result.found_existing) {
                        ctx.alloc.free(live_key);
                        result.value_ptr.* += value;
                    } else {
                        try ctx.owned_keys.append(ctx.alloc, live_key);
                        result.key_ptr.* = live_key;
                        result.value_ptr.* = value;
                    }
                }

                fn scanEntry(ctx_raw: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                    const ctx: *@This() = @ptrCast(@alignCast(ctx_raw orelse return error.InvalidArgument));
                    if (value.len != @sizeOf(u64)) return error.InvalidArtifactPayload;
                    const shadow_key = try ctx.alloc.dupe(u8, key);
                    errdefer ctx.alloc.free(shadow_key);
                    const owned_len = ctx.owned_keys.items.len;
                    try ctx.owned_keys.append(ctx.alloc, shadow_key);
                    errdefer ctx.owned_keys.shrinkRetainingCapacity(owned_len);
                    try ctx.deletes.append(ctx.alloc, shadow_key);
                    const count = std.mem.readInt(u64, value[0..8], .little);
                    var live_key = try ctx.alloc.dupe(u8, key);
                    live_key[2] = internal_keys.artifact_repair_summary_kind;
                    try ctx.addCount(live_key, count);
                    return .@"continue";
                }
            };

            try self.appendKeysForPrefixDelete(alloc, &deletes, &owned_keys, root_summary_key);
            var publish_state = PublishState{
                .alloc = alloc,
                .counts = &publish_counts,
                .deletes = &deletes,
                .owned_keys = &owned_keys,
            };
            const rebuild_upper = try internal_keys.nextPrefixAlloc(alloc, rebuild_root_summary_key);
            defer if (rebuild_upper) |buf| alloc.free(buf);
            try self.core.store.scanWithContext(
                rebuild_root_summary_key,
                if (rebuild_upper) |buf| buf else "",
                .{},
                &publish_state,
                PublishState.scanEntry,
            );

            if (state.root_count != 0) {
                const live_key = try alloc.dupe(u8, root_summary_key);
                try PublishState.addCount(&publish_state, live_key, state.root_count);
            }

            var it = state.per_index.iterator();
            while (it.next()) |entry| {
                const live_key = try internal_keys.artifactRepairSummaryIndexKeyAlloc(alloc, entry.key_ptr.*);
                try PublishState.addCount(&publish_state, live_key, entry.value_ptr.*);
            }

            var count_it = publish_counts.iterator();
            while (count_it.next()) |entry| {
                if (entry.value_ptr.* == 0) continue;
                const value = try alloc.alloc(u8, @sizeOf(u64));
                std.mem.writeInt(u64, value[0..8], entry.value_ptr.*, .little);
                try writes.append(alloc, .{ .key = entry.key_ptr.*, .value = value });
            }

            const ready_key = try internal_keys.artifactRepairSummaryReadyKeyAlloc(alloc);
            try owned_keys.append(alloc, ready_key);
            const ready_value = try alloc.dupe(u8, "1");
            try writes.append(alloc, .{ .key = ready_key, .value = ready_value });
            try deletes.append(alloc, progress_key);
        } else if (state.last_key) |last_key| {
            if (state.root_count != 0) {
                try self.appendArtifactRepairSummaryWrite(alloc, &writes, &deletes, rebuild_root_summary_key, @intCast(state.root_count));
            }

            var it = state.per_index.iterator();
            while (it.next()) |entry| {
                const key = try internal_keys.artifactRepairSummaryRebuildIndexKeyAlloc(alloc, entry.key_ptr.*);
                try owned_keys.append(alloc, key);
                try self.appendArtifactRepairSummaryWrite(alloc, &writes, &deletes, key, @intCast(entry.value_ptr.*));
            }

            const progress_key_copy = try alloc.dupe(u8, progress_key);
            try owned_keys.append(alloc, progress_key_copy);
            const progress_value = try alloc.dupe(u8, last_key);
            try writes.append(alloc, .{ .key = progress_key_copy, .value = progress_value });
            try self.core.store.putBatchWithReplayWithOptions(null, writes.items, deletes.items, null, .{ .defer_commit_flush = true });
            return true;
        }
        try self.core.store.putBatchWithReplayWithOptions(null, writes.items, deletes.items, null, .{ .defer_commit_flush = true });
        return false;
    }

    fn artifactRepairKindIndexReady(self: *DB, alloc: Allocator) !bool {
        const ready_key = try internal_keys.artifactRepairKindIndexReadyKeyAlloc(alloc);
        defer alloc.free(ready_key);
        const ready = self.core.store.get(alloc, ready_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        alloc.free(ready);
        return true;
    }

    fn rebuildArtifactRepairKindIndexIfMissing(self: *DB, alloc: Allocator) !bool {
        if (try self.artifactRepairKindIndexReady(alloc)) return false;

        const prefix = try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);

        const progress_key = try internal_keys.artifactRepairKindIndexProgressKeyAlloc(alloc);
        defer alloc.free(progress_key);
        const raw_progress = self.core.store.get(alloc, progress_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        defer if (raw_progress) |value| alloc.free(value);

        const lower = lower: {
            const progress = raw_progress orelse break :lower try alloc.dupe(u8, prefix);
            if (!std.mem.startsWith(u8, progress, prefix)) break :lower try alloc.dupe(u8, prefix);
            var lower = try alloc.alloc(u8, progress.len + 1);
            @memcpy(lower[0..progress.len], progress);
            lower[progress.len] = 0;
            break :lower lower;
        };
        defer alloc.free(lower);

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (writes.items) |item| {
                alloc.free(@constCast(item.key));
                alloc.free(@constCast(item.value));
            }
            writes.deinit(alloc);
        }

        const ScanState = struct {
            const batch_limit: usize = 1024;

            alloc: Allocator,
            writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
            rows: usize = 0,
            last_key: ?[]u8 = null,

            fn deinit(state: *@This()) void {
                if (state.last_key) |key| state.alloc.free(key);
            }

            fn scanEntry(ctx: ?*anyopaque, _: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                var issue = try decodeArtifactRepairIssueValueAlloc(state.alloc, value);
                defer issue.deinit(state.alloc);

                const kind_key = try artifactRepairIssueKindKeyForIssueAlloc(state.alloc, issue);
                errdefer state.alloc.free(kind_key);
                const value_copy = try state.alloc.dupe(u8, value);
                errdefer state.alloc.free(value_copy);
                try state.writes.append(state.alloc, .{ .key = kind_key, .value = value_copy });
                state.rows += 1;
                if (state.last_key) |key| state.alloc.free(key);
                state.last_key = try artifactRepairIssueKeyForIssueAlloc(state.alloc, issue);
                if (state.rows >= batch_limit) return .stop;
                return .@"continue";
            }
        };

        var state = ScanState{ .alloc = alloc, .writes = &writes };
        defer state.deinit();
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);

        if (state.rows < ScanState.batch_limit) {
            const ready_key = try internal_keys.artifactRepairKindIndexReadyKeyAlloc(alloc);
            errdefer alloc.free(ready_key);
            const ready_value = try alloc.dupe(u8, "1");
            errdefer alloc.free(ready_value);
            try writes.append(alloc, .{ .key = ready_key, .value = ready_value });
            const deletes = [_][]const u8{progress_key};
            try self.core.store.putBatchWithReplayWithOptions(null, writes.items, deletes[0..], null, .{ .defer_commit_flush = true });
            return false;
        }

        if (state.last_key) |last_key| {
            const progress_key_copy = try alloc.dupe(u8, progress_key);
            errdefer alloc.free(progress_key_copy);
            const progress_value = try alloc.dupe(u8, last_key);
            errdefer alloc.free(progress_value);
            try writes.append(alloc, .{ .key = progress_key_copy, .value = progress_value });
        }

        try self.core.store.putBatchWithReplayWithOptions(null, writes.items, &.{}, null, .{ .defer_commit_flush = true });
        return true;
    }

    pub fn recordArtifactRepairIssue(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
    ) !void {
        const key = try self.repairIssueKeyForIssueAlloc(alloc, issue);
        defer alloc.free(key);

        const now_ns = currentTimeNs();
        const existing = try self.loadArtifactRepairIssueByKey(alloc, key);
        var stored = if (existing) |loaded|
            loaded
        else
            try cloneArtifactRepairIssueAlloc(alloc, issue);
        defer stored.deinit(alloc);

        stored.artifact_kind = issue.artifact_kind;
        stored.repairable = artifactRepairKindHasAutomatedReprocessor(issue.artifact_kind);
        stored.sequence = issue.sequence;
        stored.reason = issue.reason;
        if (stored.first_seen_ns == 0) stored.first_seen_ns = now_ns;
        stored.last_seen_ns = now_ns;
        if (stored.artifact_key.len == 0 and issue.artifact_key.len > 0) {
            stored.artifact_key = try alloc.dupe(u8, issue.artifact_key);
        }
        if (stored.parent_doc_key.len == 0 and issue.parent_doc_key.len > 0) {
            stored.parent_doc_key = try alloc.dupe(u8, issue.parent_doc_key);
        }
        if (stored.unit_id.len == 0 and issue.unit_id.len > 0) {
            stored.unit_id = try alloc.dupe(u8, issue.unit_id);
        }
        if (stored.source_artifact_name.len == 0 and issue.source_artifact_name.len > 0) {
            stored.source_artifact_name = try alloc.dupe(u8, issue.source_artifact_name);
        }
        if (stored.unsupported_reason.len == 0 and !stored.repairable) {
            stored.unsupported_reason = try alloc.dupe(u8, artifactRepairUnsupportedReason(stored.artifact_kind));
        }

        try self.saveArtifactRepairIssueWithSummary(alloc, key, stored, existing == null);
    }

    fn recordEmbeddingArtifactRepairIssue(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        artifact_key: []const u8,
        sequence: u64,
        reason: types.ArtifactRepairReason,
    ) !void {
        var identity = (try artifact_ids.decodeEmbeddingArtifactIdentityAlloc(alloc, artifact_key)) orelse return;
        defer identity.deinit(alloc);

        const artifact_key_hex = try bytesToHexAlloc(alloc, artifact_key);
        defer alloc.free(artifact_key_hex);
        const key = try internal_keys.artifactRepairIssueKeyAlloc(alloc, index_name, "embedding", artifact_key_hex);
        defer alloc.free(key);

        const now_ns = currentTimeNs();
        const existing = try self.loadArtifactRepairIssueByKey(alloc, key);
        var issue = if (existing) |loaded|
            loaded
        else
            types.ArtifactRepairIssue{
                .artifact_kind = .embedding,
                .index_name = try alloc.dupe(u8, index_name),
                .doc_key = try alloc.dupe(u8, identity.doc_key),
                .parent_doc_key = try alloc.dupe(u8, identity.parent_doc_key orelse ""),
                .unit_id = try alloc.dupe(u8, identity.unit_id orelse ""),
                .source_artifact_name = try alloc.dupe(u8, identity.source_artifact_name orelse ""),
                .artifact_name = try alloc.dupe(u8, identity.embedding_name),
                .artifact_key = try alloc.dupe(u8, artifact_key_hex),
                .chunk_id = identity.chunk_id,
                .repairable = true,
                .first_seen_ns = now_ns,
            };
        defer issue.deinit(alloc);

        issue.sequence = sequence;
        issue.reason = reason;
        issue.chunk_id = identity.chunk_id;
        issue.repairable = true;
        issue.last_seen_ns = now_ns;
        if (issue.artifact_key.len == 0) {
            issue.artifact_key = try alloc.dupe(u8, artifact_key_hex);
        }
        if (issue.parent_doc_key.len == 0) {
            issue.parent_doc_key = try alloc.dupe(u8, identity.parent_doc_key orelse "");
        }
        if (issue.unit_id.len == 0) {
            issue.unit_id = try alloc.dupe(u8, identity.unit_id orelse "");
        }
        if (issue.source_artifact_name.len == 0) {
            issue.source_artifact_name = try alloc.dupe(u8, identity.source_artifact_name orelse "");
        }

        try self.saveArtifactRepairIssueWithSummary(alloc, key, issue, existing == null);
    }

    fn artifactRepairScanLowerBoundAlloc(
        self: *DB,
        alloc: Allocator,
        prefix: []const u8,
        cursor: ?[]const u8,
    ) ![]u8 {
        _ = self;
        const raw_cursor = cursor orelse return try alloc.dupe(u8, prefix);
        if (raw_cursor.len == 0) return try alloc.dupe(u8, prefix);
        const key = hexToBytesAlloc(alloc, raw_cursor) catch return error.InvalidArgument;
        defer alloc.free(key);
        if (!std.mem.startsWith(u8, key, prefix)) return error.InvalidArgument;
        var lower = try alloc.alloc(u8, key.len + 1);
        @memcpy(lower[0..key.len], key);
        lower[key.len] = 0;
        return lower;
    }

    fn artifactRepairCursorMatchesPrefix(self: *DB, alloc: Allocator, cursor: ?[]const u8, prefix: []const u8) !bool {
        _ = self;
        const raw_cursor = cursor orelse return true;
        if (raw_cursor.len == 0) return true;
        const key = hexToBytesAlloc(alloc, raw_cursor) catch return false;
        defer alloc.free(key);
        return std.mem.startsWith(u8, key, prefix);
    }

    fn artifactRepairPrimaryScanPrefixAlloc(self: *DB, alloc: Allocator, req: types.ArtifactRepairListRequest) ![]u8 {
        _ = self;
        if (req.index_name) |name| return try internal_keys.artifactRepairIssueIndexPrefixAlloc(alloc, name);
        return try internal_keys.artifactRepairIssueRootPrefixAlloc(alloc);
    }

    fn artifactRepairKindScanPrefixAlloc(self: *DB, alloc: Allocator, req: types.ArtifactRepairListRequest, kind: types.ArtifactRepairKind) ![]u8 {
        _ = self;
        if (req.index_name) |name| return try internal_keys.artifactRepairIssueKindIndexPrefixAlloc(alloc, @tagName(kind), name);
        return try internal_keys.artifactRepairIssueKindRootPrefixAlloc(alloc, @tagName(kind));
    }

    fn artifactRepairFallbackScanBudget(limit: u32) u64 {
        const requested: u64 = if (limit == 0) 4096 else @as(u64, limit) * 32;
        return @min(@max(requested, 256), 4096);
    }

    fn artifactRepairKindForIndexKind(kind: types.IndexKind) ?types.ArtifactRepairKind {
        return switch (kind) {
            .dense_vector, .sparse_vector => .embedding,
            .graph => .graph,
            .full_text => .full_text,
            .algebraic => .algebraic,
        };
    }

    fn listIndexRepairIssuesPage(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairListRequest,
    ) !types.ArtifactRepairListResult {
        const configs = try self.core.listIndexes(alloc);
        defer types.freeIndexConfigs(alloc, configs);
        std.mem.sort(types.IndexConfig, configs, {}, struct {
            fn lessThan(_: void, lhs: types.IndexConfig, rhs: types.IndexConfig) bool {
                return std.mem.order(u8, lhs.name, rhs.name) == .lt;
            }
        }.lessThan);

        var issues = std.ArrayListUnmanaged(types.ArtifactRepairIssue).empty;
        errdefer {
            for (issues.items) |*issue| issue.deinit(alloc);
            issues.deinit(alloc);
        }

        const cursor = req.cursor orelse "";
        var last_returned: ?[]const u8 = null;
        var has_more = false;
        var scanned: u64 = 0;
        for (configs) |cfg| {
            if (cursor.len != 0 and std.mem.order(u8, cfg.name, cursor) != .gt) continue;
            if (req.index_name) |requested| {
                if (!std.mem.eql(u8, requested, cfg.name)) continue;
            }
            const artifact_kind = artifactRepairKindForIndexKind(cfg.kind) orelse continue;
            if (req.artifact_kind) |requested_kind| {
                if (requested_kind != artifact_kind) continue;
            }
            if (!(try self.indexRepairRequired(alloc, cfg.name))) continue;
            scanned += 1;
            if (req.limit != 0 and issues.items.len >= req.limit) {
                has_more = true;
                break;
            }

            const load_error = self.core.index_manager.loadFailure(cfg.name);
            try issues.append(alloc, .{
                .artifact_kind = artifact_kind,
                .index_name = try alloc.dupe(u8, cfg.name),
                .artifact_name = try alloc.dupe(u8, cfg.name),
                .repairable = artifact_kind != .algebraic,
                .unsupported_reason = if (artifact_kind == .algebraic) try alloc.dupe(u8, artifactRepairUnsupportedReason(.algebraic)) else "",
                .reason = if (load_error != null) .unreadable_artifact else .missing_artifact,
                .last_error = if (load_error) |err_name| try alloc.dupe(u8, err_name) else try alloc.dupe(u8, if (artifact_kind == .algebraic) artifactRepairUnsupportedReason(.algebraic) else "index_repair_required"),
            });
            last_returned = cfg.name;
        }

        return .{
            .issues = try issues.toOwnedSlice(alloc),
            .limit = req.limit,
            .scanned = scanned,
            .next_cursor = if (has_more and last_returned != null) try alloc.dupe(u8, last_returned.?) else null,
            .has_more = has_more,
        };
    }

    pub fn listArtifactRepairIssuesPage(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairListRequest,
    ) !types.ArtifactRepairListResult {
        if (req.target == .index) return try self.listIndexRepairIssuesPage(alloc, req);

        var filtering_without_kind_index = false;
        const prefix = if (req.artifact_kind) |kind| prefix_blk: {
            if (try self.artifactRepairKindIndexReady(alloc)) {
                const kind_prefix = try self.artifactRepairKindScanPrefixAlloc(alloc, req, kind);
                if (try self.artifactRepairCursorMatchesPrefix(alloc, req.cursor, kind_prefix)) break :prefix_blk kind_prefix;
                alloc.free(kind_prefix);
            }
            filtering_without_kind_index = true;
            break :prefix_blk try self.artifactRepairPrimaryScanPrefixAlloc(alloc, req);
        } else try self.artifactRepairPrimaryScanPrefixAlloc(alloc, req);
        defer alloc.free(prefix);
        const upper = try internal_keys.nextPrefixAlloc(alloc, prefix);
        defer if (upper) |buf| alloc.free(buf);
        const lower = try self.artifactRepairScanLowerBoundAlloc(alloc, prefix, req.cursor);
        defer alloc.free(lower);

        const ScanState = struct {
            alloc: Allocator,
            db: *DB,
            artifact_kind: ?types.ArtifactRepairKind,
            limit: u32,
            scan_budget: u64,
            scanned: u64 = 0,
            has_more: bool = false,
            last_cursor: ?[]u8 = null,
            issues: std.ArrayListUnmanaged(types.ArtifactRepairIssue) = .empty,

            fn deinitPartial(state: *@This()) void {
                for (state.issues.items) |*issue| issue.deinit(state.alloc);
                state.issues.deinit(state.alloc);
                if (state.last_cursor) |cursor| state.alloc.free(cursor);
            }

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                if (state.limit != 0 and state.issues.items.len >= state.limit) {
                    state.has_more = true;
                    return .stop;
                }
                state.scanned += 1;
                if (state.last_cursor) |cursor| state.alloc.free(cursor);
                state.last_cursor = try bytesToHexAlloc(state.alloc, key);
                var issue = try state.db.decodeArtifactRepairIssueAlloc(state.alloc, value);
                errdefer issue.deinit(state.alloc);
                if (state.artifact_kind) |kind| {
                    if (issue.artifact_kind != kind) {
                        issue.deinit(state.alloc);
                        if (state.scan_budget != 0 and state.scanned >= state.scan_budget) {
                            state.has_more = true;
                            return .stop;
                        }
                        return .@"continue";
                    }
                }
                try state.issues.append(state.alloc, issue);
                if (state.scan_budget != 0 and state.scanned >= state.scan_budget) {
                    state.has_more = true;
                    return .stop;
                }
                return .@"continue";
            }
        };

        var state = ScanState{
            .alloc = alloc,
            .db = self,
            .artifact_kind = req.artifact_kind,
            .limit = req.limit,
            .scan_budget = if (filtering_without_kind_index) artifactRepairFallbackScanBudget(req.limit) else 0,
        };
        errdefer state.deinitPartial();
        try self.core.store.scanWithContext(lower, if (upper) |buf| buf else "", .{}, &state, ScanState.scanEntry);
        const issues = try state.issues.toOwnedSlice(alloc);
        state.issues = .empty;
        const next_cursor = if (state.has_more) state.last_cursor else null;
        if (!state.has_more) {
            if (state.last_cursor) |cursor| alloc.free(cursor);
        }
        state.last_cursor = null;
        return .{
            .issues = issues,
            .limit = req.limit,
            .scanned = state.scanned,
            .next_cursor = next_cursor,
            .has_more = state.has_more,
        };
    }

    pub fn listArtifactRepairIssues(
        self: *DB,
        alloc: Allocator,
        artifact_kind: ?types.ArtifactRepairKind,
        index_name: ?[]const u8,
        limit: usize,
    ) ![]types.ArtifactRepairIssue {
        const page = try self.listArtifactRepairIssuesPage(alloc, .{
            .artifact_kind = artifact_kind,
            .index_name = index_name,
            .limit = @intCast(@min(limit, std.math.maxInt(u32))),
        });
        if (page.next_cursor) |cursor| alloc.free(cursor);
        return page.issues;
    }

    pub fn listEmbeddingArtifactRepairIssues(
        self: *DB,
        alloc: Allocator,
        index_name: ?[]const u8,
        limit: usize,
    ) ![]types.EmbeddingArtifactRepairIssue {
        const generic = try self.listArtifactRepairIssues(alloc, .embedding, index_name, limit);
        defer types.freeArtifactRepairIssues(alloc, generic);

        var issues = try alloc.alloc(types.EmbeddingArtifactRepairIssue, generic.len);
        var count: usize = 0;
        errdefer {
            for (issues[0..count]) |*issue| issue.deinit(alloc);
            alloc.free(issues);
        }
        for (generic) |issue| {
            issues[count] = try types.embeddingArtifactRepairIssueFromArtifactAlloc(alloc, issue);
            count += 1;
        }
        return issues;
    }

    fn clearArtifactRepairIssue(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !void {
        try self.clearArtifactRepairIssueWithSummary(alloc, issue);
    }

    fn artifactNowReadable(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !bool {
        return switch (issue.artifact_kind) {
            .embedding => try self.embeddingArtifactNowReadable(alloc, issue),
            .asset => try self.documentAssetArtifactNowReadable(alloc, issue),
            .chunk, .graph, .full_text, .algebraic => false,
        };
    }

    fn documentAssetArtifactNowReadable(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !bool {
        const doc_key = if (issue.parent_doc_key.len > 0) issue.parent_doc_key else issue.doc_key;
        if (doc_key.len == 0 or issue.artifact_name.len == 0) return false;
        if (issue.artifact_key.len > 0) {
            const actual_key = try hexToBytesAlloc(alloc, issue.artifact_key);
            defer alloc.free(actual_key);
            const expected_key = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", issue.artifact_name);
            defer alloc.free(expected_key);
            if (!std.mem.eql(u8, actual_key, expected_key)) return false;
        }
        var manifest = (self.getDocumentArtifactManifest(alloc, doc_key, issue.artifact_name) catch |err| switch (err) {
            error.OutOfMemory => return err,
            else => return false,
        }) orelse return false;
        defer manifest.deinit(alloc);
        return true;
    }

    fn embeddingArtifactNowReadable(self: *DB, alloc: Allocator, issue: types.ArtifactRepairIssue) !bool {
        const artifact_key = if (issue.artifact_key.len > 0)
            try hexToBytesAlloc(alloc, issue.artifact_key)
        else
            try internal_keys.embeddingArtifactKeyForDocumentAlloc(alloc, issue.doc_key, issue.artifact_name);
        defer alloc.free(artifact_key);

        const raw = self.core.store.get(alloc, artifact_key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        defer alloc.free(raw);

        if (self.core.index_manager.denseIndex(issue.index_name)) |entry| {
            const view = enrichment_artifact_codec.denseEmbeddingVectorView(raw) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return false;
                return err;
            };
            if (view) |vector| return vector.len == entry.dims;
            const decoded = enrichment_artifact_codec.decodeDenseEmbeddingAlloc(alloc, raw) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return false;
                return err;
            };
            defer alloc.free(decoded);
            return decoded.len == entry.dims;
        }

        if (self.core.index_manager.sparseIndex(issue.index_name) != null) {
            if (enrichment_artifact_codec.sparseEmbeddingVectorView(raw)) |maybe_view| {
                if (maybe_view != null) return true;
            } else |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return false;
                return err;
            }
            var decoded = enrichment_artifact_codec.decodeSparseEmbeddingAlloc(alloc, raw) catch |err| {
                if (isRecoverableEmbeddingArtifactError(err)) return false;
                return err;
            };
            decoded.deinit(alloc);
            return true;
        }
        return false;
    }

    fn reprocessArtifactIssue(
        self: *DB,
        alloc: Allocator,
        issue: types.ArtifactRepairIssue,
    ) !bool {
        return switch (issue.artifact_kind) {
            .embedding => try self.reprocessEmbeddingArtifactIssue(alloc, issue),
            .asset => try self.reprocessDocumentArtifact(alloc, if (issue.parent_doc_key.len > 0) issue.parent_doc_key else issue.doc_key, issue.artifact_name),
            .chunk, .graph, .full_text, .algebraic => false,
        };
    }

    fn artifactRepairKindHasReprocessor(kind: types.ArtifactRepairKind) bool {
        return artifactRepairKindHasAutomatedReprocessor(kind);
    }

    pub const StartupIndexRepairDiscovery = struct {
        discovered: usize = 0,
        already_pending: usize = 0,
        terminal: usize = 0,
        existing_terminal: usize = 0,
    };

    fn indexRepairStatePathAlloc(self: *const DB, alloc: Allocator) ![]u8 {
        const path = self.core.index_repair_checkpoint_path orelse return error.DurableIndexRepairStateUnavailable;
        return try alloc.dupe(u8, path);
    }

    fn localRepairGroupId(self: *const DB) u64 {
        const namespace = self.core.identity_namespace;
        if (namespace.range_id != 0) return namespace.range_id;
        return namespace.shard_id;
    }

    pub fn hasPendingIndexRepairIntents(self: *const DB, alloc: Allocator) !bool {
        const path = try self.indexRepairStatePathAlloc(alloc);
        defer alloc.free(path);
        var state = index_repair_state.load(alloc, path) catch |err| switch (err) {
            error.FileNotFound => return false,
            else => return err,
        };
        defer state.deinit(alloc);
        return state.entries.items.len != 0;
    }

    pub const IndexRepairIntentSummary = struct {
        runnable: usize = 0,
        paused: usize = 0,
        terminal: usize = 0,
        earliest_retry_at_ms: u64 = 0,
    };

    pub fn indexRepairIntentSummary(self: *const DB, alloc: Allocator) !IndexRepairIntentSummary {
        var state = self.loadIndexRepairState(alloc) catch |err| switch (err) {
            error.FileNotFound => return .{},
            else => return err,
        };
        defer state.deinit(alloc);
        var summary: IndexRepairIntentSummary = .{};
        for (state.entries.items) |entry| {
            if (entry.intent.phase == .terminal) {
                summary.terminal += 1;
            } else if (entry.intent.automation == .paused) {
                summary.paused += 1;
            } else {
                summary.runnable += 1;
                if (entry.intent.next_retry_at_ms != 0 and
                    (summary.earliest_retry_at_ms == 0 or entry.intent.next_retry_at_ms < summary.earliest_retry_at_ms))
                {
                    summary.earliest_retry_at_ms = entry.intent.next_retry_at_ms;
                }
            }
        }
        return summary;
    }

    pub fn loadIndexRepairState(self: *const DB, alloc: Allocator) !index_repair_state.State {
        const path = try self.indexRepairStatePathAlloc(alloc);
        defer alloc.free(path);
        return try index_repair_state.load(alloc, path);
    }

    fn refreshIndexRepairAvailabilityGate(self: *DB, alloc: Allocator) !void {
        var state = self.loadIndexRepairState(alloc) catch |err| switch (err) {
            error.FileNotFound, error.DurableIndexRepairStateUnavailable => return,
            error.InvalidIndexRepairState => {
                self.index_repair_state_corrupt.store(true, .release);
                self.index_repair_replay_pinned.store(true, .release);
                const configs = try self.core.index_manager.listIndexesPublic(alloc);
                defer {
                    for (configs) |*cfg| cfg.deinit(alloc);
                    alloc.free(configs);
                }
                for (configs) |cfg| try self.core.index_manager.markRepairUnavailable(cfg.name);
                return;
            },
            else => return err,
        };
        defer state.deinit(alloc);
        for (state.entries.items) |entry| {
            var unavailable = indexRepairIntentBlocksService(entry.intent);
            if (!unavailable) {
                if (entry.intent.trigger == .incomplete_bulk_publish) {
                    const checkpoint = try self.core.loadProjectionCheckpoint(alloc, entry.intent.index_name);
                    unavailable = checkpoint.status != .clean or checkpoint.config_hash != entry.intent.config_hash;
                }
            }
            if (unavailable) {
                try self.core.index_manager.markRepairUnavailable(entry.intent.index_name);
            } else {
                self.core.index_manager.clearRepairUnavailable(entry.intent.index_name);
            }
        }
    }

    fn indexRepairIntentBlocksService(intent: index_repair_state.IndexRepairIntent) bool {
        return switch (intent.trigger) {
            .incomplete_bulk_publish => intent.phase != .cleanup,
            // Only an operator-requested rebuild starts from a generation that
            // is still proven healthy. Coverage mismatch or missing proof is
            // fail-closed until replacement validation publishes cleanup.
            .operator_generation_rebuild => intent.phase == .activating or intent.phase == .validating,
            .artifact_coverage_mismatch,
            .artifact_counter_missing,
            .root_generation_rebuild,
            .projection_generation_invalid,
            .operator_generation_validation,
            => intent.phase != .cleanup,
        };
    }

    fn loadOrCreateCurrentIndexRepairState(self: *DB, alloc: Allocator) !index_repair_state.State {
        const path = try self.indexRepairStatePathAlloc(alloc);
        defer alloc.free(path);
        var state = try index_repair_state.loadOrCreate(alloc, path, self.core.root_generation);
        var state_owned = true;
        defer if (state_owned) state.deinit(alloc);
        if (state.identity.root_generation == self.core.root_generation) {
            state_owned = false;
            return state;
        }

        // A root-generation transition fences every old repair identity. An
        // inactive candidate can be deleted. A pointer-selected candidate must
        // never become silently serviceable merely because its old intent is
        // discarded: persist fresh, new-root reconstruction debt first and
        // keep that index fail-closed until a new generation is validated.
        var replacement_intents = std.ArrayListUnmanaged(index_repair_state.IndexRepairIntent).empty;
        defer {
            for (replacement_intents.items) |*intent| intent.deinit(alloc);
            replacement_intents.deinit(alloc);
        }
        for (state.entries.items) |entry| {
            const candidate = entry.intent.candidate_relative_path orelse continue;
            try index_repair_state.validateCandidateRelativePath(entry.intent.index_name, candidate);
            if (try self.core.index_manager.isRepairCandidateActive(entry.intent.index_name, candidate)) {
                const cfg = self.core.index_manager.get(entry.intent.index_name) orelse
                    return error.InvalidIndexRepairState;
                const now_ms = currentTimeNs() / std.time.ns_per_ms;
                const target_sequence = self.core.nextDerivedSequence();
                var replacement_intent = index_repair_state.IndexRepairIntent{
                    .repair_id = try index_repair_state.newRepairId(alloc),
                    .db_identity = state.identity.db_identity,
                    .group_id = self.localRepairGroupId(),
                    .replica_id = state.identity.replica_id,
                    .root_generation = self.core.root_generation,
                    .index_name = try alloc.dupe(u8, entry.intent.index_name),
                    .kind = cfg.kind,
                    .config_hash = types.indexConfigHash(cfg.*),
                    .trigger = .root_generation_rebuild,
                    .detected_sequence = target_sequence,
                    .target_sequence = target_sequence,
                    .started_at_ms = now_ms,
                    .updated_at_ms = now_ms,
                    .owner_epoch = 0,
                    .last_error = try alloc.dupe(u8, "root_generation_changed_during_activation"),
                };
                var replacement_intent_owned = true;
                errdefer if (replacement_intent_owned) replacement_intent.deinit(alloc);
                try replacement_intents.append(alloc, replacement_intent);
                replacement_intent_owned = false;
                try self.core.index_manager.markRepairUnavailable(entry.intent.index_name);
                continue;
            }
            self.core.index_manager.clearRepairUnavailable(entry.intent.index_name);
            const separator = std.mem.indexOfScalar(u8, candidate, '/') orelse return error.InvalidRepairCandidatePath;
            const shadow_root = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ self.core.path, candidate[0..separator] });
            defer alloc.free(shadow_root);
            var io_impl = threadedIo();
            defer io_impl.deinit();
            try std.Io.Dir.cwd().deleteTree(io_impl.io(), shadow_root);
        }
        const old_identity = state.identity;
        state.deinit(alloc);
        state_owned = false;
        return try index_repair_state.resetForRootGenerationWithIntents(
            alloc,
            path,
            old_identity,
            self.core.root_generation,
            replacement_intents.items,
        );
    }

    fn loadIndexRepairEntryById(
        self: *const DB,
        alloc: Allocator,
        repair_id: u128,
    ) !index_repair_state.Entry {
        var state = try self.loadIndexRepairState(alloc);
        defer state.deinit(alloc);
        for (state.entries.items) |entry| {
            if (entry.intent.repair_id == repair_id) return try entry.clone(alloc);
        }
        return error.IndexRepairIntentNotFound;
    }

    pub const PinnedIndexRepairSnapshot = struct {
        txn: docstore_mod.DocStore.Txn,
        repair_id: u128,
        build_floor_sequence: u64,

        pub fn deinit(self: *@This()) void {
            self.txn.abort();
            self.* = undefined;
        }
    };

    /// Atomically protects replay before exposing a primary snapshot. The
    /// provisional zero pin and truncation share repair_replay_mutex, closing
    /// the floor-capture race even if the process stops between either durable
    /// checkpoint update.
    pub fn beginPinnedIndexRepairSnapshot(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
    ) !PinnedIndexRepairSnapshot {
        lockAtomic(self.core.repair_replay_mutex);
        defer self.core.repair_replay_mutex.unlock();
        const path = try self.indexRepairStatePathAlloc(alloc);
        defer alloc.free(path);
        var state = try index_repair_state.load(alloc, path);
        defer state.deinit(alloc);
        const entry_index = blk: {
            for (state.entries.items, 0..) |entry, i| {
                if (entry.intent.repair_id == repair_id) break :blk i;
            }
            return error.IndexRepairIntentNotFound;
        };
        var entry = try state.entries.items[entry_index].clone(alloc);
        defer entry.deinit(alloc);
        if (entry.intent.phase == .terminal or entry.intent.automation == .paused) return error.IndexRepairNotRunnable;
        var expected = index_repair_state.ExpectedTransition{
            .repair_id = entry.intent.repair_id,
            .revision = entry.intent.revision,
            .phase = entry.intent.phase,
            .config_hash = entry.intent.config_hash,
            .root_generation = entry.intent.root_generation,
            .owner_epoch = entry.intent.owner_epoch,
        };
        if (entry.pin == null) {
            entry.pin = .{
                .repair_id = entry.intent.repair_id,
                .db_identity = entry.intent.db_identity,
                .replica_id = entry.intent.replica_id,
                .root_generation = entry.intent.root_generation,
                .index_name = try alloc.dupe(u8, entry.intent.index_name),
                .retain_after_sequence = 0,
            };
            try index_repair_state.putEntry(alloc, path, state.identity, expected, entry);
        } else {
            // Re-entering snapshot acquisition must become conservative before
            // replacing a previously finalized build floor.
            entry.pin.?.retain_after_sequence = 0;
            try index_repair_state.putEntry(alloc, path, state.identity, expected, entry);
        }
        expected.revision +|= 1;
        self.index_repair_replay_pinned.store(true, .release);

        var txn = try self.core.store.beginReadTxn();
        errdefer txn.abort();
        const build_floor = try self.core.store.lastReplaySequenceFromTxn(&txn, 0);
        entry.intent.build_floor_sequence = build_floor;
        entry.intent.updated_at_ms = currentTimeNs() / std.time.ns_per_ms;
        entry.pin.?.retain_after_sequence = build_floor;
        try index_repair_state.putEntry(alloc, path, state.identity, expected, entry);
        return .{
            .txn = txn,
            .repair_id = repair_id,
            .build_floor_sequence = build_floor,
        };
    }

    const IndexRepairIntentUpdate = struct {
        trigger: ?index_repair_state.Trigger = null,
        operator_job_id: ?u64 = null,
        operator_job_created_at_ms: ?u64 = null,
        phase: ?index_repair_state.Phase = null,
        candidate_relative_path: ?[]const u8 = null,
        replace_candidate_path: bool = false,
        previous_pointer_captured: ?bool = null,
        previous_active_relative_path: ?[]const u8 = null,
        replace_previous_active_path: bool = false,
        candidate_applied_sequence: ?u64 = null,
        build_resume_key: ?[]const u8 = null,
        replace_build_resume_key: bool = false,
        build_reprocessed: ?u64 = null,
        estimated_candidate_bytes: ?u64 = null,
        planned_disk_bytes: ?u64 = null,
        target_sequence: ?u64 = null,
        attempt_count: ?u32 = null,
        failure_streak: ?u32 = null,
        next_retry_at_ms: ?u64 = null,
        automation: ?index_repair_state.Automation = null,
        owner_epoch: ?u64 = null,
        last_error: ?[]const u8 = null,
        replace_last_error: bool = false,
    };

    fn indexRepairRetryDelayMs(repair_id: u128, attempt_count: u32) u64 {
        const exponent: u6 = @intCast(@min(attempt_count -| 1, 5));
        const base_ms: u64 = 30 * std.time.ms_per_s;
        const maximum_ms: u64 = 10 * std.time.ms_per_min;
        const nominal = @min(base_ms << exponent, maximum_ms);
        // Stable per-attempt +/-10% jitter prevents a node restart from
        // synchronizing every pending repair while keeping the retry time
        // reconstructible and bounded.
        var seed: [20]u8 = undefined;
        std.mem.writeInt(u128, seed[0..16], repair_id, .little);
        std.mem.writeInt(u32, seed[16..20], attempt_count, .little);
        const spread = @max(@as(u64, 1), nominal / 5);
        const jitter = std.hash.Wyhash.hash(0x4944585250525954, &seed) % spread;
        return nominal - nominal / 10 + jitter;
    }

    fn indexRepairIdForIndex(self: *const DB, alloc: Allocator, index_name: []const u8) !?u128 {
        var state = self.loadIndexRepairState(alloc) catch |err| switch (err) {
            // Embedded/Lite databases intentionally omit the durable managed
            // repair checkpoint. No intent can exist in that configuration,
            // so read-side discovery is equivalent to an empty state. Actual
            // repair creation still fails closed through indexRepairStatePathAlloc.
            error.FileNotFound, error.DurableIndexRepairStateUnavailable => return null,
            else => return err,
        };
        defer state.deinit(alloc);
        const i = state.findIndex(index_name) orelse return null;
        return state.entries.items[i].intent.repair_id;
    }

    fn validateIndexRepairActivationState(self: *DB, alloc: Allocator, repair_id: u128, expected_owner_epoch: u64) !void {
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        if (entry.intent.root_generation != self.core.root_generation or
            entry.intent.group_id != self.localRepairGroupId())
        {
            return error.RepairOwnershipLost;
        }
        if (entry.intent.phase == .terminal or entry.intent.automation == .paused) return error.IndexRepairNotRunnable;
        if (expected_owner_epoch != 0 and entry.intent.owner_epoch != expected_owner_epoch) {
            return error.RepairOwnershipLost;
        }
        const cfg = self.core.index_manager.get(entry.intent.index_name) orelse return error.IndexRepairConfigurationChanged;
        if (cfg.kind != entry.intent.kind or types.indexConfigHash(cfg.*) != entry.intent.config_hash) {
            return error.IndexRepairConfigurationChanged;
        }
    }

    fn updateIndexRepairIntent(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        update: IndexRepairIntentUpdate,
    ) !void {
        const path = try self.indexRepairStatePathAlloc(alloc);
        defer alloc.free(path);
        var state = try index_repair_state.load(alloc, path);
        defer state.deinit(alloc);
        const i = blk: {
            for (state.entries.items, 0..) |entry, entry_i| {
                if (entry.intent.repair_id == repair_id) break :blk entry_i;
            }
            return error.IndexRepairIntentNotFound;
        };
        var entry = try state.entries.items[i].clone(alloc);
        defer entry.deinit(alloc);
        const expected = index_repair_state.ExpectedTransition{
            .repair_id = entry.intent.repair_id,
            .revision = entry.intent.revision,
            .phase = entry.intent.phase,
            .config_hash = entry.intent.config_hash,
            .root_generation = entry.intent.root_generation,
            .owner_epoch = entry.intent.owner_epoch,
        };
        if (update.trigger) |value| entry.intent.trigger = value;
        if (update.operator_job_id) |value| entry.intent.operator_job_id = value;
        if (update.operator_job_created_at_ms) |value| entry.intent.operator_job_created_at_ms = value;
        if (update.phase) |value| entry.intent.phase = value;
        if (update.replace_candidate_path) {
            if (entry.intent.candidate_relative_path) |value| alloc.free(value);
            entry.intent.candidate_relative_path = if (update.candidate_relative_path) |value| try alloc.dupe(u8, value) else null;
        }
        if (update.previous_pointer_captured) |value| entry.intent.previous_pointer_captured = value;
        if (update.replace_previous_active_path) {
            if (entry.intent.previous_active_relative_path) |value| alloc.free(value);
            entry.intent.previous_active_relative_path = if (update.previous_active_relative_path) |value| try alloc.dupe(u8, value) else null;
        }
        if (update.candidate_applied_sequence) |value| entry.intent.candidate_applied_sequence = value;
        if (update.replace_build_resume_key) {
            if (entry.intent.build_resume_key) |value| alloc.free(value);
            entry.intent.build_resume_key = if (update.build_resume_key) |value| try alloc.dupe(u8, value) else null;
        }
        if (update.build_reprocessed) |value| entry.intent.build_reprocessed = value;
        if (update.estimated_candidate_bytes) |value| entry.intent.estimated_candidate_bytes = value;
        if (update.planned_disk_bytes) |value| entry.intent.planned_disk_bytes = value;
        if (update.target_sequence) |value| entry.intent.target_sequence = value;
        if (update.attempt_count) |value| entry.intent.attempt_count = value;
        if (update.failure_streak) |value| entry.intent.failure_streak = value;
        if (update.next_retry_at_ms) |value| entry.intent.next_retry_at_ms = value;
        if (update.automation) |value| entry.intent.automation = value;
        if (update.owner_epoch) |value| entry.intent.owner_epoch = value;
        if (update.replace_last_error) {
            if (entry.intent.last_error) |value| alloc.free(value);
            entry.intent.last_error = if (update.last_error) |value| try alloc.dupe(u8, value) else null;
        }
        entry.intent.updated_at_ms = currentTimeNs() / std.time.ns_per_ms;
        try index_repair_state.putEntry(alloc, path, state.identity, expected, entry);
        if (indexRepairIntentBlocksService(entry.intent)) {
            try self.core.index_manager.markRepairUnavailable(entry.intent.index_name);
        } else {
            self.core.index_manager.clearRepairUnavailable(entry.intent.index_name);
        }
        if (update.automation) |automation| {
            notifyQueryVisibilityHook(
                self.async_context,
                if (automation == .enabled) .index_repair_pending else .index_repair_cleared,
            );
        }
        if (update.phase) |phase| {
            if (self.shadow_index_repair_hook) |hook| {
                if (hook.after_phase_persisted) |after_phase| {
                    try after_phase(hook.ptr, self, repair_id, phase);
                }
            }
        }
    }

    const operator_repair_completion_prefix = "\x00\x00__metadata__:index_generation_repair_completion:";

    fn operatorRepairCompletionKeyAlloc(
        alloc: Allocator,
        index_name: []const u8,
    ) ![]u8 {
        return try std.fmt.allocPrint(alloc, "{s}{s}", .{ operator_repair_completion_prefix, index_name });
    }

    fn operatorRepairAlreadyCompleted(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        job_id: u64,
        job_created_at_ms: u64,
    ) !bool {
        if (job_id == 0 or job_created_at_ms == 0) return false;
        const key = try operatorRepairCompletionKeyAlloc(alloc, cfg.name);
        defer alloc.free(key);
        const raw = self.core.store.get(alloc, key) catch |err| switch (err) {
            error.NotFound => return false,
            else => return err,
        };
        defer alloc.free(raw);
        if (raw.len != 48) return error.InvalidIndexRepairState;
        var state = try self.loadOrCreateCurrentIndexRepairState(alloc);
        defer state.deinit(alloc);
        const completed_job_id = std.mem.readInt(u64, raw[32..40], .little);
        const completed_created_at_ms = std.mem.readInt(u64, raw[40..48], .little);
        const completion_covers_request = completed_created_at_ms > job_created_at_ms or
            (completed_created_at_ms == job_created_at_ms and completed_job_id >= job_id);
        return completion_covers_request and
            std.mem.readInt(u64, raw[0..8], .little) == types.indexConfigHash(cfg) and
            std.mem.readInt(u128, raw[8..24], .little) == state.identity.db_identity and
            std.mem.readInt(u64, raw[24..32], .little) == state.identity.root_generation;
    }

    fn persistOperatorRepairCompletion(self: *DB, alloc: Allocator, intent: index_repair_state.IndexRepairIntent) !void {
        if (intent.operator_job_id == 0 or intent.operator_job_created_at_ms == 0) return;
        const key = try operatorRepairCompletionKeyAlloc(alloc, intent.index_name);
        defer alloc.free(key);
        var raw: [48]u8 = undefined;
        std.mem.writeInt(u64, raw[0..8], intent.config_hash, .little);
        std.mem.writeInt(u128, raw[8..24], intent.db_identity, .little);
        std.mem.writeInt(u64, raw[24..32], intent.root_generation, .little);
        std.mem.writeInt(u64, raw[32..40], intent.operator_job_id, .little);
        std.mem.writeInt(u64, raw[40..48], intent.operator_job_created_at_ms, .little);
        try self.core.store.put(key, &raw);
    }

    const AutomaticDenseGenerationRepairClassification = struct {
        trigger: index_repair_state.Trigger,
        last_error: []const u8,
    };

    const OperatorDenseGenerationValidation = union(enum) {
        online_safe,
        replay_pending,
        fail_closed: AutomaticDenseGenerationRepairClassification,
    };

    fn classifyCurrentDenseGenerationRepair(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
    ) !?AutomaticDenseGenerationRepairClassification {
        if (cfg.kind != .dense_vector) return null;
        const entry = self.core.index_manager.denseIndex(cfg.name) orelse return null;
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
        if (checkpoint.config_hash != types.indexConfigHash(cfg)) return .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_config_mismatch",
        };
        if (checkpoint.status == .repair_required) return .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_checkpoint_repair_required",
        };
        if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) return null;
        const expected = (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name)) orelse return .{
            .trigger = .artifact_counter_missing,
            .last_error = "dense_artifact_counter_missing",
        };
        if (entry.index.stats().active_count <= expected) return null;
        const target_sequence = try self.probeDerivedReplayTargetSequence(
            alloc,
            self.core.replaySource(),
            .{ .name = cfg.name, .kind = .dense_vector },
            checkpoint.applied_sequence,
        );
        if (checkpoint.applied_sequence < target_sequence) return null;
        return .{
            .trigger = .artifact_coverage_mismatch,
            .last_error = "dense_artifact_coverage_surplus",
        };
    }

    /// Performs the potentially linear structural proof only on the admitted
    /// BackendRuntime repair worker, never on the HTTP/operator request path.
    /// Cheap generation, replay, and cardinality checks run first so routine
    /// lag avoids a tree walk. The validation read transaction is stable while
    /// foreground writes continue through the ordinary derived stream.
    fn validateOperatorDenseGenerationForOnlineRebuild(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        options: types.ArtifactRepairRunOptions,
    ) !OperatorDenseGenerationValidation {
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
        if (checkpoint.config_hash != types.indexConfigHash(cfg)) return .{ .fail_closed = .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_config_mismatch",
        } };
        if (checkpoint.status != .clean) return .{ .fail_closed = .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_checkpoint_not_clean",
        } };
        const target_sequence = try self.probeDerivedReplayTargetSequence(
            alloc,
            self.core.replaySource(),
            .{ .name = cfg.name, .kind = .dense_vector },
            checkpoint.applied_sequence,
        );
        if (checkpoint.applied_sequence < target_sequence) return .replay_pending;

        // Pin both the catalog entry and its generation while inspecting the
        // HBC metadata/tree. The read transaction stabilizes backend pages;
        // this guard additionally prevents an apply or delete/recreate from
        // changing the in-memory generation around that snapshot.
        var apply_guard = self.core.index_manager.lockManagedIndexApply(.{
            .name = cfg.name,
            .kind = .dense_vector,
        }) catch return .{ .fail_closed = .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_generation_unavailable",
        } };
        defer apply_guard.unlock();

        const entry = self.core.index_manager.denseIndex(cfg.name) orelse return .{ .fail_closed = .{
            .trigger = .projection_generation_invalid,
            .last_error = "dense_projection_generation_unavailable",
        } };

        if (try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) {
            const expected = (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name)) orelse
                return .{ .fail_closed = .{
                    .trigger = .artifact_counter_missing,
                    .last_error = "dense_artifact_counter_missing",
                } };
            if (!denseCoverageMatchesTarget(entry.index.stats().active_count, expected)) {
                return .{ .fail_closed = .{
                    .trigger = .artifact_coverage_mismatch,
                    .last_error = "dense_artifact_coverage_mismatch",
                } };
            }
        }

        const cancel_ctx = if (options.cancel_check) |check| check.ptr else null;
        const cancel_fn = if (options.cancel_check) |check| check.is_requested else null;
        entry.index.validateStoredStructureWithCancellation(alloc, cancel_ctx, cancel_fn) catch |err| switch (err) {
            error.NotFound, error.FileNotFound, error.Corrupted => return .{ .fail_closed = .{
                .trigger = .projection_generation_invalid,
                .last_error = "dense_projection_structure_invalid",
            } },
            else => return err,
        };
        return .online_safe;
    }

    fn createGenerationRepairIntent(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        trigger: index_repair_state.Trigger,
        operator_job_id: u64,
        operator_job_created_at_ms: u64,
        last_error: ?[]const u8,
    ) !u128 {
        var state = try self.loadOrCreateCurrentIndexRepairState(alloc);
        defer state.deinit(alloc);
        if (state.findIndex(cfg.name)) |i| return state.entries.items[i].intent.repair_id;
        const path = try self.indexRepairStatePathAlloc(alloc);
        defer alloc.free(path);
        const now_ms = currentTimeNs() / std.time.ns_per_ms;
        const target_sequence = self.core.nextDerivedSequence();
        const repair_id = try index_repair_state.newRepairId(alloc);
        const index_name = try alloc.dupe(u8, cfg.name);
        var intent_allocations_transferred = false;
        errdefer if (!intent_allocations_transferred) alloc.free(index_name);
        const owned_last_error = if (last_error) |value| try alloc.dupe(u8, value) else null;
        errdefer if (!intent_allocations_transferred) if (owned_last_error) |value| alloc.free(value);
        var intent = index_repair_state.IndexRepairIntent{
            .repair_id = repair_id,
            .db_identity = state.identity.db_identity,
            .group_id = self.localRepairGroupId(),
            .replica_id = state.identity.replica_id,
            .root_generation = state.identity.root_generation,
            .index_name = index_name,
            .kind = cfg.kind,
            .config_hash = types.indexConfigHash(cfg),
            .trigger = trigger,
            .operator_job_id = operator_job_id,
            .operator_job_created_at_ms = operator_job_created_at_ms,
            .detected_sequence = target_sequence,
            .target_sequence = target_sequence,
            .started_at_ms = now_ms,
            .updated_at_ms = now_ms,
            .owner_epoch = 0,
            .last_error = owned_last_error,
        };
        intent_allocations_transferred = true;
        defer intent.deinit(alloc);
        index_repair_state.putEntry(alloc, path, state.identity, null, .{ .intent = intent }) catch |err| switch (err) {
            // Another operator/maintenance caller may win creation between the
            // optimistic state read and the checkpoint CAS. Adopt that durable
            // intent; callers subsequently attach their job identity or
            // promote its safety classification with revision-fenced retries.
            error.RepairTransitionConflict => return (try self.indexRepairIdForIndex(alloc, cfg.name)) orelse return err,
            else => return err,
        };
        if (indexRepairIntentBlocksService(intent)) {
            try self.core.index_manager.markRepairUnavailable(intent.index_name);
        }
        notifyQueryVisibilityHook(self.async_context, .index_repair_pending);
        return repair_id;
    }

    fn createOperatorGenerationRepairIntent(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        operator_job_id: u64,
        operator_job_created_at_ms: u64,
    ) !u128 {
        const repair_id = try self.createGenerationRepairIntent(
            alloc,
            cfg,
            if (cfg.kind == .dense_vector) .operator_generation_validation else .operator_generation_rebuild,
            operator_job_id,
            operator_job_created_at_ms,
            null,
        );
        try self.attachOperatorRepairRequest(
            alloc,
            repair_id,
            operator_job_id,
            operator_job_created_at_ms,
        );
        return repair_id;
    }

    fn attachOperatorRepairRequest(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        operator_job_id: u64,
        operator_job_created_at_ms: u64,
    ) !void {
        if (operator_job_id == 0 or operator_job_created_at_ms == 0) return;
        var attempts: usize = 0;
        while (attempts < 4) : (attempts += 1) {
            var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer entry.deinit(alloc);
            const existing_is_newer = entry.intent.operator_job_created_at_ms > operator_job_created_at_ms or
                (entry.intent.operator_job_created_at_ms == operator_job_created_at_ms and
                    entry.intent.operator_job_id >= operator_job_id);
            if (existing_is_newer) return;
            self.updateIndexRepairIntent(alloc, repair_id, .{
                .operator_job_id = operator_job_id,
                .operator_job_created_at_ms = operator_job_created_at_ms,
            }) catch |err| switch (err) {
                error.RepairTransitionConflict => continue,
                else => return err,
            };
            return;
        }
        return error.RepairTransitionConflict;
    }

    fn automaticDenseGenerationRepairTriggerPriority(trigger: index_repair_state.Trigger) u8 {
        return switch (trigger) {
            .operator_generation_rebuild, .operator_generation_validation => 0,
            .artifact_coverage_mismatch => 1,
            .artifact_counter_missing => 2,
            .incomplete_bulk_publish, .root_generation_rebuild, .projection_generation_invalid => 3,
        };
    }

    fn ensureAutomaticDenseGenerationRepairIntent(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        trigger: index_repair_state.Trigger,
        last_error: []const u8,
    ) !u128 {
        std.debug.assert(trigger == .artifact_coverage_mismatch or
            trigger == .artifact_counter_missing or
            trigger == .projection_generation_invalid);

        // Every automatic generation repair represents missing correctness
        // proof. Close the query gate before persistence so an I/O failure
        // cannot leave a known-unverified index available.
        try self.core.index_manager.markRepairUnavailable(cfg.name);

        const repair_id = (try self.indexRepairIdForIndex(alloc, cfg.name)) orelse
            try self.createGenerationRepairIntent(
                alloc,
                cfg,
                trigger,
                0,
                0,
                last_error,
            );

        // Creation races with an operator request are harmless: re-read the
        // winning intent and promote its safety classification when needed.
        var attempts: usize = 0;
        while (attempts < 4) : (attempts += 1) {
            var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer entry.deinit(alloc);
            if (automaticDenseGenerationRepairTriggerPriority(trigger) <=
                automaticDenseGenerationRepairTriggerPriority(entry.intent.trigger)) return repair_id;
            self.updateIndexRepairIntent(alloc, repair_id, .{
                .trigger = trigger,
                .replace_last_error = true,
                .last_error = last_error,
            }) catch |err| switch (err) {
                error.RepairTransitionConflict => continue,
                else => return err,
            };
            return repair_id;
        }
        return error.RepairTransitionConflict;
    }

    const DenseArtifactCounterBootstrapSnapshot = struct {
        txn: docstore_mod.DocStore.Txn,
        attempt_id: u128,

        fn deinit(self: *@This()) void {
            self.txn.abort();
            self.* = undefined;
        }
    };

    fn beginDenseArtifactCounterBootstrapSnapshot(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        repair_id: u128,
    ) !DenseArtifactCounterBootstrapSnapshot {
        lockApply(self);
        defer self.core.unlockApply();

        if (try loadDenseArtifactTargetCounter(alloc, self.core.store, index_name) != null) {
            return error.DenseArtifactCounterAlreadyInitialized;
        }
        const attempt_id = try index_repair_state.newRepairId(alloc);
        const marker_key = try denseArtifactCounterBootstrapKeyAlloc(alloc, index_name);
        defer alloc.free(marker_key);
        var marker_value: [dense_artifact_counter_bootstrap_encoded_len]u8 = undefined;
        encodeDenseArtifactCounterBootstrap(.{
            .repair_id = repair_id,
            .attempt_id = attempt_id,
        }, &marker_value);
        try self.core.store.putBatch(&.{.{ .key = marker_key, .value = &marker_value }}, &.{});

        // The apply lock orders marker publication before this snapshot and
        // before every later artifact mutation. Once it is released, those
        // mutations update the marker's signed delta in their own atomic store
        // batch while this stable snapshot is counted without blocking writes.
        return .{
            .txn = try self.core.store.beginReadTxn(),
            .attempt_id = attempt_id,
        };
    }

    fn finishDenseArtifactCounterBootstrap(
        self: *DB,
        alloc: Allocator,
        index_name: []const u8,
        repair_id: u128,
        attempt_id: u128,
        snapshot_count: u64,
    ) !void {
        lockApply(self);
        defer self.core.unlockApply();

        if (try loadDenseArtifactTargetCounter(alloc, self.core.store, index_name) != null) return;
        const marker = (try loadDenseArtifactCounterBootstrap(alloc, self.core.store, index_name)) orelse
            return error.DenseArtifactCounterBootstrapMissing;
        if (marker.repair_id != repair_id or marker.attempt_id != attempt_id) {
            return error.StaleDenseArtifactCounterBootstrap;
        }

        const final_count_i128 = @as(i128, @intCast(snapshot_count)) + @as(i128, marker.delta);
        if (final_count_i128 < 0 or final_count_i128 > std.math.maxInt(u64)) {
            return error.InvalidDenseArtifactCounterBootstrapDelta;
        }
        const counter_key = try denseArtifactTargetCounterKeyAlloc(alloc, index_name);
        defer alloc.free(counter_key);
        const marker_key = try denseArtifactCounterBootstrapKeyAlloc(alloc, index_name);
        defer alloc.free(marker_key);
        var counter_value: [8]u8 = undefined;
        std.mem.writeInt(u64, &counter_value, @intCast(final_count_i128), .little);
        try self.core.store.putBatch(
            &.{.{ .key = counter_key, .value = &counter_value }},
            &.{marker_key},
        );
    }

    fn countDenseArtifactsForConfigFromReadTxn(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        read_txn: *docstore_mod.DocStore.Txn,
        cancel_check: ?types.RepairCancelCheck,
    ) !u64 {
        const artifact_name = try index_manager_mod.denseConfigArtifactNameAlloc(alloc, cfg);
        defer alloc.free(artifact_name);
        const dims = try index_manager_mod.denseConfigDimensions(alloc, cfg);
        const lower = try self.core.documentRangeLowerAlloc("");
        defer self.core.alloc.free(lower);

        const ScanState = struct {
            alloc: Allocator,
            artifact_name: []const u8,
            dims: u32,
            cancel_check: ?types.RepairCancelCheck,
            scanned: usize = 0,
            count: u64 = 0,

            fn scanEntry(ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
                const state: *@This() = @ptrCast(@alignCast(ctx orelse return error.InvalidArgument));
                state.scanned +|= 1;
                if ((state.scanned & 1023) == 0) {
                    if (state.cancel_check) |check| if (check.requested()) return error.Canceled;
                }
                if (!internal_keys.isInternalUserKey(key)) return .@"continue";
                var artifact_ref = (try decodeArtifactRefIfKnownAlloc(state.alloc, key)) orelse return .@"continue";
                defer artifact_ref.deinit(state.alloc);
                if (artifact_ref.kind != .embedding or
                    !std.mem.eql(u8, artifact_ref.name, state.artifact_name))
                {
                    return .@"continue";
                }
                const artifact_dims = enrichment_artifact_codec.decodeDenseEmbeddingDims(value) catch |err| {
                    if (isRecoverableEmbeddingArtifactError(err)) return .@"continue";
                    return err;
                };
                if (artifact_dims == state.dims) state.count +|= 1;
                return .@"continue";
            }
        };

        var scan_state = ScanState{
            .alloc = alloc,
            .artifact_name = artifact_name,
            .dims = dims,
            .cancel_check = cancel_check,
        };
        try self.core.store.scanReadTxnWithContext(read_txn, lower, "", .{}, &scan_state, ScanState.scanEntry);
        return scan_state.count;
    }

    fn ensureDenseArtifactTargetCounterForRepair(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        repair_id: u128,
        cancel_check: ?types.RepairCancelCheck,
    ) !void {
        if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) return;
        if (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name) != null) return;

        // Counter bootstrap is a background repair phase in its own right. It
        // can hold a stable store snapshot for a full artifact scan, so admit
        // it before publishing the marker rather than doing unaccounted work
        // that a later shadow-build admission would reject.
        var bootstrap_admission: ?resource_manager_mod.Reservation = if (self.core.index_manager.resource_manager) |manager|
            try reserveDenseCounterBootstrapWorkingSet(manager)
        else
            null;
        defer if (bootstrap_admission) |*reservation| reservation.release();

        var bootstrap_snapshot = self.beginDenseArtifactCounterBootstrapSnapshot(alloc, cfg.name, repair_id) catch |err| switch (err) {
            error.DenseArtifactCounterAlreadyInitialized => return,
            else => return err,
        };
        defer bootstrap_snapshot.deinit();

        const snapshot_count = try self.countDenseArtifactsForConfigFromReadTxn(
            alloc,
            cfg,
            &bootstrap_snapshot.txn,
            cancel_check,
        );
        if (cancel_check) |check| if (check.requested()) return error.Canceled;
        try self.finishDenseArtifactCounterBootstrap(
            alloc,
            cfg.name,
            repair_id,
            bootstrap_snapshot.attempt_id,
            snapshot_count,
        );
    }

    fn validateIndexRepairSourcePreflight(self: *DB, alloc: Allocator, cfg: types.IndexConfig) !void {
        if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) return;
        const target_count = try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name);
        if (target_count == null) return error.RepairSourceCoverageIncomplete;
    }

    fn currentIndexRepairIdMatches(self: *const DB, alloc: Allocator, index_name: []const u8, expected_repair_id: ?u128) !?u128 {
        const repair_id = (try self.indexRepairIdForIndex(alloc, index_name)) orelse {
            if (expected_repair_id != null) return error.StaleIndexRepairControl;
            return null;
        };
        if (expected_repair_id) |expected| {
            if (repair_id != expected) return error.StaleIndexRepairControl;
        }
        return repair_id;
    }

    pub fn pauseAutomaticIndexRepair(self: *DB, alloc: Allocator, index_name: []const u8, expected_repair_id: ?u128) !bool {
        const repair_id = (try self.currentIndexRepairIdMatches(alloc, index_name, expected_repair_id)) orelse return false;
        try self.updateIndexRepairIntent(alloc, repair_id, .{ .automation = .paused });
        _ = self.requestActiveIndexRepairCancellation(index_name);
        return true;
    }

    pub fn cancelCurrentIndexRepairAttempt(self: *DB, alloc: Allocator, index_name: []const u8, expected_repair_id: ?u128) !bool {
        _ = (try self.currentIndexRepairIdMatches(alloc, index_name, expected_repair_id)) orelse return false;
        return self.requestActiveIndexRepairCancellation(index_name);
    }

    pub fn resumeAutomaticIndexRepair(self: *DB, alloc: Allocator, index_name: []const u8, expected_repair_id: ?u128) !bool {
        const repair_id = (try self.currentIndexRepairIdMatches(alloc, index_name, expected_repair_id)) orelse return false;
        try self.updateIndexRepairIntent(alloc, repair_id, .{
            .automation = .enabled,
            .next_retry_at_ms = 0,
            .replace_last_error = true,
        });
        return true;
    }

    fn abandonIndexRepairForDeletion(self: *DB, alloc: Allocator, index_name: []const u8) !void {
        const repair_id = (try self.indexRepairIdForIndex(alloc, index_name)) orelse return;
        if (!(try self.beginIndexRepairLease(index_name))) return error.IndexRepairInProgress;
        defer self.endIndexRepairLease(index_name);
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        if (entry.intent.candidate_relative_path) |candidate| {
            if (!try self.core.index_manager.isRepairCandidateActive(index_name, candidate)) {
                try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
            }
        }
        try self.removeIndexRepairIntentAndPin(alloc, repair_id);
    }

    fn recordIndexRepairAttemptFailure(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        err_name: []const u8,
        terminal: bool,
    ) !void {
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        const now_ms = currentTimeNs() / std.time.ns_per_ms;
        const attempt_count = @max(entry.intent.attempt_count, 1);
        const failure_streak = entry.intent.failure_streak +| 1;
        try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = if (terminal) .terminal else entry.intent.phase,
            .attempt_count = attempt_count,
            .failure_streak = failure_streak,
            .next_retry_at_ms = if (terminal) 0 else now_ms +| indexRepairRetryDelayMs(repair_id, failure_streak),
            .last_error = err_name,
            .replace_last_error = true,
        });
    }

    fn indexRepairFailureIsTerminal(err: anyerror) bool {
        return switch (err) {
            error.InvalidArgument,
            error.NotFound,
            error.UnsupportedOperation,
            error.InvalidIndexRepairState,
            error.InvalidRepairCandidatePath,
            error.ReplicaIdentityMismatch,
            error.DurableIndexRepairStateUnavailable,
            error.RepairSourceCoverageIncomplete,
            error.IndexRepairConfigurationChanged,
            => true,
            else => false,
        };
    }

    fn removeIndexRepairIntentAndPin(self: *DB, alloc: Allocator, repair_id: u128) !void {
        // Pin creation, pin removal, the in-memory pressure gate, and replay
        // truncation must observe one serialization order. Per-index repair
        // leases are insufficient because two different indexes may complete
        // concurrently.
        lockAtomic(self.core.repair_replay_mutex);
        defer self.core.repair_replay_mutex.unlock();
        const path = try self.indexRepairStatePathAlloc(alloc);
        defer alloc.free(path);
        var state = try index_repair_state.load(alloc, path);
        defer state.deinit(alloc);
        const entry = blk: {
            for (state.entries.items) |candidate| {
                if (candidate.intent.repair_id == repair_id) break :blk candidate;
            }
            return error.IndexRepairIntentNotFound;
        };
        if (entry.intent.phase == .cleanup) try self.persistOperatorRepairCompletion(alloc, entry.intent);
        var remaining_replay_pin = false;
        for (state.entries.items) |candidate| {
            if (candidate.intent.repair_id != repair_id and candidate.pin != null) {
                remaining_replay_pin = true;
                break;
            }
        }
        try index_repair_state.removeEntryAndPin(alloc, path, state.identity, .{
            .repair_id = repair_id,
            .revision = entry.intent.revision,
            .phase = entry.intent.phase,
            .config_hash = entry.intent.config_hash,
            .root_generation = entry.intent.root_generation,
            .owner_epoch = entry.intent.owner_epoch,
        });
        self.index_repair_replay_pinned.store(remaining_replay_pin, .release);
        self.core.index_manager.clearRepairUnavailable(entry.intent.index_name);
        notifyQueryVisibilityHook(
            self.async_context,
            if (remaining_replay_pin) .index_repair_pending else .index_repair_cleared,
        );
    }

    pub fn denseRepairWriteBackpressured(self: *const DB) bool {
        if (!self.index_repair_replay_pinned.load(.acquire)) return false;
        const manager = self.core.index_manager.resource_manager orelse return false;
        return manager.denseRepairReplayPressureIsHard();
    }

    fn discardInactiveIndexRepairCandidate(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
    ) !void {
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        const candidate = entry.intent.candidate_relative_path orelse return;
        try index_repair_state.validateCandidateRelativePath(entry.intent.index_name, candidate);
        if (try self.core.index_manager.isRepairCandidateActive(entry.intent.index_name, candidate)) {
            return error.RepairCandidateAlreadyActive;
        }
        const separator = std.mem.indexOfScalar(u8, candidate, '/') orelse return error.InvalidRepairCandidatePath;
        const shadow_root = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ self.core.path, candidate[0..separator] });
        defer alloc.free(shadow_root);
        var io_impl = threadedIo();
        defer io_impl.deinit();
        // `deleteTree` is idempotent for an absent root. A cancelled
        // pre-checkpoint build may already have removed its non-reopenable
        // shadow in the unwind path.
        try std.Io.Dir.cwd().deleteTree(io_impl.io(), shadow_root);
        try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .preflight,
            .replace_candidate_path = true,
            .replace_build_resume_key = true,
            .build_reprocessed = 0,
            .candidate_applied_sequence = 0,
            .target_sequence = self.core.nextDerivedSequence(),
        });
    }

    /// Completes the idempotent half of activation recovery. Returns false
    /// when the recorded candidate is not the active loaded generation, which
    /// means the caller may safely discard/rebuild only that candidate.
    fn reconcileActivatedIndexRepair(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
    ) !bool {
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        const candidate = entry.intent.candidate_relative_path orelse return false;
        try index_repair_state.validateCandidateRelativePath(entry.intent.index_name, candidate);
        if (!try self.core.index_manager.isRepairCandidateActive(entry.intent.index_name, candidate)) return false;
        if (!self.core.index_manager.has(entry.intent.index_name) or
            self.core.index_manager.loadFailure(entry.intent.index_name) != null)
        {
            return false;
        }

        try self.core.index_manager.syncIndexByName(entry.intent.index_name, true);
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, entry.intent.index_name);
        const applied_sequence = @max(checkpoint.applied_sequence, entry.intent.candidate_applied_sequence);
        if (entry.intent.phase != .cleanup or checkpoint.status != .clean or checkpoint.config_hash != entry.intent.config_hash) {
            const update = apply_state.AppliedSequenceUpdate{
                .index_name = entry.intent.index_name,
                .sequence = applied_sequence,
                .status = .clean,
                .generation = checkpoint.generation +| 1,
                .config_hash = entry.intent.config_hash,
            };
            try saveIndexStatusSnapshots(alloc, self.core.store, self.core.index_manager, &[_]apply_state.AppliedSequenceUpdate{update});
            try self.core.saveAppliedSequence(entry.intent.index_name, applied_sequence);
            try self.core.saveProjectionCheckpoint(entry.intent.index_name, .{
                .applied_sequence = update.sequence,
                .status = update.status,
                .generation = update.generation,
                .config_hash = update.config_hash,
            });
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .cleanup,
                .candidate_applied_sequence = applied_sequence,
                .target_sequence = applied_sequence,
                .next_retry_at_ms = 0,
                .replace_last_error = true,
            });
        }
        try self.removeIndexRepairIntentAndPin(alloc, repair_id);
        self.scheduleInactiveRepairShadowCleanup();
        return true;
    }

    /// Rolls a failed-to-load activated candidate back to the exact pointer
    /// captured before activation. The candidate is then inactive and may be
    /// discarded without risking the prior generation. A poisoned in-place
    /// root may still fail to reopen; that is expected and leaves the index
    /// quarantined while a fresh candidate is built.
    fn rollbackUnavailableActivatedIndexRepair(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
    ) !bool {
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);
        if (!entry.intent.previous_pointer_captured) return false;
        const candidate = entry.intent.candidate_relative_path orelse return false;
        if (!try self.core.index_manager.isRepairCandidateActive(entry.intent.index_name, candidate)) return false;
        try self.core.index_manager.restoreActiveIndexRootPointer(
            entry.intent.index_name,
            candidate,
            entry.intent.previous_active_relative_path,
        );
        _ = try self.retryQuarantinedIndexLoads(true);
        try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
        return true;
    }

    /// Cheap startup discovery. This authorizes and durably records repair
    /// debt, but deliberately performs no corpus scan and never touches the
    /// quarantined index root.
    pub fn discoverRecoverableStartupIndexFailures(
        self: *DB,
        alloc: Allocator,
        limit: usize,
    ) !StartupIndexRepairDiscovery {
        var result: StartupIndexRepairDiscovery = .{};
        var state = try self.loadOrCreateCurrentIndexRepairState(alloc);
        defer state.deinit(alloc);
        const path = try self.indexRepairStatePathAlloc(alloc);
        defer alloc.free(path);

        const configs = try self.core.index_manager.listIndexesPublic(alloc);
        defer {
            for (configs) |*cfg| cfg.deinit(alloc);
            alloc.free(configs);
        }
        for (configs) |cfg| {
            const action = self.core.index_manager.recoveryActionForIndex(cfg.name) orelse continue;
            if (state.findIndex(cfg.name)) |i| {
                if (state.entries.items[i].intent.phase == .terminal) {
                    result.terminal += 1;
                    result.existing_terminal += 1;
                } else {
                    result.already_pending += 1;
                }
                continue;
            }
            switch (action) {
                .retry_open => continue,
                .manual_intervention => {
                    result.terminal += 1;
                    continue;
                },
                .rebuild_from_artifacts => {},
            }
            // IncompleteBulkPublish is currently an HBC dense-index failure.
            // Do not let a future reuse of the error name silently broaden the
            // destructive automatic-reconstruction allowlist.
            if (cfg.kind != .dense_vector) {
                result.terminal += 1;
                continue;
            }
            if (result.discovered >= limit) continue;

            const checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
            const now_ms = currentTimeNs() / std.time.ns_per_ms;
            const target_sequence = self.core.nextDerivedSequence();
            const repair_id = try index_repair_state.newRepairId(alloc);
            const index_name = try alloc.dupe(u8, cfg.name);
            var intent = index_repair_state.IndexRepairIntent{
                .repair_id = repair_id,
                .db_identity = state.identity.db_identity,
                .group_id = self.localRepairGroupId(),
                .replica_id = state.identity.replica_id,
                .root_generation = state.identity.root_generation,
                .index_name = index_name,
                .kind = cfg.kind,
                .config_hash = types.indexConfigHash(cfg),
                .detected_sequence = target_sequence,
                .target_sequence = target_sequence,
                .started_at_ms = now_ms,
                .updated_at_ms = now_ms,
                .owner_epoch = 0,
            };
            defer intent.deinit(alloc);
            try index_repair_state.putEntry(alloc, path, state.identity, null, .{ .intent = intent });
            try self.core.index_manager.markRepairUnavailable(cfg.name);
            notifyQueryVisibilityHook(self.async_context, .index_repair_pending);
            result.discovered += 1;

            // Intent durability precedes the serviceability marker. If this
            // checkpoint write fails, restart still rediscovers the intent and
            // completes the transition without deleting the quarantined root.
            try self.core.saveProjectionCheckpoint(cfg.name, .{
                .applied_sequence = checkpoint.applied_sequence,
                .status = .repair_required,
                .generation = checkpoint.generation,
                .config_hash = types.indexConfigHash(cfg),
            });
        }
        return result;
    }

    pub const IndexRepairAdvanceResult = struct {
        repair_id: u128,
        attempted: bool = false,
        repaired: bool = false,
        busy: bool = false,
        deferred: bool = false,
        disk_wait: bool = false,
        terminal: bool = false,
        documents_reprocessed: u64 = 0,
        next_retry_at_ms: u64 = 0,
        has_repair_outcome: bool = false,
        artifacts_repaired: u64 = 0,
        missing_source_docs: u64 = 0,
        failed: u64 = 0,
        unsupported: u64 = 0,
        unresolved: u64 = 0,
        indexes_rebuilt: u64 = 0,
        debt_remaining: bool = false,
    };

    const DurableIndexRepairRunControl = struct {
        db: *DB,
        index_name: []const u8,
        upstream: ?types.RepairCancelCheck,
        ownership: ?types.RepairActivationCheck,

        fn cancelled(ptr: *anyopaque) bool {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.upstream) |check| {
                if (check.requested()) return true;
            }
            if (self.ownership) |check| {
                if (!(check.current() catch return true)) return true;
            }
            return self.db.activeIndexRepairCancellationRequested(self.index_name);
        }
    };

    /// Advances one durable repair intent. Operator repair and the automatic
    /// owner-side executor both enter through this state machine so restart,
    /// cancellation, retries, and pointer reconciliation have one correctness
    /// path.
    const RepairCapacityGuard = struct {
        reservation: *resource_manager_mod.CapacityReservation,
        db: *DB,
        alloc: Allocator,
        repair_id: u128,
        options: types.ArtifactRepairRunOptions,
        admitted_total_bytes: u64,
        headroom_bytes: u64,
        candidate_root: ?[]const u8 = null,

        fn bindCandidateRoot(ptr: *anyopaque, candidate_root: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.candidate_root = candidate_root;
        }

        fn reconcile(ptr: *anyopaque, candidate_bytes: u64) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const required = candidate_bytes +| self.headroom_bytes;
            const next_plan = @max(required, self.admitted_total_bytes);
            const desired_future_claim = next_plan -| candidate_bytes;
            const observation = try repairCapacityObservation(self.options);
            const now_ns = monotonicTimeNs();
            try self.reservation.resize(desired_future_claim, observation, now_ns);
            // Shrinking a claim is admission-free, but this boundary follows
            // materialized writes. Revalidate the remaining aggregate claim
            // against the same fresh observation before advancing state.
            try self.reservation.revalidate(observation, now_ns);
            if (next_plan != self.admitted_total_bytes) {
                try self.db.updateIndexRepairIntent(self.alloc, self.repair_id, .{ .planned_disk_bytes = next_plan });
                self.admitted_total_bytes = next_plan;
            }
        }

        fn revalidate(ptr: *anyopaque) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const observation = try repairCapacityObservation(self.options);
            // Availability already includes materialized candidate bytes,
            // while the reservation describes future growth. Stay on the O(1)
            // path while the conservative claim fits. A failed probe is not a
            // denial yet: reconcile exact candidate bytes first, then let the
            // final revalidation record a real denial only if it still fails.
            if (try self.reservation.fits(observation, monotonicTimeNs())) return;
            if (self.candidate_root) |candidate_root| {
                return try RepairCapacityGuard.reconcile(self, try directoryUsageBytes(self.alloc, candidate_root));
            }
            try self.reservation.revalidate(observation, monotonicTimeNs());
        }
    };

    fn repairCapacityDomain(options: types.ArtifactRepairRunOptions) resource_manager_mod.CapacityDomainId {
        if (options.capacity_source) |source| return source.domain_id;
        return options.capacity_domain_id;
    }

    fn repairCapacityObservation(options: types.ArtifactRepairRunOptions) !resource_manager_mod.CapacityObservation {
        const observed = if (options.capacity_source) |source|
            source.current() catch |err| switch (err) {
                // Capacity observation is an optional backend capability.
                // Unsupported backends still participate in node-wide byte
                // accounting; transient failures from a supported source
                // remain retryable and fail admission closed.
                error.UnsupportedPlatform => resource_manager_mod.CapacityObservation{},
                else => return err,
            }
        else
            options.capacity_observation;
        return .{
            .available_bytes = observed.available_bytes,
            .capacity_bytes = observed.capacity_bytes,
            .observed_at_ns = observed.observed_at_ns,
            .valid_for_ns = observed.valid_for_ns,
        };
    }

    fn artifactBackedDenseRepairEstimate(self: *DB, alloc: Allocator, cfg: types.IndexConfig) !u64 {
        if (!try index_manager_mod.denseConfigRequiresArtifactCoverage(alloc, cfg)) return 0;
        const target_count = (try loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name)) orelse return 0;
        const dims = try index_manager_mod.denseConfigDimensions(alloc, cfg);
        // Candidate storage contains the source vector, HBC node/posting
        // state, quantized payloads, keys, and LSM metadata. Two times the raw
        // vector payload plus a per-vector structural allowance is a
        // deliberately conservative preflight; live boundary checks below
        // remain authoritative as bytes materialize.
        const per_vector = std.math.add(u64, @as(u64, dims) *| @sizeOf(f32), 512) catch std.math.maxInt(u64);
        const logical = std.math.mul(u64, target_count, per_vector) catch std.math.maxInt(u64);
        return std.math.mul(u64, logical, 2) catch std.math.maxInt(u64);
    }

    const RepairWorkingSetPlan = struct {
        reservation_bytes: u64,
        dense_rebuild_batch_items: usize = 2048,
    };

    const dense_counter_bootstrap_working_set_bytes: u64 = 8 * 1024 * 1024;

    fn reserveDenseCounterBootstrapWorkingSet(
        manager: *resource_manager_mod.ResourceManager,
    ) !resource_manager_mod.Reservation {
        const slice_stats = manager.sliceStats(.dense_repair_working_set);
        const hard_available = if (slice_stats.hard_limit_bytes == 0)
            std.math.maxInt(u64)
        else
            slice_stats.hard_limit_bytes -| slice_stats.used_bytes;
        // Let ResourceManager perform an authoritative hard rejection so the
        // shared rejection metric remains accurate under pressure and races.
        if (hard_available < dense_counter_bootstrap_working_set_bytes) {
            return manager.reserve(.dense_repair_working_set, dense_counter_bootstrap_working_set_bytes) catch
                return error.RepairResourceUnavailable;
        }
        const soft_available = if (slice_stats.soft_limit_bytes == 0)
            hard_available
        else
            slice_stats.soft_limit_bytes -| slice_stats.used_bytes;
        if (soft_available < dense_counter_bootstrap_working_set_bytes) {
            return error.RepairResourceUnavailable;
        }
        return manager.reserve(.dense_repair_working_set, dense_counter_bootstrap_working_set_bytes) catch
            return error.RepairResourceUnavailable;
    }

    fn repairWorkingSetPlan(
        alloc: Allocator,
        manager: *resource_manager_mod.ResourceManager,
        cfg: types.IndexConfig,
    ) !RepairWorkingSetPlan {
        const base_bytes: u64 = 8 * 1024 * 1024;
        if (cfg.kind != .dense_vector) return .{ .reservation_bytes = base_bytes };

        const dims = try index_manager_mod.denseConfigDimensions(alloc, cfg);
        // The snapshot scanner owns one decoded vector while the mapper/HBC
        // boundary may transiently own a second copy. Include keys, artifact
        // identity, list capacity, and allocator overhead per item. HBC/LSM
        // caches and routing work remain independently accounted by their own
        // ResourceManager slices.
        const raw_vector_bytes = std.math.mul(u64, dims, @sizeOf(f32)) catch std.math.maxInt(u64);
        const per_item_bytes = (std.math.mul(u64, raw_vector_bytes, 2) catch std.math.maxInt(u64)) +| 2048;
        const desired_items: u64 = 2048;
        const slice_stats = manager.sliceStats(.dense_repair_working_set);
        const hard_available = if (slice_stats.hard_limit_bytes == 0)
            std.math.maxInt(u64)
        else
            slice_stats.hard_limit_bytes -| slice_stats.used_bytes;
        const minimum_reservation = base_bytes +| per_item_bytes;
        // Preserve ResourceManager's authoritative hard-limit rejection and
        // metric. For admissible work, however, size background batches to the
        // soft budget: reaching the hard limit is a safety failure, not a
        // throughput target.
        if (hard_available < minimum_reservation) {
            return .{
                .reservation_bytes = minimum_reservation,
                .dense_rebuild_batch_items = 1,
            };
        }
        const available = if (slice_stats.soft_limit_bytes == 0)
            hard_available
        else
            slice_stats.soft_limit_bytes -| slice_stats.used_bytes;
        if (available < minimum_reservation) return error.RepairResourceUnavailable;
        const fitting_items = if (available <= base_bytes)
            0
        else
            (available - base_bytes) / @max(@as(u64, 1), per_item_bytes);
        const batch_items = @min(desired_items, fitting_items);
        return .{
            .reservation_bytes = base_bytes +| (per_item_bytes *| batch_items),
            .dense_rebuild_batch_items = if (comptime builtin.is_test)
                test_dense_repair_rebuild_batch_size orelse @as(usize, @intCast(batch_items))
            else
                @intCast(batch_items),
        };
    }

    pub fn advanceIndexRepairIntent(
        self: *DB,
        alloc: Allocator,
        repair_id: u128,
        options: types.ArtifactRepairRunOptions,
    ) anyerror!IndexRepairAdvanceResult {
        var result = IndexRepairAdvanceResult{ .repair_id = repair_id };
        var effective_options = options;
        if (effective_options.capacity_source == null) effective_options.capacity_source = self.capacity_source;
        var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer entry.deinit(alloc);

        if (entry.intent.root_generation != self.core.root_generation or
            entry.intent.group_id != self.localRepairGroupId())
        {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, "repair_identity_mismatch", true);
            result.terminal = true;
            return result;
        }
        if (entry.intent.phase == .terminal) {
            result.terminal = true;
            return result;
        }
        if (entry.intent.automation == .paused) {
            result.deferred = true;
            return result;
        }
        const now_ms = currentTimeNs() / std.time.ns_per_ms;
        if (entry.intent.next_retry_at_ms > now_ms) {
            result.deferred = true;
            result.next_retry_at_ms = entry.intent.next_retry_at_ms;
            return result;
        }
        checkArtifactRepairActivationOwner(options) catch |err| switch (err) {
            error.RepairOwnershipLost => {
                result.deferred = true;
                return result;
            },
            else => return err,
        };

        // Claim the durable state machine with the same epoch captured by the
        // owner-side activation fence. A later term/root owner may safely
        // reclaim the intent, but every subsequent transition and the final
        // activation in this attempt are CAS-fenced by the new epoch.
        if (options.owner_epoch != 0 and entry.intent.owner_epoch != options.owner_epoch) {
            try self.updateIndexRepairIntent(alloc, repair_id, .{ .owner_epoch = options.owner_epoch });
            entry.intent.owner_epoch = options.owner_epoch;
        }

        const cfg_ptr = self.core.index_manager.get(entry.intent.index_name) orelse {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, "index_configuration_missing", true);
            result.terminal = true;
            return result;
        };
        if (cfg_ptr.kind != entry.intent.kind or types.indexConfigHash(cfg_ptr.*) != entry.intent.config_hash) {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, "index_configuration_changed", true);
            result.terminal = true;
            return result;
        }

        // Missing-counter projections bootstrap coverage from a stable primary
        // snapshot plus an atomically maintained concurrent-write delta. The
        // durable repair intent authorizes retry after cancellation or restart;
        // no candidate directory is created until authoritative coverage exists.
        self.ensureDenseArtifactTargetCounterForRepair(
            alloc,
            cfg_ptr.*,
            repair_id,
            effective_options.cancel_check,
        ) catch |err| switch (err) {
            error.Canceled, error.StaleDenseArtifactCounterBootstrap => {
                result.attempted = true;
                result.deferred = true;
                return result;
            },
            error.RepairResourceUnavailable => {
                const attempt_count = entry.intent.attempt_count +| 1;
                const failure_streak = entry.intent.failure_streak +| 1;
                const next_retry_at_ms = now_ms +| indexRepairRetryDelayMs(repair_id, failure_streak);
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .attempt_count = attempt_count,
                    .failure_streak = failure_streak,
                    .next_retry_at_ms = next_retry_at_ms,
                    .last_error = "RepairResourceUnavailable",
                    .replace_last_error = true,
                });
                result.attempted = true;
                result.deferred = true;
                result.next_retry_at_ms = next_retry_at_ms;
                return result;
            },
            else => return err,
        };

        // Automatic reconstruction is destructive only at pointer activation,
        // but creating an apparently valid empty candidate from missing source
        // metadata is still unsafe. Full per-artifact validation remains part
        // of the shadow build.
        self.validateIndexRepairSourcePreflight(alloc, cfg_ptr.*) catch |err| {
            const err_name = if (err == error.RepairSourceCoverageIncomplete)
                "dense_artifact_coverage_missing"
            else
                @errorName(err);
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, err_name, true);
            result.attempted = true;
            result.terminal = true;
            return result;
        };

        const active_index_bytes = self.core.index_manager.activeIndexStorageBytes(entry.intent.index_name) catch 0;
        const source_estimate = self.artifactBackedDenseRepairEstimate(alloc, cfg_ptr.*) catch 0;
        var estimated_candidate_bytes = @max(
            entry.intent.estimated_candidate_bytes,
            @max(options.estimated_candidate_bytes, @max(active_index_bytes, source_estimate)),
        );
        if (estimated_candidate_bytes == 0) {
            estimated_candidate_bytes = 64 * 1024 * 1024;
        }
        const cleanup_and_replay_headroom = @max(estimated_candidate_bytes / 4, 256 * 1024 * 1024);
        const required_disk_bytes = estimated_candidate_bytes +| cleanup_and_replay_headroom;
        const planned_disk_bytes = @max(
            entry.intent.planned_disk_bytes,
            @max(options.planned_disk_bytes, required_disk_bytes),
        );
        if (entry.intent.estimated_candidate_bytes != estimated_candidate_bytes or
            entry.intent.planned_disk_bytes != planned_disk_bytes)
        {
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                .estimated_candidate_bytes = estimated_candidate_bytes,
                .planned_disk_bytes = planned_disk_bytes,
            });
            entry.intent.estimated_candidate_bytes = estimated_candidate_bytes;
            entry.intent.planned_disk_bytes = planned_disk_bytes;
        }

        // A process may stop after pointer activation but before publishing a
        // clean checkpoint or deleting the intent. Never rebuild in that case:
        // prove that the recorded candidate is active and loaded, finish the
        // validation checkpoint, then atomically release intent and replay pin.
        if (entry.intent.phase == .activating or
            entry.intent.phase == .validating or
            entry.intent.phase == .cleanup)
        {
            if (entry.intent.candidate_relative_path == null) {
                try self.recordIndexRepairAttemptFailure(alloc, repair_id, "activated_candidate_missing", true);
                result.terminal = true;
                return result;
            }
            if (try self.reconcileActivatedIndexRepair(alloc, repair_id)) {
                result.attempted = true;
                result.repaired = true;
                return result;
            }
            const rolled_back = try self.rollbackUnavailableActivatedIndexRepair(alloc, repair_id);
            // `activating` was persisted before the pointer write. If the
            // candidate is not active, retain the ready generation and resume
            // convergence. This transition is authorized only after the durable
            // pointer was checked above; an ambiguous or failed rollback leaves
            // the intent in `activating` and fails closed.
            if (!rolled_back) {
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .waiting_for_convergence,
                });
                entry.intent.phase = .waiting_for_convergence;
            }
        }

        // Capacity is checked and claimed through the shared ResourceManager
        // so every DB on the node participates in one admission domain. Existing
        // candidate bytes are already reflected in filesystem availability;
        // reserve only the remaining growth and cleanup headroom on resume.
        // Reconciliation above is intentionally admission-free because it
        // releases space and must remain possible on an already-full volume.
        var candidate_bytes: u64 = 0;
        if (entry.intent.candidate_relative_path) |candidate| {
            try index_repair_state.validateCandidateRelativePath(entry.intent.index_name, candidate);
            const separator = std.mem.indexOfScalar(u8, candidate, '/') orelse return error.InvalidRepairCandidatePath;
            const candidate_root = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ self.core.path, candidate[0..separator] });
            defer alloc.free(candidate_root);
            candidate_bytes = directoryUsageBytes(alloc, candidate_root) catch 0;
        }
        const remaining_disk_claim = planned_disk_bytes -| @min(planned_disk_bytes, candidate_bytes);
        const manager = self.core.index_manager.resource_manager orelse return error.ResourceManagerUnavailable;
        const first_capacity = repairCapacityObservation(effective_options) catch |err| {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, @errorName(err), false);
            result.deferred = true;
            result.disk_wait = true;
            return result;
        };
        var disk_reservation = manager.reserveCapacity(
            alloc,
            repairCapacityDomain(effective_options),
            remaining_disk_claim,
            first_capacity,
            monotonicTimeNs(),
        ) catch |err| switch (err) {
            error.CapacityUnavailable, error.CapacityObservationStale => {
                try self.recordIndexRepairAttemptFailure(alloc, repair_id, "disk_admission_unavailable", false);
                result.deferred = true;
                result.disk_wait = true;
                var updated = try self.loadIndexRepairEntryById(alloc, repair_id);
                defer updated.deinit(alloc);
                result.next_retry_at_ms = updated.intent.next_retry_at_ms;
                return result;
            },
            else => return err,
        };
        defer disk_reservation.release();
        var capacity_guard = RepairCapacityGuard{
            .reservation = &disk_reservation,
            .db = self,
            .alloc = alloc,
            .repair_id = repair_id,
            .options = effective_options,
            .admitted_total_bytes = planned_disk_bytes,
            .headroom_bytes = cleanup_and_replay_headroom,
        };

        const attempt_count = entry.intent.attempt_count +| 1;
        try self.updateIndexRepairIntent(alloc, repair_id, .{
            .attempt_count = attempt_count,
            .next_retry_at_ms = 0,
        });
        entry.intent.attempt_count = attempt_count;
        result.attempted = true;
        var run_control = DurableIndexRepairRunControl{
            .db = self,
            .index_name = entry.intent.index_name,
            .upstream = options.cancel_check,
            .ownership = options.activation_check,
        };
        var run_options = effective_options;
        run_options.cancel_check = .{
            .ptr = &run_control,
            .is_requested = DurableIndexRepairRunControl.cancelled,
        };
        run_options.capacity_check = .{
            .ptr = &capacity_guard,
            .reconcile = RepairCapacityGuard.reconcile,
            .revalidate = RepairCapacityGuard.revalidate,
            .bind_candidate_root = RepairCapacityGuard.bindCandidateRoot,
        };
        run_options.executing_durable_index_repair = true;
        const artifact_kind = artifactRepairKindForIndexKind(entry.intent.kind) orelse {
            try self.recordIndexRepairAttemptFailure(alloc, repair_id, "unsupported_index_kind", true);
            result.terminal = true;
            return result;
        };
        const repair = self.repairArtifactIssuesWithRequestOptions(alloc, .{
            .target = .index,
            .artifact_kind = artifact_kind,
            .index_name = entry.intent.index_name,
            .limit = 1,
            .force = true,
        }, run_options) catch |err| {
            // Fault-injection hooks model process loss, not an ordinary
            // returned repair failure. Let the test harness observe the
            // injected stop without persisting retry/backoff state that a
            // crashed process could never have written.
            if (comptime builtin.is_test) {
                if (self.shadow_index_repair_hook != null and std.mem.startsWith(u8, @errorName(err), "Test")) {
                    return err;
                }
            }
            if (err == error.Canceled and run_options.cancelled()) {
                result.deferred = true;
                return result;
            }
            const capacity_wait = err == error.CapacityUnavailable or err == error.CapacityObservationStale;
            try self.recordIndexRepairAttemptFailure(
                alloc,
                repair_id,
                if (capacity_wait) "disk_admission_unavailable" else @errorName(err),
                indexRepairFailureIsTerminal(err),
            );
            result.disk_wait = capacity_wait;
            if (indexRepairFailureIsTerminal(err)) {
                result.terminal = true;
            } else {
                result.deferred = true;
                var updated = try self.loadIndexRepairEntryById(alloc, repair_id);
                defer updated.deinit(alloc);
                result.next_retry_at_ms = updated.intent.next_retry_at_ms;
            }
            return result;
        };
        result.documents_reprocessed = repair.reprocessed;
        result.has_repair_outcome = true;
        result.artifacts_repaired = repair.repaired;
        result.missing_source_docs = repair.missing_source_docs;
        result.failed = repair.failed;
        result.unsupported = repair.unsupported;
        result.unresolved = repair.unresolved;
        result.indexes_rebuilt = repair.indexes_rebuilt;
        result.debt_remaining = repair.debt_remaining;

        // A committed replacement wins a cancellation observed after the
        // final pointer/checkpoint publication. Artifact debt discovered
        // during the rebuild remains in its own durable queue and must not
        // resurrect the already-completed generation intent.
        if (repair.indexes_rebuilt != 0 or repair.repaired != 0) {
            result.repaired = true;
            return result;
        }

        // Cooperative owner shutdown is not a failed repair attempt. Durable
        // snapshot/catch-up boundaries have already left the candidate in a
        // resumable phase, so preserve its retry schedule and let the next
        // owner continue immediately.
        if (run_options.cancelled()) {
            result.deferred = true;
            return result;
        }
        if (repair.in_progress != 0) {
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                .failure_streak = 0,
                .next_retry_at_ms = 0,
                .replace_last_error = true,
            });
            result.busy = true;
            return result;
        }
        try self.recordIndexRepairAttemptFailure(alloc, repair_id, "repair_attempt_incomplete", false);
        result.deferred = true;
        var updated = try self.loadIndexRepairEntryById(alloc, repair_id);
        defer updated.deinit(alloc);
        result.next_retry_at_ms = updated.intent.next_retry_at_ms;
        return result;
    }

    pub const StartupIndexRepairResult = struct {
        discovered: usize = 0,
        attempted: usize = 0,
        repaired: usize = 0,
        remaining: usize = 0,
        terminal: usize = 0,
        deferred: usize = 0,
        busy: usize = 0,
        disk_waits: usize = 0,
        documents_reprocessed: u64 = 0,
        next_retry_at_ms: u64 = 0,
    };

    /// Bounded owner-side pass used by managed startup workers and periodic
    /// repair scans. Discovery itself is cheap; callers choose when execution
    /// is admitted by passing a small `limit` (normally one per node).
    pub fn repairRecoverableStartupIndexFailures(
        self: *DB,
        alloc: Allocator,
        limit: usize,
        options: types.ArtifactRepairRunOptions,
    ) !StartupIndexRepairResult {
        var result: StartupIndexRepairResult = .{};
        const discovery = try self.discoverRecoverableStartupIndexFailures(alloc, limit);
        result.discovered = discovery.discovered;
        // Existing terminal intents are counted from the durable state below.
        // Discovery contributes only terminal load failures for which no intent
        // exists, avoiding double-counting checkpointed failures.
        result.terminal = discovery.terminal - discovery.existing_terminal;

        var state = try self.loadIndexRepairState(alloc);
        defer state.deinit(alloc);
        const Candidate = struct {
            repair_id: u128,
            started_at_ms: u64,
        };
        var candidates = std.ArrayListUnmanaged(Candidate).empty;
        defer candidates.deinit(alloc);
        const now_ms = currentTimeNs() / std.time.ns_per_ms;
        for (state.entries.items) |entry| {
            if (entry.intent.phase == .terminal) {
                result.terminal += 1;
                continue;
            }
            if (entry.intent.automation == .paused or entry.intent.next_retry_at_ms > now_ms) {
                result.deferred += 1;
                if (entry.intent.next_retry_at_ms != 0 and
                    (result.next_retry_at_ms == 0 or entry.intent.next_retry_at_ms < result.next_retry_at_ms))
                {
                    result.next_retry_at_ms = entry.intent.next_retry_at_ms;
                }
                continue;
            }
            try candidates.append(alloc, .{
                .repair_id = entry.intent.repair_id,
                .started_at_ms = entry.intent.started_at_ms,
            });
        }
        std.mem.sort(Candidate, candidates.items, {}, struct {
            fn lessThan(_: void, a: Candidate, b: Candidate) bool {
                if (a.started_at_ms != b.started_at_ms) return a.started_at_ms < b.started_at_ms;
                return a.repair_id < b.repair_id;
            }
        }.lessThan);
        for (candidates.items[0..@min(limit, candidates.items.len)]) |candidate| {
            const advanced = try self.advanceIndexRepairIntent(alloc, candidate.repair_id, options);
            result.attempted += @intFromBool(advanced.attempted);
            result.repaired += @intFromBool(advanced.repaired);
            result.deferred += @intFromBool(advanced.deferred);
            result.disk_waits += @intFromBool(advanced.disk_wait);
            result.busy += @intFromBool(advanced.busy);
            result.documents_reprocessed += advanced.documents_reprocessed;
            if (advanced.next_retry_at_ms != 0 and
                (result.next_retry_at_ms == 0 or advanced.next_retry_at_ms < result.next_retry_at_ms))
            {
                result.next_retry_at_ms = advanced.next_retry_at_ms;
            }
        }
        var after = try self.loadIndexRepairState(alloc);
        defer after.deinit(alloc);
        result.remaining = after.entries.items.len;
        return result;
    }

    pub fn repairArtifactIssuesWithRequest(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairRunRequest,
    ) !types.ArtifactRepairResult {
        return try self.repairArtifactIssuesWithRequestOptions(alloc, req, .{});
    }

    pub fn repairArtifactIssuesWithRequestOptions(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairRunRequest,
        options: types.ArtifactRepairRunOptions,
    ) !types.ArtifactRepairResult {
        try checkArtifactRepairCancelled(options);
        if (req.target == .index) return try self.repairIndexIssuesWithRequest(alloc, req, options);

        const page = try self.listArtifactRepairIssuesPage(alloc, .{
            .artifact_kind = req.artifact_kind,
            .index_name = req.index_name,
            .limit = req.limit,
            .cursor = req.cursor,
        });
        defer {
            types.freeArtifactRepairIssues(alloc, page.issues);
            if (page.next_cursor) |cursor| alloc.free(cursor);
        }

        var result: types.ArtifactRepairResult = .{
            .limit = req.limit,
            .has_more = page.has_more,
            .debt_remaining = page.has_more,
        };
        if (page.next_cursor) |cursor| {
            result.next_cursor = try alloc.dupe(u8, cursor);
        }
        for (page.issues) |*issue| {
            if (options.cancelled()) {
                result.unresolved += 1;
                result.debt_remaining = true;
                return result;
            }
            result.scanned += 1;
            issue.attempts += 1;
            issue.last_seen_ns = currentTimeNs();

            if (!artifactRepairKindHasReprocessor(issue.artifact_kind)) {
                const unsupported_reason = artifactRepairUnsupportedReason(issue.artifact_kind);
                issue.repairable = false;
                if (issue.unsupported_reason.len == 0) {
                    issue.unsupported_reason = try alloc.dupe(u8, unsupported_reason);
                }
                try replaceRepairIssueLastError(alloc, issue, unsupported_reason);
                try saveArtifactRepairIssueToStore(alloc, self.core.store, issue.*);
                result.unsupported += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
                continue;
            }

            const reprocessed = self.reprocessArtifactIssue(alloc, issue.*) catch |err| switch (err) {
                error.NotFound => {
                    try replaceRepairIssueLastError(alloc, issue, "source_document_missing");
                    try saveArtifactRepairIssueToStore(alloc, self.core.store, issue.*);
                    result.missing_source_docs += 1;
                    result.unresolved += 1;
                    result.debt_remaining = true;
                    continue;
                },
                else => {
                    try replaceRepairIssueLastError(alloc, issue, @errorName(err));
                    try saveArtifactRepairIssueToStore(alloc, self.core.store, issue.*);
                    result.failed += 1;
                    result.unresolved += 1;
                    result.debt_remaining = true;
                    continue;
                },
            };
            if (!reprocessed) {
                const unavailable_error = switch (issue.artifact_kind) {
                    .embedding => "embedding_enrichment_unavailable",
                    else => "artifact_reprocessor_unavailable",
                };
                try replaceRepairIssueLastError(alloc, issue, unavailable_error);
                try saveArtifactRepairIssueToStore(alloc, self.core.store, issue.*);
                result.failed += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
                continue;
            }
            result.reprocessed += 1;
            if (try self.artifactNowReadable(alloc, issue.*)) {
                try self.clearArtifactRepairIssue(alloc, issue.*);
                result.repaired += 1;
            } else {
                try replaceRepairIssueLastError(alloc, issue, "artifact_still_unreadable");
                try saveArtifactRepairIssueToStore(alloc, self.core.store, issue.*);
                result.failed += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
            }
        }
        if (result.repaired != 0) {
            self.runDerivedUntil(self.core.nextDerivedSequence()) catch |err| switch (err) {
                error.ArtifactRepairRequired => {},
                else => return err,
            };
            try self.runArtifactRepairMetadataMaintenanceUntilIdle();
        }
        return result;
    }

    fn repairIndexIssuesWithRequest(
        self: *DB,
        alloc: Allocator,
        req: types.ArtifactRepairRunRequest,
        options: types.ArtifactRepairRunOptions,
    ) !types.ArtifactRepairResult {
        try checkArtifactRepairCancelled(options);
        const requested_index = req.index_name orelse return error.InvalidArgument;
        if (req.cursor != null and req.cursor.?.len != 0) return error.InvalidArgument;
        const limit = if (req.limit == 0) @as(u32, 100) else req.limit;
        var result = types.ArtifactRepairResult{ .limit = limit };
        if (limit == 0) return result;
        if (req.control == null and req.repair_id != null) return error.InvalidArgument;

        const cfg_ptr = self.core.index_manager.get(requested_index) orelse return error.NotFound;
        var cfg = try types.IndexConfig.clone(alloc, cfg_ptr.*);
        defer cfg.deinit(alloc);

        if (req.control) |control| {
            if (req.force or req.cursor != null or req.artifact_kind != null) return error.InvalidArgument;
            const applied = switch (control) {
                .pause_automatic => try self.pauseAutomaticIndexRepair(alloc, requested_index, req.repair_id),
                .resume_automatic => try self.resumeAutomaticIndexRepair(alloc, requested_index, req.repair_id),
                .cancel_current_attempt => try self.cancelCurrentIndexRepairAttempt(alloc, requested_index, req.repair_id),
            };
            result.scanned = 1;
            result.controls_applied = @intFromBool(applied);
            result.debt_remaining = applied;
            return result;
        }

        if (req.artifact_kind) |kind| {
            const matches_kind = switch (cfg.kind) {
                .dense_vector, .sparse_vector => kind == .embedding,
                .graph => kind == .graph,
                .full_text => kind == .full_text,
                .algebraic => kind == .algebraic,
            };
            if (!matches_kind) return error.NotFound;
        }

        const repair_required = try self.indexRepairRequired(alloc, cfg.name);
        if (!repair_required and !req.force) return result;
        if ((req.repair_job_id == null) != (req.repair_job_created_at_ms == null)) return error.InvalidArgument;
        const repair_job_created_at_ms = req.repair_job_created_at_ms orelse 0;
        if (req.force and req.repair_job_id != null and try self.operatorRepairAlreadyCompleted(
            alloc,
            cfg,
            req.repair_job_id.?,
            repair_job_created_at_ms,
        )) {
            result.scanned = 1;
            result.repaired = 1;
            result.indexes_rebuilt = 1;
            return result;
        }

        const had_load_failure = self.core.index_manager.loadFailure(cfg.name) != null;
        var durable_repair_id = try self.indexRepairIdForIndex(alloc, cfg.name);
        if (had_load_failure and self.core.index_manager.recoveryActionForIndex(cfg.name) == .rebuild_from_artifacts) {
            _ = try self.discoverRecoverableStartupIndexFailures(alloc, 1);
            durable_repair_id = try self.indexRepairIdForIndex(alloc, cfg.name);
        }
        if (try self.classifyCurrentDenseGenerationRepair(alloc, cfg)) |classification| {
            durable_repair_id = try self.ensureAutomaticDenseGenerationRepairIntent(
                alloc,
                cfg,
                classification.trigger,
                classification.last_error,
            );
        } else if (durable_repair_id == null and cfg.kind != .algebraic) {
            durable_repair_id = try self.createOperatorGenerationRepairIntent(
                alloc,
                cfg,
                req.repair_job_id orelse 0,
                repair_job_created_at_ms,
            );
        }
        if (durable_repair_id) |repair_id| {
            if (req.force and req.repair_job_id != null) {
                try self.attachOperatorRepairRequest(
                    alloc,
                    repair_id,
                    req.repair_job_id.?,
                    repair_job_created_at_ms,
                );
            }
        }

        // Public/operator entry points never execute a durable generation
        // rebuild through this lower-level function. Managed callers enqueue
        // the exact group; standalone callers synchronously enter the same
        // admitted state machine used by the owner-side scheduler.
        if (durable_repair_id) |repair_id| if (!options.executing_durable_index_repair) {
            result.scanned = 1;
            if (had_load_failure) result.indexes_degraded = 1;
            if (req.force) {
                var current = try self.loadIndexRepairEntryById(alloc, repair_id);
                defer current.deinit(alloc);
                if (current.intent.phase == .terminal) {
                    try self.updateIndexRepairIntent(alloc, repair_id, .{
                        .phase = .detected,
                        .attempt_count = current.intent.attempt_count +| 1,
                        .failure_streak = 0,
                        .next_retry_at_ms = 0,
                        .replace_last_error = true,
                    });
                }
            }
            if (options.defer_durable_index_repair_execution) {
                result.in_progress = 1;
                result.unresolved = 1;
                result.debt_remaining = true;
                return result;
            }
            const advanced = try self.advanceIndexRepairIntent(alloc, repair_id, options);
            result.reprocessed = advanced.documents_reprocessed;
            if (advanced.has_repair_outcome and advanced.repaired) {
                result.repaired = advanced.artifacts_repaired;
                result.missing_source_docs = advanced.missing_source_docs;
                result.failed = advanced.failed;
                result.unsupported = advanced.unsupported;
                result.unresolved = advanced.unresolved;
                result.indexes_rebuilt = advanced.indexes_rebuilt;
                result.debt_remaining = advanced.debt_remaining;
            } else if (advanced.repaired) {
                result.repaired = 1;
                result.indexes_rebuilt = 1;
            } else if (advanced.terminal) {
                result.failed = 1;
                result.unresolved = 1;
                result.debt_remaining = true;
            } else {
                result.in_progress = 1;
                result.unresolved = 1;
                result.debt_remaining = true;
            }
            return result;
        };

        if (!(try self.beginIndexRepairLease(cfg.name))) {
            result.scanned += 1;
            result.in_progress += 1;
            result.unresolved += 1;
            result.debt_remaining = true;
            return result;
        }
        defer self.endIndexRepairLease(cfg.name);

        result.scanned += 1;
        if (durable_repair_id) |repair_id| {
            if (try self.reconcileActivatedIndexRepair(alloc, repair_id)) {
                result.repaired += 1;
                return result;
            }
            _ = try self.rollbackUnavailableActivatedIndexRepair(alloc, repair_id);
            var durable_entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer durable_entry.deinit(alloc);
            const resumable = durable_entry.intent.candidate_relative_path != null and switch (durable_entry.intent.phase) {
                .building => durable_entry.intent.build_resume_key != null and cfg.kind == .dense_vector,
                .catching_up, .ready, .waiting_for_convergence => true,
                else => false,
            };
            if (durable_entry.intent.phase == .terminal) {
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .detected,
                    .attempt_count = durable_entry.intent.attempt_count +| 1,
                    .failure_streak = 0,
                    .next_retry_at_ms = 0,
                    .replace_last_error = true,
                });
                durable_entry.intent.phase = .detected;
            }
            if (!resumable and durable_entry.intent.phase != .preflight) {
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .preflight,
                    .attempt_count = @max(@as(u32, 1), durable_entry.intent.attempt_count),
                    .failure_streak = 0,
                    .next_retry_at_ms = 0,
                    .replace_last_error = true,
                });
            }
            self.ensureDenseArtifactTargetCounterForRepair(
                alloc,
                cfg,
                repair_id,
                options.cancel_check,
            ) catch |err| switch (err) {
                error.Canceled, error.StaleDenseArtifactCounterBootstrap => {
                    result.in_progress += 1;
                    result.unresolved += 1;
                    result.debt_remaining = true;
                    return result;
                },
                else => return err,
            };
            self.validateIndexRepairSourcePreflight(alloc, cfg) catch |err| {
                const err_name = if (err == error.RepairSourceCoverageIncomplete)
                    "dense_artifact_coverage_missing"
                else
                    @errorName(err);
                try self.recordIndexRepairAttemptFailure(alloc, repair_id, err_name, true);
                result.failed += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
                return result;
            };
        }
        if (had_load_failure) result.indexes_degraded += 1;
        if (self.core.index_manager.loadFailure(cfg.name) != null) {
            const recovery_action = self.core.index_manager.recoveryActionForIndex(cfg.name).?;
            switch (recovery_action) {
                .retry_open, .manual_intervention => {
                    // Explicit named operator repair may first retry any
                    // quarantined open. This does not broaden the automatic
                    // destructive-rebuild allowlist.
                    _ = try self.retryQuarantinedIndexLoads(true);
                    if (self.core.index_manager.loadFailure(cfg.name) != null and recovery_action == .retry_open) {
                        result.failed += 1;
                        result.unresolved += 1;
                        result.debt_remaining = true;
                        return result;
                    }
                },
                .rebuild_from_artifacts => {
                    // Build directly from the retained status-only config. The
                    // quarantined root remains untouched until the replacement
                    // is durable and activated by pointer swap.
                },
            }
        }
        if (had_load_failure and self.core.index_manager.loadFailure(cfg.name) == null and (cfg.kind == .full_text or cfg.kind == .algebraic) and !try self.indexRepairRequired(alloc, cfg.name)) {
            result.repaired += 1;
            return result;
        }

        if (cfg.kind == .algebraic) {
            result.unsupported += 1;
            result.unresolved += 1;
            result.debt_remaining = true;
            return result;
        }
        const rebuilt = self.rebuildIndexWithShadowReplacement(alloc, cfg, options, durable_repair_id) catch |err| switch (err) {
            error.Canceled => {
                result.unresolved += 1;
                result.debt_remaining = true;
                return result;
            },
            error.ShadowIndexCatchUpIncomplete => {
                result.failed += 1;
                result.unresolved += 1;
                result.debt_remaining = true;
                return result;
            },
            else => return err,
        };
        result.reprocessed += rebuilt.reprocessed;
        if (rebuilt.yielded) {
            result.in_progress += 1;
            result.unresolved += 1;
            result.debt_remaining = true;
            return result;
        }
        result.indexes_rebuilt += 1;
        if (try self.indexRepairRequired(alloc, cfg.name)) {
            result.unresolved += 1;
            result.debt_remaining = true;
        } else {
            result.repaired += 1;
        }
        return result;
    }

    const ShadowIndexReplacementResult = struct {
        reprocessed: u64 = 0,
        applied_sequence: u64 = 0,
        yielded: bool = false,
    };

    fn rebuildIndexWithShadowReplacement(
        self: *DB,
        alloc: Allocator,
        cfg: types.IndexConfig,
        options: types.ArtifactRepairRunOptions,
        durable_repair_id: ?u128,
    ) !ShadowIndexReplacementResult {
        try checkArtifactRepairCancelled(options);
        const working_set_plan = if (self.core.index_manager.resource_manager) |manager|
            try repairWorkingSetPlan(alloc, manager, cfg)
        else
            RepairWorkingSetPlan{ .reservation_bytes = 0 };
        var repair_admission: ?resource_manager_mod.Reservation = if (self.core.index_manager.resource_manager) |manager|
            manager.reserve(.dense_repair_working_set, working_set_plan.reservation_bytes) catch
                return error.RepairResourceUnavailable
        else
            null;
        defer if (repair_admission) |*reservation| reservation.release();

        // A forced dense rebuild is initially fail-closed. Only the admitted
        // background worker may prove the current generation safe enough to
        // remain online during shadow construction. Automatic anomaly
        // classifications stay fail-closed and reuse the same reconstruction.
        if (durable_repair_id) |repair_id| {
            var durable_entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer durable_entry.deinit(alloc);
            if (durable_entry.intent.trigger == .operator_generation_validation) {
                switch (try self.validateOperatorDenseGenerationForOnlineRebuild(alloc, cfg, options)) {
                    .online_safe => try self.updateIndexRepairIntent(alloc, repair_id, .{
                        .trigger = .operator_generation_rebuild,
                        .replace_last_error = true,
                    }),
                    .replay_pending => return error.OperatorGenerationValidationPending,
                    .fail_closed => |classification| try self.updateIndexRepairIntent(alloc, repair_id, .{
                        .trigger = classification.trigger,
                        .last_error = classification.last_error,
                        .replace_last_error = true,
                    }),
                }
            }
        }
        var resume_candidate = false;
        var resume_building = false;
        var resume_requires_ready_manifest = false;
        var persisted_build_floor_sequence: u64 = 0;
        var persisted_build_reprocessed: u64 = 0;
        var build_resume_key: ?[]u8 = null;
        defer if (build_resume_key) |key| alloc.free(key);
        const generation_id = durable_repair_id orelse try index_repair_state.newRepairId(alloc);
        var shadow_base: []u8 = undefined;
        if (durable_repair_id) |repair_id| {
            var entry = try self.loadIndexRepairEntryById(alloc, repair_id);
            defer entry.deinit(alloc);
            const resumable_phase = switch (entry.intent.phase) {
                .building => entry.intent.build_resume_key != null and cfg.kind == .dense_vector,
                .catching_up, .ready, .waiting_for_convergence => true,
                else => false,
            };
            if (resumable_phase and entry.intent.candidate_relative_path != null) {
                const candidate = entry.intent.candidate_relative_path.?;
                try index_repair_state.validateCandidateRelativePath(cfg.name, candidate);
                const separator = std.mem.indexOfScalar(u8, candidate, '/') orelse return error.InvalidRepairCandidatePath;
                shadow_base = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ self.core.path, candidate[0..separator] });
                resume_candidate = true;
                resume_building = entry.intent.phase == .building;
                resume_requires_ready_manifest = entry.intent.phase == .ready or entry.intent.phase == .waiting_for_convergence;
                persisted_build_floor_sequence = entry.intent.build_floor_sequence;
                persisted_build_reprocessed = entry.intent.build_reprocessed;
                build_resume_key = if (entry.intent.build_resume_key) |key| try alloc.dupe(u8, key) else null;
            } else {
                try self.discardInactiveIndexRepairCandidate(alloc, repair_id);
                shadow_base = try createUniqueRepairShadowBase(alloc, self.core.path);
            }
        } else {
            shadow_base = try createUniqueRepairShadowBase(alloc, self.core.path);
        }
        if (!resume_candidate) try index_manager_mod.IndexManager.writeRepairShadowInProgressMarker(alloc, shadow_base);
        var shadow_installed = false;
        var candidate_reopenable = resume_candidate;
        defer {
            var io_impl = threadedIo();
            defer io_impl.deinit();
            if (!shadow_installed and !candidate_reopenable) {
                index_manager_mod.IndexManager.clearRepairShadowInProgressMarker(alloc, shadow_base) catch {};
                std.Io.Dir.cwd().deleteTree(io_impl.io(), shadow_base) catch {};
            }
            alloc.free(shadow_base);
        }
        const shadow_indexes_path = try std.fmt.allocPrint(alloc, "{s}/indexes", .{shadow_base});
        defer alloc.free(shadow_indexes_path);
        if (!resume_candidate) try ensureDirPath(shadow_indexes_path);

        const shadow_index_path = try std.fmt.allocPrint(alloc, "{s}/{s}", .{ shadow_indexes_path, cfg.name });
        defer alloc.free(shadow_index_path);
        const shadow_checkpoint_path = try std.fmt.allocPrint(alloc, "{s}/applied-sequences", .{shadow_base});
        defer alloc.free(shadow_checkpoint_path);
        if (options.capacity_check) |check| try check.bindCandidateRoot(shadow_base);
        if (resume_requires_ready_manifest) {
            _ = index_generation_manifest.validateReady(
                alloc,
                shadow_index_path,
                generation_id,
                cfg.name,
                types.indexConfigHash(cfg),
            ) catch {
                candidate_reopenable = false;
                if (durable_repair_id) |repair_id| self.discardInactiveIndexRepairCandidate(alloc, repair_id) catch {};
                return error.RepairCandidateResumeInvalid;
            };
        }
        if (!resume_candidate) {
            if (durable_repair_id) |repair_id| {
                const candidate_relative_path = try std.fmt.allocPrint(
                    alloc,
                    "{s}/indexes/{s}",
                    .{ std.fs.path.basename(shadow_base), cfg.name },
                );
                defer alloc.free(candidate_relative_path);
                try index_repair_state.validateCandidateRelativePath(cfg.name, candidate_relative_path);
                try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .building,
                    .candidate_relative_path = candidate_relative_path,
                    .replace_candidate_path = true,
                });
            }
        }

        var shadow_manager = try index_manager_mod.IndexManager.initWithOptions(
            alloc,
            shadow_base,
            self.index_backends,
        );
        shadow_manager.setAppliedSequenceCheckpointPath(shadow_checkpoint_path);
        shadow_manager.registerReplacementIndex(self.core.store, cfg) catch |err| {
            shadow_manager.deinit();
            if (resume_candidate) {
                candidate_reopenable = false;
                if (durable_repair_id) |repair_id| self.discardInactiveIndexRepairCandidate(alloc, repair_id) catch {};
                return error.RepairCandidateResumeInvalid;
            }
            return err;
        };
        var shadow_manager_open = true;
        defer if (shadow_manager_open) shadow_manager.deinit();

        // A scan cursor is useful only when there is a durable intent to own
        // it. Non-durable/internal one-shot rebuild callers retain the existing
        // complete bulk behavior even if they forward a scheduler policy by
        // mistake; otherwise they could repeatedly discard partial shadows.
        var effective_options = options;
        if (durable_repair_id == null) effective_options.yield_check = null;
        const cooperative_dense_build = cfg.kind == .dense_vector and effective_options.yield_check != null;
        var shadow_ctx = AsyncContext{
            .alloc = alloc,
            .io = self.backend_runtime.io(),
            .store = self.core.store,
            .applied_sequence_checkpoint_path = shadow_checkpoint_path,
            .index_manager = &shadow_manager,
            .apply_mutex = self.async_context.apply_mutex,
            .dense_bulk_session_scope = .external,
            .resolution_runtime = self.resolution_runtime,
            .promotion_runtime = self.promotion_runtime,
            .repair_options = effective_options,
        };
        defer shadow_ctx.deinit(alloc);

        var build_floor_sequence: u64 = if (resume_building)
            persisted_build_floor_sequence
        else if (resume_candidate)
            try apply_state.loadAppliedSequenceWithCheckpoint(
                alloc,
                self.core.store,
                shadow_checkpoint_path,
                cfg.name,
            )
        else
            0;
        var expected_snapshot_coverage: ?u64 = null;
        const completed_snapshot_build = !resume_candidate or resume_building;
        const rebuilt: u64 = if (resume_candidate and !resume_building) 0 else switch (cfg.kind) {
            .dense_vector, .sparse_vector, .graph, .full_text => rebuilt_blk: {
                try checkArtifactRepairCancelled(options);
                var pinned_snapshot: ?PinnedIndexRepairSnapshot = if (!resume_building) if (durable_repair_id) |repair_id|
                    try self.beginPinnedIndexRepairSnapshot(alloc, repair_id)
                else
                    null else null;
                defer if (pinned_snapshot) |*pinned| pinned.deinit();
                var ordinary_snapshot: ?docstore_mod.DocStore.Txn = if (pinned_snapshot == null)
                    try self.core.store.beginReadTxn()
                else
                    null;
                defer if (ordinary_snapshot) |*ordinary| ordinary.abort();
                const snapshot_txn = if (pinned_snapshot) |*pinned|
                    &pinned.txn
                else
                    &ordinary_snapshot.?;
                build_floor_sequence = if (resume_building)
                    persisted_build_floor_sequence
                else if (pinned_snapshot) |pinned|
                    pinned.build_floor_sequence
                else
                    try self.core.store.lastReplaySequenceFromTxn(snapshot_txn, 0);
                shadow_ctx.repair_sequence = build_floor_sequence;
                shadow_ctx.snapshot_read_txn = snapshot_txn;
                defer shadow_ctx.snapshot_read_txn = null;
                const count: u64 = switch (cfg.kind) {
                    .dense_vector => count_blk: {
                        var slice = try rebuildDenseIndexForTargetCoverageSliceContext(
                            &shadow_ctx,
                            cfg.name,
                            working_set_plan.dense_rebuild_batch_items,
                            build_resume_key,
                        );
                        defer slice.deinit(alloc);
                        const count: u64 = persisted_build_reprocessed +| @as(u64, @intCast(slice.rebuilt));
                        if (!slice.complete()) {
                            if (options.capacity_check) |check| {
                                try check.current(try directoryUsageBytes(alloc, shadow_base));
                            }
                            if (durable_repair_id) |repair_id| {
                                try self.updateIndexRepairIntent(alloc, repair_id, .{
                                    .phase = .building,
                                    .build_resume_key = slice.resume_key.?,
                                    .replace_build_resume_key = true,
                                    .build_reprocessed = count,
                                    .failure_streak = 0,
                                    .next_retry_at_ms = 0,
                                    .replace_last_error = true,
                                });
                            }
                            candidate_reopenable = durable_repair_id != null;
                            return .{ .reprocessed = @intCast(slice.rebuilt), .yielded = true };
                        }
                        if (cooperative_dense_build) {
                            // A count observed between slices is not a stable
                            // coverage assertion. Require the durable artifact
                            // counter here; validate its exact fenced value
                            // after final replay below. Inline vectors avoid a
                            // second corpus scan entirely.
                            const dense_entry = shadow_manager.denseIndex(cfg.name) orelse return error.IndexNotFound;
                            expected_snapshot_coverage = if (denseIndexIsArtifactBacked(dense_entry))
                                try DB.loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name)
                            else
                                null;
                        } else {
                            expected_snapshot_coverage = try denseTargetCountForIndexContext(&shadow_ctx, cfg.name);
                        }
                        break :count_blk count;
                    },
                    .sparse_vector => @intCast(try rebuildSparseIndexFromStoredEmbeddingArtifactsContext(&shadow_ctx, cfg.name, 2048)),
                    .graph => @intCast(try applySplitGraphArtifactsForIndexStreamingContext(
                        &shadow_ctx,
                        cfg.name,
                        graph_repair_rebuild_batch_size,
                    )),
                    .full_text => try shadow_manager.resetFullTextIndexForArtifactRebuildFromReadTxn(
                        self.core.store,
                        snapshot_txn,
                        cfg.name,
                        options.cancel_check,
                        options.capacity_check,
                    ),
                    else => unreachable,
                };
                break :rebuilt_blk count;
            },
            .algebraic => return error.UnsupportedOperation,
        };
        // Durable intent progress is cumulative, while the public/run result
        // reports work performed by this scheduler turn. Keeping those two
        // meanings separate prevents the final resumed slice from recounting
        // every vector processed by earlier turns.
        const reprocessed_this_pass = if (resume_building and cfg.kind == .dense_vector)
            rebuilt -| persisted_build_reprocessed
        else
            rebuilt;

        const index_ref = index_manager_mod.ManagedIndexRef{
            .name = cfg.name,
            .kind = cfg.kind,
        };
        if (cfg.kind == .dense_vector) {
            const built_entry = shadow_manager.denseIndex(cfg.name) orelse return error.IndexNotFound;
            if (completed_snapshot_build and denseIndexIsArtifactBacked(built_entry) and expected_snapshot_coverage == null) {
                return error.RepairSourceCoverageIncomplete;
            }
            if (!cooperative_dense_build) {
                if (expected_snapshot_coverage) |expected| {
                    if (!denseCoverageMatchesTarget(built_entry.index.stats().active_count, expected)) {
                        return error.RepairSourceCoverageIncomplete;
                    }
                }
            }
        }
        if (completed_snapshot_build) {
            try checkArtifactRepairCancelled(options);
            try self.saveShadowReplacementAppliedSequence(alloc, &shadow_manager, shadow_checkpoint_path, index_ref, build_floor_sequence);
            if (options.capacity_check) |check| {
                try check.current(try directoryUsageBytes(alloc, shadow_base));
            }
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .catching_up,
                .replace_build_resume_key = true,
                .build_reprocessed = rebuilt,
                .candidate_applied_sequence = build_floor_sequence,
                .failure_streak = 0,
                .next_retry_at_ms = 0,
                .replace_last_error = true,
            });
            // From this transition onward the candidate and its applied
            // checkpoint are independently reopenable. Cancellation, owner
            // loss, or restart preserves it for bounded catch-up resumption.
            candidate_reopenable = durable_repair_id != null;
            if (self.shadow_index_repair_hook) |hook| {
                try hook.after_snapshot_build(hook.ptr, self, cfg.name, build_floor_sequence);
            }
        }
        var observed_ns_per_sequence: u64 = 0;
        var catch_up_start_sequence = build_floor_sequence;
        var catch_up_start_ns = monotonicTimeNs();
        const initial_catch_up_target = self.core.nextDerivedSequence();
        const initial_catch_up = try self.catchUpShadowReplacementUntil(
            alloc,
            &shadow_manager,
            shadow_checkpoint_path,
            index_ref,
            initial_catch_up_target,
            options,
            null,
            0,
        );
        var converged_sequence = initial_catch_up.applied_sequence;
        if (options.capacity_check) |check| {
            try check.current(try directoryUsageBytes(alloc, shadow_base));
        }
        observed_ns_per_sequence = observeRepairCatchUpCost(
            observed_ns_per_sequence,
            catch_up_start_sequence,
            converged_sequence,
            elapsedSince(catch_up_start_ns),
        );
        if (initial_catch_up.yielded) {
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .catching_up,
                .candidate_applied_sequence = converged_sequence,
                .target_sequence = initial_catch_up_target,
                .failure_streak = 0,
                .next_retry_at_ms = 0,
                .replace_last_error = true,
            });
            candidate_reopenable = durable_repair_id != null;
            return .{ .reprocessed = reprocessed_this_pass, .yielded = true };
        }
        try index_generation_manifest.writeReady(
            alloc,
            shadow_index_path,
            generation_id,
            cfg.name,
            types.indexConfigHash(cfg),
            converged_sequence,
        );
        if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .ready,
            .candidate_applied_sequence = converged_sequence,
            .target_sequence = self.core.nextDerivedSequence(),
        });

        const use_dense_search_barrier = cfg.kind == .dense_vector;
        if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .waiting_for_convergence,
            .candidate_applied_sequence = converged_sequence,
            .target_sequence = self.core.nextDerivedSequence(),
        });
        const max_activation_gap_sequences = @max(@as(u64, 1), options.max_activation_gap_sequences);
        const max_convergence_rounds: usize = @max(@as(usize, 1), options.max_convergence_rounds);
        const max_activation_pause_ns = std.math.mul(
            u64,
            @max(@as(u64, 1), options.max_activation_pause_ms),
            std.time.ns_per_ms,
        ) catch std.math.maxInt(u64);
        var convergence_round: usize = 0;
        while (!repairActivationAdmissible(
            self.core.nextDerivedSequence() -| converged_sequence,
            observed_ns_per_sequence,
            max_activation_gap_sequences,
            max_activation_pause_ns,
        ) and
            convergence_round < max_convergence_rounds) : (convergence_round += 1)
        {
            const convergence_target = self.core.nextDerivedSequence();
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .catching_up,
                .candidate_applied_sequence = converged_sequence,
                .target_sequence = convergence_target,
            });
            catch_up_start_sequence = converged_sequence;
            catch_up_start_ns = monotonicTimeNs();
            const convergence_catch_up = try self.catchUpShadowReplacementUntil(
                alloc,
                &shadow_manager,
                shadow_checkpoint_path,
                index_ref,
                convergence_target,
                options,
                null,
                0,
            );
            converged_sequence = convergence_catch_up.applied_sequence;
            if (options.capacity_check) |check| {
                try check.current(try directoryUsageBytes(alloc, shadow_base));
            }
            observed_ns_per_sequence = observeRepairCatchUpCost(
                observed_ns_per_sequence,
                catch_up_start_sequence,
                converged_sequence,
                elapsedSince(catch_up_start_ns),
            );
            if (convergence_catch_up.yielded) {
                if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                    .phase = .catching_up,
                    .candidate_applied_sequence = converged_sequence,
                    .target_sequence = convergence_target,
                    .failure_streak = 0,
                    .next_retry_at_ms = 0,
                    .replace_last_error = true,
                });
                candidate_reopenable = durable_repair_id != null;
                return .{ .reprocessed = reprocessed_this_pass, .yielded = true };
            }
            try index_generation_manifest.writeReady(
                alloc,
                shadow_index_path,
                generation_id,
                cfg.name,
                types.indexConfigHash(cfg),
                converged_sequence,
            );
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .ready,
                .candidate_applied_sequence = converged_sequence,
                .target_sequence = convergence_target,
            });
            if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .waiting_for_convergence,
                .candidate_applied_sequence = converged_sequence,
                .target_sequence = self.core.nextDerivedSequence(),
            });
        }
        if (!repairActivationAdmissible(
            self.core.nextDerivedSequence() -| converged_sequence,
            observed_ns_per_sequence,
            max_activation_gap_sequences,
            max_activation_pause_ns,
        )) {
            return error.ShadowIndexCatchUpIncomplete;
        }
        const ready_sequence = try index_generation_manifest.validateReady(
            alloc,
            shadow_index_path,
            generation_id,
            cfg.name,
            types.indexConfigHash(cfg),
        );
        if (ready_sequence != converged_sequence) return error.IndexGenerationManifestMismatch;
        try checkArtifactRepairActivationOwner(options);
        const activation_started_ns = monotonicTimeNs();
        const activation_deadline_ns = activation_started_ns +| max_activation_pause_ns;
        var unpublished_replacement: ?index_manager_mod.IndexManager.DetachedIndex = null;
        defer if (unpublished_replacement) |*replacement| {
            shadow_manager.destroyDetachedReplacementIndex(replacement);
        };
        var retired_generation: ?index_manager_mod.IndexManager.DetachedIndex = null;
        defer if (retired_generation) |*retired| {
            self.core.index_manager.destroyDetachedReplacementIndex(retired);
        };
        var activation_metric_recorded = false;
        defer if (!activation_metric_recorded) {
            if (self.core.index_manager.resource_manager) |manager| {
                manager.recordIndexRepairActivation(monotonicTimeNs() -| activation_started_ns, max_activation_pause_ns);
            }
        };
        var repair_barrier_held = false;
        if (use_dense_search_barrier) {
            if (!self.beginIndexRepairBarrierUntil(activation_deadline_ns)) {
                return error.ShadowIndexCatchUpIncomplete;
            }
            repair_barrier_held = true;
        }
        defer if (repair_barrier_held) self.endIndexRepairBarrier();

        try checkArtifactRepairCancelled(options);
        if (!self.lockApplyUntil(activation_deadline_ns)) return error.ShadowIndexCatchUpIncomplete;
        var apply_lock_held = true;
        defer if (apply_lock_held) self.core.unlockApply();

        const final_target = self.core.nextDerivedSequence();
        if (!repairActivationAdmissible(
            final_target -| converged_sequence,
            observed_ns_per_sequence,
            max_activation_gap_sequences,
            max_activation_pause_ns,
        )) {
            return error.ShadowIndexCatchUpIncomplete;
        }
        const activation_replay_deadline_ns = repairActivationReplayDeadline(
            monotonicTimeNs(),
            activation_deadline_ns,
            max_activation_pause_ns,
        ) orelse return error.ShadowIndexCatchUpIncomplete;
        const activation_catch_up = self.catchUpShadowReplacementUntil(
            alloc,
            &shadow_manager,
            shadow_checkpoint_path,
            index_ref,
            final_target,
            options,
            activation_replay_deadline_ns,
            observed_ns_per_sequence,
        ) catch |err| switch (err) {
            error.CatchUpDeadlineExceeded => return error.ShadowIndexCatchUpIncomplete,
            else => return err,
        };
        std.debug.assert(!activation_catch_up.yielded);
        const reached_target = activation_catch_up.applied_sequence;
        if (reached_target < final_target) return error.ShadowIndexCatchUpIncomplete;
        // The artifact counter is maintained in the same fenced primary write
        // stream and is O(1) to read. Checking it only after final replay makes
        // sliced builds robust to inserts/deletes on either side of the scan
        // cursor while still failing closed on missing source artifacts. Inline
        // vector scans need no corpus-wide validation in the activation pause.
        if (cfg.kind == .dense_vector) {
            const dense_entry = shadow_manager.denseIndex(cfg.name) orelse return error.IndexNotFound;
            if (denseIndexIsArtifactBacked(dense_entry)) {
                const expected = (try DB.loadDenseArtifactTargetCounter(alloc, self.core.store, cfg.name)) orelse
                    return error.RepairSourceCoverageIncomplete;
                if (!denseCoverageMatchesTarget(dense_entry.index.stats().active_count, expected)) {
                    return error.RepairSourceCoverageIncomplete;
                }
            }
        }
        try checkArtifactRepairCancelled(options);
        try checkArtifactRepairActivationOwner(options);
        try ensureRepairActivationDeadline(activation_deadline_ns);
        if (durable_repair_id) |repair_id| try self.validateIndexRepairActivationState(alloc, repair_id, options.owner_epoch);
        try ensureRepairActivationDeadline(activation_deadline_ns);
        const previous_active_pointer = try self.core.index_manager.captureActiveIndexRootPointer(cfg.name);
        defer if (previous_active_pointer) |value| alloc.free(value);
        try ensureRepairActivationDeadline(activation_deadline_ns);
        if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .activating,
            .candidate_applied_sequence = reached_target,
            .target_sequence = final_target,
            .previous_pointer_captured = true,
            .previous_active_relative_path = previous_active_pointer,
            .replace_previous_active_path = true,
        });
        try ensureRepairActivationDeadline(activation_deadline_ns);

        // Final replay may advance beyond the preliminary ready marker. Make
        // readiness describe the exact durable generation installed by the
        // pointer swap, not merely the pre-barrier candidate.
        try index_generation_manifest.writeReady(
            alloc,
            shadow_index_path,
            generation_id,
            cfg.name,
            types.indexConfigHash(cfg),
            reached_target,
        );
        try ensureRepairActivationDeadline(activation_deadline_ns);
        const manifest_sequence = try index_generation_manifest.validateReady(
            alloc,
            shadow_index_path,
            generation_id,
            cfg.name,
            types.indexConfigHash(cfg),
        );
        if (manifest_sequence != reached_target) return error.IndexGenerationManifestMismatch;
        try ensureRepairActivationDeadline(activation_deadline_ns);

        // Transfer the already-open runtime for every index family. Pointer
        // publication and in-memory handoff are allocation-free, and the
        // predecessor is retired only after service fences are released.
        unpublished_replacement = try shadow_manager.detachReplacementIndex(cfg.name);
        retired_generation = try self.core.index_manager.installAdoptedReplacementIndex(
            self.core.store,
            cfg,
            shadow_index_path,
            previous_active_pointer,
            &unpublished_replacement.?,
        );
        unpublished_replacement = null;
        shadow_installed = true;
        if (self.shadow_index_repair_hook) |hook| {
            if (hook.after_pointer_activation) |after_activation| try after_activation(hook.ptr, self, cfg.name);
        }
        if (durable_repair_id) |repair_id| try self.updateIndexRepairIntent(alloc, repair_id, .{
            .phase = .validating,
            .candidate_applied_sequence = final_target,
            .target_sequence = final_target,
        });
        index_manager_mod.IndexManager.clearRepairShadowInProgressMarker(alloc, shadow_base) catch |err| {
            std.log.warn("failed to clear repair shadow in-progress marker index={s} err={s}", .{ cfg.name, @errorName(err) });
        };
        const prior_checkpoint = try self.core.loadProjectionCheckpoint(alloc, cfg.name);
        const final_update = apply_state.AppliedSequenceUpdate{
            .index_name = cfg.name,
            .sequence = final_target,
            .status = .clean,
            .generation = prior_checkpoint.generation +| 1,
            .config_hash = types.indexConfigHash(cfg),
        };
        try saveIndexStatusSnapshots(alloc, self.core.store, self.core.index_manager, &[_]apply_state.AppliedSequenceUpdate{final_update});
        try self.core.saveAppliedSequence(cfg.name, final_target);
        try self.core.saveProjectionCheckpoint(cfg.name, .{
            .applied_sequence = final_update.sequence,
            .status = final_update.status,
            .generation = final_update.generation,
            .config_hash = final_update.config_hash,
        });

        // The pointer and clean checkpoint are now ordered before any later
        // foreground apply. Release write and dense-search fencing before
        // operator hooks, intent cleanup, and generation garbage collection.
        // Capture the actual service pause before releasing either fence.
        // Generation teardown and other post-commit work are measured
        // separately and cannot produce false pause-budget alarms.
        const activation_pause_ns = monotonicTimeNs() -| activation_started_ns;
        self.core.unlockApply();
        apply_lock_held = false;
        if (repair_barrier_held) {
            self.endIndexRepairBarrier();
            repair_barrier_held = false;
        }
        if (retired_generation) |*retired| {
            self.core.index_manager.destroyDetachedReplacementIndex(retired);
            retired_generation = null;
        }
        if (shadow_manager_open) {
            shadow_manager.deinit();
            shadow_manager_open = false;
        }
        if (self.core.index_manager.resource_manager) |manager| {
            manager.recordIndexRepairActivation(activation_pause_ns, max_activation_pause_ns);
        }
        activation_metric_recorded = true;
        if (activation_pause_ns > max_activation_pause_ns) {
            std.log.warn(
                "index repair activation exceeded pause budget index={s} elapsed_ms={} budget_ms={}",
                .{
                    cfg.name,
                    @divTrunc(activation_pause_ns, std.time.ns_per_ms),
                    @divTrunc(max_activation_pause_ns, std.time.ns_per_ms),
                },
            );
        }
        if (self.shadow_index_repair_hook) |hook| {
            if (hook.after_clean_checkpoint) |after_checkpoint| try after_checkpoint(hook.ptr, self, cfg.name);
        }
        if (durable_repair_id) |repair_id| {
            try self.updateIndexRepairIntent(alloc, repair_id, .{
                .phase = .cleanup,
                .candidate_applied_sequence = final_target,
                .target_sequence = final_target,
            });
            // The clean checkpoint and replacement are durable before this
            // single local transition releases replay retention and removes
            // the intent.
            try self.removeIndexRepairIntentAndPin(alloc, repair_id);
            self.scheduleInactiveRepairShadowCleanup();
        }

        return .{
            .reprocessed = reprocessed_this_pass,
            .applied_sequence = final_target,
        };
    }

    const ShadowCatchUpResult = struct {
        applied_sequence: u64,
        yielded: bool = false,
    };

    fn catchUpShadowReplacementUntil(
        self: *DB,
        alloc: Allocator,
        shadow_manager: *index_manager_mod.IndexManager,
        shadow_checkpoint_path: []const u8,
        index_ref: index_manager_mod.ManagedIndexRef,
        target_sequence: u64,
        options: types.ArtifactRepairRunOptions,
        deadline_ns: ?u64,
        observed_ns_per_sequence: u64,
    ) !ShadowCatchUpResult {
        if (target_sequence == 0) return .{ .applied_sequence = 0 };
        // Cooperative yielding is only valid before activation fencing. Final
        // replay has its own hard deadline and must either reach that target or
        // abort activation while the write/search barriers remain held.
        const cooperative = deadline_ns == null and options.yield_check != null;
        var batch_ctx = self.batchContext();
        batch_ctx.index_manager = shadow_manager;
        batch_ctx.applied_sequence_checkpoint_path = shadow_checkpoint_path;
        batch_ctx.async_context = null;
        batch_ctx.dense_bulk_session_scope = .external;

        var applied = try apply_state.loadAppliedSequenceWithCheckpoint(
            alloc,
            self.core.store,
            shadow_checkpoint_path,
            index_ref.name,
        );
        while (applied < target_sequence) {
            try checkArtifactRepairCancelled(options);
            if (deadline_ns) |deadline| {
                if (monotonicTimeNs() >= deadline) return error.ShadowIndexCatchUpIncomplete;
            }
            var replay_ctx = ReplayApplyContextBatch{
                .batch = &batch_ctx,
                .dense_bulk_session_scope = .external,
            };
            const remaining_sequences = target_sequence -| applied;
            var max_records_per_window = if (comptime builtin.is_test)
                test_index_repair_catch_up_max_records_per_window orelse derived_worker.catch_up_max_records_per_window_default
            else
                derived_worker.catch_up_max_records_per_window_default;
            var max_items_per_window: usize = 0;
            if (deadline_ns) |deadline| {
                const now = monotonicTimeNs();
                if (now >= deadline) return error.CatchUpDeadlineExceeded;
                const per_sequence_ns = @max(@as(u64, 1), observed_ns_per_sequence);
                const affordable_sequences = (deadline - now) / per_sequence_ns;
                if (affordable_sequences == 0) return error.CatchUpDeadlineExceeded;
                const bounded_sequences = @min(remaining_sequences, affordable_sequences);
                max_records_per_window = @max(@as(usize, 1), @min(
                    derived_worker.catch_up_max_records_per_window_default,
                    std.math.cast(usize, bounded_sequences) orelse std.math.maxInt(usize),
                ));
                max_items_per_window = max_records_per_window;
            }
            const catch_up_stats = try derived_worker.catchUpIndexWithOptions(
                alloc,
                self.core.replaySource(),
                index_ref,
                applied,
                &replay_ctx,
                applyDerivedBatchToIndexReplayContext,
                .{
                    .resource_manager = shadow_manager.resource_manager,
                    .window_ctx = &replay_ctx,
                    .begin_window_fn = beginDerivedCatchUpWindowContext,
                    .finish_window_fn = finishDerivedCatchUpWindowContext,
                    .target_sequence = target_sequence,
                    .max_records_per_window = max_records_per_window,
                    .max_items_per_window = max_items_per_window,
                    // One independently durable window lets the owner inspect
                    // its cooperative deadline without adding a clock read to
                    // every replay record or changing the ordinary catch-up
                    // path. The outer loop immediately reopens from the saved
                    // applied sequence while budget remains.
                    .max_windows_per_call = if (cooperative) 1 else 0,
                    .deadline_ns = deadline_ns,
                },
            );
            const advanced = catch_up_stats.appliedSequenceAdvance(applied) orelse blk: {
                if (catch_up_stats.shouldTryTargetAdvance(applied, target_sequence) and
                    try canAdvanceDerivedReplayTargetContext(&batch_ctx, index_ref, applied, target_sequence))
                {
                    break :blk target_sequence;
                }
                break :blk applied;
            };
            if (advanced <= applied) return .{ .applied_sequence = applied };
            try self.saveShadowReplacementAppliedSequence(alloc, shadow_manager, shadow_checkpoint_path, index_ref, advanced);
            applied = advanced;
            if (cooperative and applied < target_sequence and options.yield_check.?.requested()) {
                return .{ .applied_sequence = applied, .yielded = true };
            }
            if (deadline_ns) |deadline| {
                if (applied < target_sequence and monotonicTimeNs() >= deadline) {
                    return error.ShadowIndexCatchUpIncomplete;
                }
            }
        }
        try checkArtifactRepairCancelled(options);
        return .{ .applied_sequence = applied };
    }

    fn observeRepairCatchUpCost(previous_ns_per_sequence: u64, from_sequence: u64, to_sequence: u64, elapsed_ns: u64) u64 {
        const advanced = to_sequence -| from_sequence;
        if (advanced == 0) return previous_ns_per_sequence;
        const observed = @max(@as(u64, 1), (elapsed_ns +| advanced -| 1) / advanced);
        // Retain the slower observed rate. Activation admission should be
        // conservative when foreground pressure makes recent replay slower.
        return @max(previous_ns_per_sequence, observed);
    }

    fn repairActivationReplayDeadline(now_ns: u64, activation_deadline_ns: u64, pause_budget_ns: u64) ?u64 {
        if (now_ns >= activation_deadline_ns) return null;
        // Reserve a bounded tail for manifest validation, pointer publication,
        // and clean-checkpoint durability.  Five milliseconds is sufficient
        // for small budgets; large budgets reserve at most fifty milliseconds
        // so replay still receives the majority of the fence interval.
        const reserve_ns = @max(
            5 * std.time.ns_per_ms,
            @min(50 * std.time.ns_per_ms, pause_budget_ns / 5),
        );
        if (activation_deadline_ns - now_ns <= reserve_ns) return null;
        return activation_deadline_ns - reserve_ns;
    }

    fn repairActivationAdmissible(
        gap_sequences: u64,
        observed_ns_per_sequence: u64,
        max_gap_sequences: u64,
        max_pause_ns: u64,
    ) bool {
        if (gap_sequences == 0) return true;
        if (gap_sequences > max_gap_sequences or observed_ns_per_sequence == 0) return false;
        const estimated_pause_ns = std.math.mul(u64, gap_sequences, observed_ns_per_sequence) catch std.math.maxInt(u64);
        return estimated_pause_ns <= max_pause_ns;
    }

    fn saveShadowReplacementAppliedSequence(
        self: *DB,
        alloc: Allocator,
        shadow_manager: *index_manager_mod.IndexManager,
        shadow_checkpoint_path: []const u8,
        index_ref: index_manager_mod.ManagedIndexRef,
        sequence: u64,
    ) !void {
        try shadow_manager.checkpointLsmWalForManagedIndex(index_ref);
        const update = apply_state.AppliedSequenceUpdate{
            .index_name = index_ref.name,
            .sequence = sequence,
            .config_hash = if (shadow_manager.get(index_ref.name)) |value| types.indexConfigHash(value.*) else 0,
        };
        const updates = [_]apply_state.AppliedSequenceUpdate{update};
        try saveDenseProjectionMetadataForAppliedSequenceUpdates(shadow_manager, &updates);
        try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(shadow_manager, &updates);
        try apply_state.saveAppliedSequenceUpdateWithCheckpoint(
            alloc,
            self.core.store,
            shadow_checkpoint_path,
            update,
        );
    }

    fn indexRepairRequired(self: *DB, alloc: Allocator, index_name: []const u8) !bool {
        if (self.core.index_manager.loadFailure(index_name) != null) return true;
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, index_name);
        switch (checkpoint.status) {
            .degraded, .repair_required => return true,
            .clean, .rebuilding => {},
        }
        if (try self.denseCoverageRegressionRepairRequired(alloc, index_name)) return true;
        return try self.artifactRepairSummaryIndexCount(alloc, index_name) != 0;
    }

    fn denseCoverageRegressionRepairRequired(self: *DB, alloc: Allocator, index_name: []const u8) !bool {
        const entry = self.core.index_manager.denseIndex(index_name) orelse return false;
        if (!denseIndexIsArtifactBacked(entry)) return false;
        const expected = (try loadDenseArtifactTargetCounter(alloc, self.core.store, index_name)) orelse
            return true;
        if (denseCoverageMatchesTarget(entry.index.stats().active_count, expected)) return false;

        // Source counters advance atomically with primary writes, before the
        // asynchronous projection applies the corresponding replay sequence.
        // A cardinality difference is repair debt only after replay converges;
        // otherwise every healthy asynchronous write would be misclassified.
        const checkpoint = try self.core.loadProjectionCheckpoint(alloc, index_name);
        if (checkpoint.status == .rebuilding) return false;
        const target_sequence = try self.probeDerivedReplayTargetSequence(
            alloc,
            self.core.replaySource(),
            .{ .name = index_name, .kind = .dense_vector },
            checkpoint.applied_sequence,
        );
        return checkpoint.applied_sequence >= target_sequence;
    }

    pub fn repairArtifactIssues(
        self: *DB,
        alloc: Allocator,
