fn concatArtifactKeyViews(alloc: Allocator, lhs: []const []const u8, rhs: []const []u8) ![][]const u8 {
    const out = try alloc.alloc([]const u8, lhs.len + rhs.len);
    @memcpy(out[0..lhs.len], lhs);
    for (rhs, 0..) |key, i| out[lhs.len + i] = key;
    return out;
}

fn concatKeyViews(alloc: Allocator, lhs: []const []const u8, rhs: []const []const u8) ![]const []const u8 {
    const out = try alloc.alloc([]const u8, lhs.len + rhs.len);
    @memcpy(out[0..lhs.len], lhs);
    @memcpy(out[lhs.len..], rhs);
    return out;
}

fn concatKVPairSlices(alloc: Allocator, lhs: []const docstore_mod.KVPair, rhs: []const docstore_mod.KVPair) ![]docstore_mod.KVPair {
    const out = try alloc.alloc(docstore_mod.KVPair, lhs.len + rhs.len);
    @memcpy(out[0..lhs.len], lhs);
    for (rhs, 0..) |write, i| out[lhs.len + i] = write;
    return out;
}

const GraphMaterializationOptions = struct {
    require_resolution_contract: bool = false,
    repair_ctx: ?*const AsyncContext = null,
    sequence: u64 = 0,
};

fn materializeGraphSourceArtifactsForIndex(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_manager: *index_manager_mod.IndexManager,
    changed_artifact_keys: []const []const u8,
    index_name: []const u8,
    options: GraphMaterializationOptions,
) ![][]u8 {
    const source = index_manager.graphArtifactSource(index_name) orelse return try alloc.alloc([]u8, 0);

    var changed = std.ArrayListUnmanaged([]u8).empty;
    errdefer freeOwnedKeySlice(alloc, changed.items);

    for (changed_artifact_keys) |artifact_key| {
        if (internal_keys.isResolutionArtifactKey(artifact_key)) {
            try materializeMentionEdgesForResolutionKey(alloc, store, index_manager, &changed, index_name, source, artifact_key, options);
            continue;
        }
        var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, artifact_key)) orelse continue;
        defer artifact_ref.deinit(alloc);
        if (!graphArtifactSourceConsumesRef(index_manager, source, artifact_ref)) continue;

        var deletes = std.ArrayListUnmanaged([]const u8).empty;
        defer {
            for (deletes.items) |key| alloc.free(@constCast(key));
            deletes.deinit(alloc);
        }

        const raw = store.get(alloc, artifact_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        defer if (raw) |value| alloc.free(value);

        var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
        defer {
            for (writes.items) |write| {
                alloc.free(@constCast(write.key));
                alloc.free(@constCast(write.value));
            }
            writes.deinit(alloc);
        }

        if (raw) |value| {
            const raw_doc = try storeDocumentValueForGraphSource(alloc, store, artifact_ref.document_id);
            defer if (raw_doc) |doc_value| alloc.free(doc_value);
            const graph_writes = graphWritesFromArtifactValueAlloc(alloc, index_name, artifact_ref.document_id, value, source, graphArtifactContentType(index_manager, source.artifact_name), raw_doc) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => {
                    if (options.repair_ctx) |repair_ctx| {
                        try recordArtifactRepairIssueForRefContext(repair_ctx, index_name, artifact_ref, artifact_key, options.sequence, .corrupt_artifact);
                        return error.ArtifactRepairRequired;
                    }
                    return err;
                },
            };
            defer freeGraphWrites(alloc, graph_writes);
            for (graph_writes) |write| {
                const key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, write.source, write.index_name, write.edge_type, write.target);
                var key_owned = true;
                errdefer if (key_owned) alloc.free(key);
                const payload = try enrichment_artifact_codec.encodeGraphEdgeAlloc(alloc, null, write.weight, write.created_at, write.updated_at, write.metadata_json);
                var payload_owned = true;
                errdefer if (payload_owned) alloc.free(payload);
                try writes.append(alloc, .{ .key = key, .value = payload });
                key_owned = false;
                payload_owned = false;
                try appendUniqueOwnedKey(alloc, &changed, key);
            }
        }

        const state_name = try graphArtifactStateNameAlloc(alloc, artifact_ref);
        defer alloc.free(state_name);
        const state_key = try graphAssetStateKeyAlloc(alloc, artifact_ref.document_id, index_name, state_name);
        defer alloc.free(state_key);
        if (try loadGraphAssetStateKeysAlloc(alloc, store, state_key)) |previous_keys| {
            defer freeOwnedConstKeySlice(alloc, previous_keys);
            for (previous_keys) |previous_key| {
                if (containsStoreWriteKey(writes.items, previous_key)) continue;
                try deletes.append(alloc, try alloc.dupe(u8, previous_key));
                try appendUniqueOwnedKey(alloc, &changed, previous_key);
            }
        } else if (graphArtifactRefUsesDocumentWideFallback(artifact_ref)) {
            const protected_keys = try resolutionMentionStateKeysForGraphSourceAlloc(alloc, store, index_manager, artifact_ref.document_id, index_name, source);
            defer freeOwnedConstKeySlice(alloc, protected_keys);
            const existing = try collectGraphArtifactsForDocIndex(alloc, store, artifact_ref.document_id, index_name);
            defer docstore_mod.DocStore.freeResults(alloc, existing);
            for (existing) |entry| {
                if (containsStoreWriteKey(writes.items, entry.key)) continue;
                if (containsDeleteKey(protected_keys, entry.key)) continue;
                try deletes.append(alloc, try alloc.dupe(u8, entry.key));
                try appendUniqueOwnedKey(alloc, &changed, entry.key);
            }
        }

        const state_value = try encodeGraphAssetStateKeysAlloc(alloc, writes.items);
        var state_value_owned = true;
        defer if (state_value_owned) alloc.free(state_value);
        try writes.append(alloc, .{
            .key = try alloc.dupe(u8, state_key),
            .value = state_value,
        });
        state_value_owned = false;

        if (writes.items.len > 0 or deletes.items.len > 0) {
            var changed_batch = try filterChangedGraphMaterializationBatch(alloc, store, writes.items, deletes.items);
            defer changed_batch.deinit(alloc);
            if (changed_batch.writes.len > 0 or changed_batch.deletes.len > 0) {
                try store.putBatch(changed_batch.writes, changed_batch.deletes);
            }
        }
    }

    return try changed.toOwnedSlice(alloc);
}

fn materializeMentionEdgesForResolutionKey(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_manager: *index_manager_mod.IndexManager,
    changed: *std.ArrayListUnmanaged([]u8),
    index_name: []const u8,
    source: index_manager_mod.GraphArtifactSource,
    resolution_key: []const u8,
    options: GraphMaterializationOptions,
) !void {
    if (source.mention_edge_type.len == 0) return;
    const parsed_key = (try internal_keys.parseResolutionArtifactKeyAlloc(alloc, resolution_key)) orelse return;
    defer alloc.free(parsed_key.doc_key);
    defer alloc.free(parsed_key.artifact_name);

    const raw_resolution = store.get(alloc, resolution_key) catch |err| switch (err) {
        error.NotFound => null,
        else => return err,
    };
    defer if (raw_resolution) |raw| alloc.free(raw);

    const cfg = resolverConfigForResolution(index_manager, source.artifact_name, parsed_key.artifact_name) orelse {
        if (options.require_resolution_contract) return error.MissingResolverArtifactContract;
        return;
    };
    const state_name = try mentionGraphStateNameAlloc(alloc, source.artifact_name, cfg.resolution_artifact);
    defer alloc.free(state_name);
    const state_key = try graphAssetStateKeyAlloc(alloc, parsed_key.doc_key, index_name, state_name);
    defer alloc.free(state_key);

    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer {
        for (writes.items) |write| {
            alloc.free(@constCast(write.key));
            alloc.free(@constCast(write.value));
        }
        writes.deinit(alloc);
    }
    var mention_writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer {
        for (mention_writes.items) |write| {
            alloc.free(@constCast(write.key));
            alloc.free(@constCast(write.value));
        }
        mention_writes.deinit(alloc);
    }
    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer {
        for (deletes.items) |key| alloc.free(@constCast(key));
        deletes.deinit(alloc);
    }

    if (raw_resolution) |raw| {
        const raw_extraction = loadSourceExtractionForResolution(alloc, store, parsed_key.doc_key, cfg.source_artifact) catch null;
        defer if (raw_extraction) |raw_src| alloc.free(raw_src);
        const mention_edge_writes = try mentionEdgeWritesFromResolutionAlloc(
            alloc,
            index_name,
            parsed_key.doc_key,
            raw,
            raw_extraction,
            source.mention_edge_type,
            cfg,
        );
        defer freeGraphWrites(alloc, mention_edge_writes);
        for (mention_edge_writes) |write| {
            const key = try internal_keys.graphEdgeArtifactKeyAlloc(alloc, write.source, write.index_name, write.edge_type, write.target);
            var key_owned = true;
            errdefer if (key_owned) alloc.free(key);
            const payload = try enrichment_artifact_codec.encodeGraphEdgeAlloc(alloc, null, write.weight, write.created_at, write.updated_at, write.metadata_json);
            var payload_owned = true;
            errdefer if (payload_owned) alloc.free(payload);
            try writes.append(alloc, .{ .key = key, .value = payload });
            key_owned = false;
            payload_owned = false;
            try appendUniqueOwnedKey(alloc, changed, key);
        }
        try appendMentionEvidenceArtifactsFromResolution(
            alloc,
            &mention_writes,
            changed,
            parsed_key.doc_key,
            resolution_key,
            raw,
            raw_extraction,
            cfg,
        );
    }

    if (try loadGraphAssetStateKeysAlloc(alloc, store, state_key)) |previous_keys| {
        defer freeOwnedConstKeySlice(alloc, previous_keys);
        for (previous_keys) |previous_key| {
            if (containsStoreWriteKey(writes.items, previous_key)) continue;
            try deletes.append(alloc, try alloc.dupe(u8, previous_key));
            try appendUniqueOwnedKey(alloc, changed, previous_key);
        }
    }

    const state_value = try encodeGraphAssetStateKeysAlloc(alloc, writes.items);
    var state_value_owned = true;
    defer if (state_value_owned) alloc.free(state_value);
    try writes.append(alloc, .{
        .key = try alloc.dupe(u8, state_key),
        .value = state_value,
    });
    state_value_owned = false;

    const mention_state_name = try mentionArtifactStateNameAlloc(alloc, source.artifact_name, cfg.resolution_artifact);
    defer alloc.free(mention_state_name);
    const mention_state_key = try graphAssetStateKeyAlloc(alloc, parsed_key.doc_key, index_name, mention_state_name);
    defer alloc.free(mention_state_key);
    if (try loadGraphAssetStateKeysAlloc(alloc, store, mention_state_key)) |previous_keys| {
        defer freeOwnedConstKeySlice(alloc, previous_keys);
        for (previous_keys) |previous_key| {
            if (containsStoreWriteKey(mention_writes.items, previous_key)) continue;
            try deletes.append(alloc, try alloc.dupe(u8, previous_key));
            try appendUniqueOwnedKey(alloc, changed, previous_key);
        }
    }

    const mention_state_value = try encodeGraphAssetStateKeysAlloc(alloc, mention_writes.items);
    var mention_state_value_owned = true;
    defer if (mention_state_value_owned) alloc.free(mention_state_value);
    try mention_writes.append(alloc, .{
        .key = try alloc.dupe(u8, mention_state_key),
        .value = mention_state_value,
    });
    mention_state_value_owned = false;

    if (writes.items.len > 0 or mention_writes.items.len > 0 or deletes.items.len > 0) {
        const combined = try concatKVPairSlices(alloc, writes.items, mention_writes.items);
        defer alloc.free(combined);
        var changed_batch = try filterChangedGraphMaterializationBatch(alloc, store, combined, deletes.items);
        defer changed_batch.deinit(alloc);
        if (changed_batch.writes.len > 0 or changed_batch.deletes.len > 0) {
            try store.putBatch(changed_batch.writes, changed_batch.deletes);
        }
    }
}

fn freeGraphWrites(alloc: Allocator, writes: []types.GraphEdgeWrite) void {
    for (writes) |write| {
        alloc.free(@constCast(write.index_name));
        alloc.free(@constCast(write.source));
        alloc.free(@constCast(write.target));
        alloc.free(@constCast(write.edge_type));
        if (write.metadata_json.len > 0) alloc.free(@constCast(write.metadata_json));
    }
    if (writes.len > 0) alloc.free(writes);
}

fn resolverConfigForResolution(
    index_manager: *index_manager_mod.IndexManager,
    source_artifact: []const u8,
    resolution_artifact: []const u8,
) ?*const index_manager_mod.ResolverConfig {
    for (index_manager.resolvers.items) |*cfg| {
        if (std.mem.eql(u8, cfg.source_artifact, source_artifact) and
            std.mem.eql(u8, cfg.resolution_artifact, resolution_artifact))
        {
            return cfg;
        }
    }
    return null;
}

fn resolverConfigForResolutionArtifact(
    index_manager: *index_manager_mod.IndexManager,
    resolution_artifact: []const u8,
) ?*const index_manager_mod.ResolverConfig {
    for (index_manager.resolvers.items) |*cfg| {
        if (std.mem.eql(u8, cfg.resolution_artifact, resolution_artifact)) return cfg;
    }
    return null;
}

fn mentionGraphStateNameAlloc(alloc: Allocator, source_artifact: []const u8, resolution_artifact: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{s}\x1fresolution_mentions\x1f{s}", .{ source_artifact, resolution_artifact });
}

fn mentionArtifactStateNameAlloc(alloc: Allocator, source_artifact: []const u8, resolution_artifact: []const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{s}\x1fresolution_mention_artifacts\x1f{s}", .{ source_artifact, resolution_artifact });
}

fn resolutionMentionArtifactNameAlloc(
    alloc: Allocator,
    source_artifact: []const u8,
    resolution_artifact: []const u8,
    local_id: []const u8,
) ![]u8 {
    return try std.fmt.allocPrint(alloc, "_resolution_mention\x1f{s}\x1f{s}\x1f{s}", .{ source_artifact, resolution_artifact, local_id });
}

fn resolutionMentionArtifactKeyAlloc(
    alloc: Allocator,
    doc_key: []const u8,
    source_artifact: []const u8,
    resolution_artifact: []const u8,
    local_id: []const u8,
) ![]u8 {
    const name = try resolutionMentionArtifactNameAlloc(alloc, source_artifact, resolution_artifact, local_id);
    defer alloc.free(name);
    return try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", name);
}

fn resolutionMentionStateKeysForGraphSourceAlloc(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    index_manager: *index_manager_mod.IndexManager,
    doc_key: []const u8,
    index_name: []const u8,
    source: index_manager_mod.GraphArtifactSource,
) ![][]const u8 {
    if (source.mention_edge_type.len == 0) return try alloc.alloc([]const u8, 0);

    var protected = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (protected.items) |key| alloc.free(@constCast(key));
        protected.deinit(alloc);
    }

    for (index_manager.resolvers.items) |cfg| {
        if (!std.mem.eql(u8, cfg.source_artifact, source.artifact_name)) continue;

        const state_name = try mentionGraphStateNameAlloc(alloc, source.artifact_name, cfg.resolution_artifact);
        defer alloc.free(state_name);
        const state_key = try graphAssetStateKeyAlloc(alloc, doc_key, index_name, state_name);
        defer alloc.free(state_key);

        const state_keys = try loadGraphAssetStateKeysAlloc(alloc, store, state_key) orelse continue;
        defer freeOwnedConstKeySlice(alloc, state_keys);
        for (state_keys) |key| {
            try protected.append(alloc, try alloc.dupe(u8, key));
        }
    }

    return try protected.toOwnedSlice(alloc);
}

fn loadSourceExtractionForResolution(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    doc_key: []const u8,
    source_artifact: []const u8,
) !?[]u8 {
    if (try sourceArtifactKeyFromResolutionScopeAlloc(alloc, doc_key, source_artifact)) |source_key| {
        defer alloc.free(source_key);
        return store.get(alloc, source_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
    }
    const extraction_key = try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", source_artifact);
    defer alloc.free(extraction_key);
    return store.get(alloc, extraction_key) catch |err| switch (err) {
        error.NotFound => null,
        else => return err,
    };
}

fn sourceArtifactKeyFromResolutionScopeAlloc(alloc: Allocator, doc_key: []const u8, source_artifact: []const u8) !?[]u8 {
    var artifact_ref = (try decodeArtifactRefIfKnownAlloc(alloc, doc_key)) orelse return null;
    defer artifact_ref.deinit(alloc);
    if (artifact_ref.kind != .asset and artifact_ref.kind != .chunk) return null;
    if (!std.mem.eql(u8, artifact_ref.name, source_artifact)) return null;
    return try alloc.dupe(u8, doc_key);
}

fn sourceArtifactKeyForResolutionAlloc(alloc: Allocator, doc_key: []const u8, source_artifact: []const u8) ![]u8 {
    if (try sourceArtifactKeyFromResolutionScopeAlloc(alloc, doc_key, source_artifact)) |source_key| return source_key;
    return try internal_keys.artifactNamedPrefixAlloc(alloc, doc_key, "asset", source_artifact);
}

fn extractionConfidenceForLocalId(entities: []const resolver_lib.ExtractedEntity, local_id: []const u8) ?f64 {
    for (entities) |entity| {
        if (std.mem.eql(u8, entity.local_id, local_id)) return entity.confidence;
    }
    return null;
}

fn extractionEntityForLocalId(entities: []const resolver_lib.ExtractedEntity, local_id: []const u8) ?resolver_lib.ExtractedEntity {
    for (entities) |entity| {
        if (std.mem.eql(u8, entity.local_id, local_id)) return entity;
    }
    return null;
}

fn resolutionDecisionCreatesCanonicalEdge(decision: resolver_lib.Decision) bool {
    return switch (decision) {
        .new, .match => true,
        .review => false,
    };
}

fn decisionName(decision: resolver_lib.Decision) []const u8 {
    return switch (decision) {
        .new => "new",
        .match => "match",
        .review => "review",
    };
}

/// Build `doc -> entity` mention edges (provenance) from the durable resolution
/// artifact for canonical decisions. The target is the resolved DocRef, so
/// prefix/ANN matches, merge redirects, and curator overrides are reflected in
/// graph state. Review-band decisions remain visible through the review queue,
/// not as ordinary resolved provenance. The optional extraction artifact is
/// consulted only for the original mention confidence used by provenance weight
/// calibration.
fn mentionEdgeWritesFromResolutionAlloc(
    alloc: Allocator,
    index_name: []const u8,
    doc_key: []const u8,
    resolution_raw: []const u8,
    extraction_raw: ?[]const u8,
    mention_edge_type: []const u8,
    cfg: *const index_manager_mod.ResolverConfig,
) ![]types.GraphEdgeWrite {
    var parsed_resolution = resolver_lib.parseResolution(alloc, resolution_raw) catch return try alloc.alloc(types.GraphEdgeWrite, 0);
    defer parsed_resolution.deinit();
    var parsed_extraction: ?resolver_lib.ParsedEntities = if (extraction_raw) |raw|
        resolver_lib.parseExtractionEntities(alloc, raw) catch null
    else
        null;
    defer if (parsed_extraction) |*parsed| parsed.deinit();

    var aggregates = std.ArrayListUnmanaged(MentionEdgeAggregate).empty;
    defer {
        for (aggregates.items) |*aggregate| aggregate.deinit(alloc);
        aggregates.deinit(alloc);
    }
    for (parsed_resolution.entities) |entity| {
        if (!resolutionDecisionCreatesCanonicalEdge(entity.decision)) continue;
        if (entity.doc_ref.key.len == 0) continue;
        const mention_confidence = if (parsed_extraction) |parsed|
            extractionConfidenceForLocalId(parsed.entities, entity.local_id) orelse entity.confidence
        else
            entity.confidence;
        const mention_artifact_key = try resolutionMentionArtifactKeyAlloc(alloc, doc_key, cfg.source_artifact, cfg.resolution_artifact, entity.local_id);
        var mention_key_owned = true;
        errdefer if (mention_key_owned) alloc.free(mention_artifact_key);
        const aggregate = try findOrAppendMentionEdgeAggregate(alloc, &aggregates, entity.doc_ref.key, entity.doc_ref.table);
        try aggregate.appendMentionArtifactKey(alloc, mention_artifact_key);
        mention_key_owned = false;
        aggregate.mention_confidence = @max(aggregate.mention_confidence, mention_confidence);
    }

    var writes = std.ArrayListUnmanaged(types.GraphEdgeWrite).empty;
    errdefer freeGraphWrites(alloc, writes.items);
    for (aggregates.items) |aggregate| {
        const metadata = try mentionEdgeMetadataJsonAlloc(alloc, aggregate);
        errdefer alloc.free(metadata);
        try writes.append(alloc, .{
            .index_name = try alloc.dupe(u8, index_name),
            .source = try alloc.dupe(u8, doc_key),
            .target = try alloc.dupe(u8, aggregate.target),
            .edge_type = try alloc.dupe(u8, mention_edge_type),
            .weight = cfg.fusedMentionWeight(aggregate.mention_confidence),
            .metadata_json = metadata,
        });
    }
    return try writes.toOwnedSlice(alloc);
}

const MentionEdgeAggregate = struct {
    target: []u8,
    target_table: []u8,
    mention_confidence: f64,
    mention_artifact_keys: std.ArrayListUnmanaged([]u8) = .empty,

    fn deinit(self: *MentionEdgeAggregate, alloc: Allocator) void {
        alloc.free(self.target);
        alloc.free(self.target_table);
        for (self.mention_artifact_keys.items) |key| alloc.free(key);
        self.mention_artifact_keys.deinit(alloc);
        self.* = undefined;
    }

    fn appendMentionArtifactKey(self: *MentionEdgeAggregate, alloc: Allocator, key: []u8) !void {
        try self.mention_artifact_keys.append(alloc, key);
    }
};

fn findOrAppendMentionEdgeAggregate(
    alloc: Allocator,
    aggregates: *std.ArrayListUnmanaged(MentionEdgeAggregate),
    target: []const u8,
    target_table: []const u8,
) !*MentionEdgeAggregate {
    for (aggregates.items) |*existing| {
        if (std.mem.eql(u8, existing.target, target)) return existing;
    }
    const target_owned = try alloc.dupe(u8, target);
    var target_owned_live = true;
    errdefer if (target_owned_live) alloc.free(target_owned);
    const table_owned = try alloc.dupe(u8, target_table);
    var table_owned_live = true;
    errdefer if (table_owned_live) alloc.free(table_owned);
    try aggregates.append(alloc, .{
        .target = target_owned,
        .target_table = table_owned,
        .mention_confidence = 0,
    });
    target_owned_live = false;
    table_owned_live = false;
    return &aggregates.items[aggregates.items.len - 1];
}

fn mentionEdgeMetadataJsonAlloc(alloc: Allocator, aggregate: MentionEdgeAggregate) ![]u8 {
    // Record the resolved DocRef target table so the endpoint can be hydrated
    // cross-table; same-table hydration ignores it. The mention artifact keys
    // are the durable evidence rollup behind the deduplicated entity edge.
    return try std.json.Stringify.valueAlloc(alloc, .{
        .target_table = aggregate.target_table,
        .mention_count = aggregate.mention_artifact_keys.items.len,
        .mention_artifact_keys = aggregate.mention_artifact_keys.items,
    }, .{});
}

fn appendMentionEvidenceArtifactsFromResolution(
    alloc: Allocator,
    writes: *std.ArrayListUnmanaged(docstore_mod.KVPair),
    changed: *std.ArrayListUnmanaged([]u8),
    doc_key: []const u8,
    resolution_key: []const u8,
    resolution_raw: []const u8,
    extraction_raw: ?[]const u8,
    cfg: *const index_manager_mod.ResolverConfig,
) !void {
    var parsed_resolution = resolver_lib.parseResolution(alloc, resolution_raw) catch return;
    defer parsed_resolution.deinit();
    var parsed_extraction: ?resolver_lib.ParsedEntities = if (extraction_raw) |raw|
        resolver_lib.parseExtractionEntities(alloc, raw) catch null
    else
        null;
    defer if (parsed_extraction) |*parsed| parsed.deinit();
    const source_artifact_key = try sourceArtifactKeyForResolutionAlloc(alloc, doc_key, cfg.source_artifact);
    defer alloc.free(source_artifact_key);

    for (parsed_resolution.entities) |entity| {
        if (!resolutionDecisionCreatesCanonicalEdge(entity.decision)) continue;
        if (entity.doc_ref.key.len == 0) continue;
        const extraction_entity = if (parsed_extraction) |parsed|
            extractionEntityForLocalId(parsed.entities, entity.local_id)
        else
            null;
        const key = try resolutionMentionArtifactKeyAlloc(alloc, doc_key, cfg.source_artifact, cfg.resolution_artifact, entity.local_id);
        var key_owned = true;
        errdefer if (key_owned) alloc.free(key);
        const payload = try mentionEvidencePayloadAlloc(alloc, doc_key, key, source_artifact_key, resolution_key, cfg, entity, extraction_entity);
        var payload_owned = true;
        errdefer if (payload_owned) alloc.free(payload);
        try writes.append(alloc, .{ .key = key, .value = payload });
        key_owned = false;
        payload_owned = false;
        try appendUniqueOwnedKey(alloc, changed, key);
    }
}

fn mentionEvidencePayloadAlloc(
    alloc: Allocator,
    doc_key: []const u8,
    mention_artifact_key: []const u8,
    source_artifact_key: []const u8,
    resolution_key: []const u8,
    cfg: *const index_manager_mod.ResolverConfig,
    entity: resolver_lib.ResolvedEntity,
    extraction_entity: ?resolver_lib.ExtractedEntity,
) ![]u8 {
    const mention_label = if (extraction_entity) |source| source.label else entity.label;
    const mention_text = if (extraction_entity) |source| source.text else entity.surface_form;
    const mention_confidence = if (extraction_entity) |source| source.confidence else entity.confidence;
    return try std.json.Stringify.valueAlloc(alloc, .{
        ._schema = "antfly.resolution_mention.v1",
        ._parent_doc_key = doc_key,
        ._artifact_kind = "resolution_mention",
        ._artifact_key = mention_artifact_key,
        .source_artifact = cfg.source_artifact,
        .source_artifact_key = source_artifact_key,
        .resolution_artifact = cfg.resolution_artifact,
        .resolution_artifact_key = resolution_key,
        .resolver = cfg.name,
        .resolver_table = cfg.table,
        .config_generation = cfg.config_generation,
        .local_id = entity.local_id,
        .decision = decisionName(entity.decision),
        .confidence = entity.confidence,
        .canonical = .{
            .table = entity.doc_ref.table,
            .key = entity.doc_ref.key,
            .name = entity.canonical_name,
            .label = entity.label,
        },
        .mention = .{
            .text = mention_text,
            .label = mention_label,
            .confidence = mention_confidence,
        },
    }, .{});
}

fn graphWritesFromArtifactValueAlloc(
    alloc: Allocator,
    index_name: []const u8,
    doc_key: []const u8,
    raw: []const u8,
    source: index_manager_mod.GraphArtifactSource,
    artifact_content_type: []const u8,
    raw_doc: ?[]const u8,
) ![]types.GraphEdgeWrite {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, raw, .{});
    defer parsed.deinit();
    var parsed_doc = if (raw_doc) |doc| try std.json.parseFromSlice(std.json.Value, alloc, doc, .{}) else null;
    defer if (parsed_doc) |*doc| doc.deinit();
    const doc_value: ?std.json.Value = if (parsed_doc) |doc| doc.value else null;

    var writes = std.ArrayListUnmanaged(types.GraphEdgeWrite).empty;
    errdefer freeGraphWrites(alloc, writes.items);

    switch (source.format) {
        .extraction_relation => try appendRelationItemsFromPath(alloc, &writes, index_name, doc_key, doc_value, parsed.value, source.path, source.mapping, source.artifact_name, artifact_content_type, parsed.value),
        .extraction_graph => {
            if (source.path.len > 0) {
                try appendRelationItemsFromPath(alloc, &writes, index_name, doc_key, doc_value, parsed.value, source.path, source.mapping, source.artifact_name, artifact_content_type, parsed.value);
            } else if (parsed.value == .object) {
                if (parsed.value.object.get("relations")) |relations| try appendRelationValueItems(alloc, &writes, index_name, doc_key, doc_value, relations, source.mapping, source.artifact_name, artifact_content_type, parsed.value);
                if (parsed.value.object.get("edges")) |edges| try appendRelationValueItems(alloc, &writes, index_name, doc_key, doc_value, edges, source.mapping, source.artifact_name, artifact_content_type, parsed.value);
            }
        },
    }

    return try writes.toOwnedSlice(alloc);
}

fn appendRelationItemsFromPath(
    alloc: Allocator,
    writes: *std.ArrayListUnmanaged(types.GraphEdgeWrite),
    index_name: []const u8,
    doc_key: []const u8,
    doc_value: ?std.json.Value,
    root: std.json.Value,
    path: []const u8,
    mapping: index_manager_mod.GraphArtifactMapping,
    artifact_name: []const u8,
    artifact_content_type: []const u8,
    artifact_value: std.json.Value,
) !void {
    if (path.len == 0 or std.mem.eql(u8, path, "$")) return appendRelationValueItems(alloc, writes, index_name, doc_key, doc_value, root, mapping, artifact_name, artifact_content_type, artifact_value);
    const selected = selectGraphArtifactPath(root, path) orelse return;
    try appendRelationValueItems(alloc, writes, index_name, doc_key, doc_value, selected, mapping, artifact_name, artifact_content_type, artifact_value);
}

fn selectGraphArtifactPath(root: std.json.Value, path: []const u8) ?std.json.Value {
    var trimmed = path;
    if (std.mem.startsWith(u8, trimmed, "$.")) trimmed = trimmed[2..];
    if (std.mem.endsWith(u8, trimmed, "[*]")) trimmed = trimmed[0 .. trimmed.len - 3];
    if (trimmed.len == 0) return root;

    var current = root;
    var parts = std.mem.splitScalar(u8, trimmed, '.');
    while (parts.next()) |part| {
        if (part.len == 0) return null;
        if (current != .object) return null;
        current = current.object.get(part) orelse return null;
    }
    return current;
}

fn appendRelationValueItems(
    alloc: Allocator,
    writes: *std.ArrayListUnmanaged(types.GraphEdgeWrite),
    index_name: []const u8,
    doc_key: []const u8,
    doc_value: ?std.json.Value,
    value: std.json.Value,
    mapping: index_manager_mod.GraphArtifactMapping,
    artifact_name: []const u8,
    artifact_content_type: []const u8,
    artifact_value: std.json.Value,
) !void {
    if (value == .array) {
        for (value.array.items, 0..) |item, i| try appendRelationItem(alloc, writes, index_name, doc_key, doc_value, item, i, mapping, artifact_name, artifact_content_type, artifact_value);
    } else {
        try appendRelationItem(alloc, writes, index_name, doc_key, doc_value, value, 0, mapping, artifact_name, artifact_content_type, artifact_value);
    }
}

fn appendRelationItem(
    alloc: Allocator,
    writes: *std.ArrayListUnmanaged(types.GraphEdgeWrite),
    index_name: []const u8,
    doc_key: []const u8,
    doc_value: ?std.json.Value,
    item: std.json.Value,
    item_index: usize,
    mapping: index_manager_mod.GraphArtifactMapping,
    artifact_name: []const u8,
    artifact_content_type: []const u8,
    artifact_value: std.json.Value,
) !void {
    if (item != .object) return;
    const mapped_edge_type = if (mapping.edge_type_template.len > 0)
        try renderGraphArtifactTemplateAlloc(alloc, mapping.edge_type_template, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value)
    else
        null;
    defer if (mapped_edge_type) |value| alloc.free(value);
    const edge_type = if (mapped_edge_type) |value|
        std.mem.trim(u8, value, &std.ascii.whitespace)
    else
        jsonStringField(item, "type") orelse jsonStringField(item, "edge_type") orelse jsonStringField(item, "relation") orelse return;
    if (edge_type.len == 0) return;

    const mapped_source = if (mapping.source_template.len > 0)
        try renderGraphArtifactTemplateAlloc(alloc, mapping.source_template, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value)
    else
        null;
    defer if (mapped_source) |value| alloc.free(value);
    const source_doc = if (mapped_source) |value| blk: {
        const trimmed = std.mem.trim(u8, value, &std.ascii.whitespace);
        break :blk if (trimmed.len > 0) trimmed else doc_key;
    } else if (item.object.get("source")) |source_value|
        jsonEndpointDocumentIdResolved(source_value, artifact_value) orelse doc_key
    else
        doc_key;

    const mapped_target = if (mapping.target_template.len > 0)
        try renderGraphArtifactTemplateAlloc(alloc, mapping.target_template, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value)
    else
        null;
    defer if (mapped_target) |value| alloc.free(value);
    const target_doc = if (mapped_target) |value| blk: {
        const trimmed = std.mem.trim(u8, value, &std.ascii.whitespace);
        if (trimmed.len == 0) return;
        break :blk trimmed;
    } else blk: {
        const target_value = item.object.get("target") orelse return;
        break :blk jsonEndpointDocumentIdResolved(target_value, artifact_value) orelse return;
    };

    const weight = if (mapping.weight_template.len > 0) blk: {
        const rendered = try renderGraphArtifactTemplateAlloc(alloc, mapping.weight_template, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value);
        defer alloc.free(rendered);
        const trimmed = std.mem.trim(u8, rendered, &std.ascii.whitespace);
        break :blk if (trimmed.len > 0) try std.fmt.parseFloat(f64, trimmed) else 1.0;
    } else jsonFloatField(item, "weight") orelse jsonFloatField(item, "confidence") orelse 1.0;
    const metadata_json = if (mapping.metadata_template_json.len > 0)
        try renderGraphArtifactMetadataTemplateAlloc(alloc, mapping.metadata_template_json, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value)
    else
        try std.json.Stringify.valueAlloc(alloc, item, .{});
    errdefer alloc.free(metadata_json);

    try writes.append(alloc, .{
        .index_name = try alloc.dupe(u8, index_name),
        .source = try alloc.dupe(u8, source_doc),
        .target = try alloc.dupe(u8, target_doc),
        .edge_type = try alloc.dupe(u8, edge_type),
        .weight = weight,
        .created_at = 0,
        .updated_at = 0,
        .metadata_json = metadata_json,
    });
}

fn renderGraphArtifactTemplateAlloc(
    alloc: Allocator,
    template_source: []const u8,
    doc_key: []const u8,
    doc_value: ?std.json.Value,
    item: std.json.Value,
    item_index: usize,
    artifact_name: []const u8,
    artifact_content_type: []const u8,
    artifact_value: std.json.Value,
) ![]u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    var pos: usize = 0;
    while (pos < template_source.len) {
        const start = std.mem.indexOfPos(u8, template_source, pos, "{{") orelse {
            try out.appendSlice(alloc, template_source[pos..]);
            break;
        };
        try out.appendSlice(alloc, template_source[pos..start]);
        const body_start = start + 2;
        const end = std.mem.indexOfPos(u8, template_source, body_start, "}}") orelse {
            try out.appendSlice(alloc, template_source[start..]);
            break;
        };
        const expr = std.mem.trim(u8, template_source[body_start..end], &std.ascii.whitespace);
        const rendered = try renderGraphArtifactExpressionAlloc(alloc, expr, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value);
        defer alloc.free(rendered);
        try out.appendSlice(alloc, rendered);
        pos = end + 2;
    }
    return try out.toOwnedSlice(alloc);
}

fn renderGraphArtifactExpressionAlloc(
    alloc: Allocator,
    expr: []const u8,
    doc_key: []const u8,
    doc_value: ?std.json.Value,
    item: std.json.Value,
    item_index: usize,
    artifact_name: []const u8,
    artifact_content_type: []const u8,
    artifact_value: std.json.Value,
) ![]u8 {
    if (std.mem.startsWith(u8, expr, "default ")) {
        var parts = std.mem.tokenizeAny(u8, expr["default ".len..], &std.ascii.whitespace);
        const path = parts.next() orelse return try alloc.dupe(u8, "");
        const fallback = parts.next() orelse "";
        const value = graphTemplateValue(path, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value);
        const text = if (value) |found| try graphJsonValueTextAlloc(alloc, found) else try alloc.dupe(u8, fallback);
        if (std.mem.trim(u8, text, &std.ascii.whitespace).len == 0 and fallback.len > 0) {
            alloc.free(text);
            return try alloc.dupe(u8, fallback);
        }
        return text;
    }
    if (graphTemplateValue(expr, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value)) |value| {
        return try graphJsonValueTextAlloc(alloc, value);
    }
    return try alloc.dupe(u8, "");
}

fn graphTemplateValue(
    path: []const u8,
    doc_key: []const u8,
    doc_value: ?std.json.Value,
    item: std.json.Value,
    item_index: usize,
    artifact_name: []const u8,
    artifact_content_type: []const u8,
    artifact_value: std.json.Value,
) ?std.json.Value {
    if (std.mem.eql(u8, path, "_doc.key")) return .{ .string = doc_key };
    if (std.mem.startsWith(u8, path, "_doc.value.")) {
        const doc = doc_value orelse return null;
        return selectJsonDotPath(doc, path["_doc.value.".len..]);
    }
    if (std.mem.eql(u8, path, "_artifact.name")) return .{ .string = artifact_name };
    if (std.mem.eql(u8, path, "_artifact.content_type")) return .{ .string = artifact_content_type };
    if (std.mem.eql(u8, path, "_artifact.value")) return artifact_value;
    if (std.mem.startsWith(u8, path, "_artifact.value.")) return selectJsonDotPath(artifact_value, path["_artifact.value.".len..]);
    if (std.mem.eql(u8, path, "_item_index")) return .{ .integer = @intCast(item_index) };
    if (std.mem.eql(u8, path, "_item")) return item;
    if (std.mem.startsWith(u8, path, "_item.")) return selectGraphItemDotPath(item, path["_item.".len..], artifact_value);
    return null;
}

fn selectGraphItemDotPath(item: std.json.Value, path: []const u8, artifact_value: std.json.Value) ?std.json.Value {
    if (std.mem.eql(u8, path, "source") or std.mem.startsWith(u8, path, "source.")) {
        if (item != .object) return null;
        const endpoint = item.object.get("source") orelse return null;
        const selected = resolveGraphEndpointEntity(endpoint, artifact_value) orelse endpoint;
        if (std.mem.eql(u8, path, "source")) return selected;
        return selectJsonDotPath(selected, path["source.".len..]);
    }
    if (std.mem.eql(u8, path, "target") or std.mem.startsWith(u8, path, "target.")) {
        if (item != .object) return null;
        const endpoint = item.object.get("target") orelse return null;
        const selected = resolveGraphEndpointEntity(endpoint, artifact_value) orelse endpoint;
        if (std.mem.eql(u8, path, "target")) return selected;
        return selectJsonDotPath(selected, path["target.".len..]);
    }
    return selectJsonDotPath(item, path);
}

fn selectJsonDotPath(root: std.json.Value, path: []const u8) ?std.json.Value {
    var current = root;
    var parts = std.mem.splitScalar(u8, path, '.');
    while (parts.next()) |part| {
        if (part.len == 0) return null;
        if (current != .object) return null;
        current = current.object.get(part) orelse return null;
    }
    return current;
}

fn graphJsonValueTextAlloc(alloc: Allocator, value: std.json.Value) ![]u8 {
    return switch (value) {
        .null => try alloc.dupe(u8, ""),
        .bool => |b| try alloc.dupe(u8, if (b) "true" else "false"),
        .integer => |n| try std.fmt.allocPrint(alloc, "{d}", .{n}),
        .float => |n| try std.fmt.allocPrint(alloc, "{d}", .{n}),
        .number_string => |s| try alloc.dupe(u8, s),
        .string => |s| try alloc.dupe(u8, s),
        .array, .object => try std.json.Stringify.valueAlloc(alloc, value, .{}),
    };
}

fn renderGraphArtifactMetadataTemplateAlloc(
    alloc: Allocator,
    metadata_template_json: []const u8,
    doc_key: []const u8,
    doc_value: ?std.json.Value,
    item: std.json.Value,
    item_index: usize,
    artifact_name: []const u8,
    artifact_content_type: []const u8,
    artifact_value: std.json.Value,
) ![]u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, metadata_template_json, .{});
    defer parsed.deinit();
    var rendered = try renderGraphArtifactMetadataValueAlloc(alloc, parsed.value, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value);
    defer freeGraphRenderedJsonValue(alloc, &rendered);
    return try std.json.Stringify.valueAlloc(alloc, rendered, .{});
}

fn renderGraphArtifactMetadataValueAlloc(
    alloc: Allocator,
    value: std.json.Value,
    doc_key: []const u8,
    doc_value: ?std.json.Value,
    item: std.json.Value,
    item_index: usize,
    artifact_name: []const u8,
    artifact_content_type: []const u8,
    artifact_value: std.json.Value,
) !std.json.Value {
    return switch (value) {
        .string => |text| .{ .string = try renderGraphArtifactTemplateAlloc(alloc, text, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value) },
        .array => |array| blk: {
            var out = std.json.Array.init(alloc);
            errdefer out.deinit();
            for (array.items) |child| try out.append(try renderGraphArtifactMetadataValueAlloc(alloc, child, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value));
            break :blk .{ .array = out };
        },
        .object => |object| blk: {
            var out = std.json.ObjectMap.empty;
            errdefer out.deinit(alloc);
            var it = object.iterator();
            while (it.next()) |entry| {
                try out.put(alloc, try alloc.dupe(u8, entry.key_ptr.*), try renderGraphArtifactMetadataValueAlloc(alloc, entry.value_ptr.*, doc_key, doc_value, item, item_index, artifact_name, artifact_content_type, artifact_value));
            }
            break :blk .{ .object = out };
        },
        else => value,
    };
}

fn freeGraphRenderedJsonValue(alloc: Allocator, value: *std.json.Value) void {
    switch (value.*) {
        .string => |text| alloc.free(@constCast(text)),
        .array => |*array| {
            for (array.items) |*item| freeGraphRenderedJsonValue(alloc, item);
            array.deinit();
        },
        .object => |*object| {
            var it = object.iterator();
            while (it.next()) |entry| {
                alloc.free(@constCast(entry.key_ptr.*));
                freeGraphRenderedJsonValue(alloc, entry.value_ptr);
            }
            object.deinit(alloc);
        },
        else => {},
    }
    value.* = .null;
}

fn jsonEndpointDocumentId(value: std.json.Value) ?[]const u8 {
    return switch (value) {
        .string => value.string,
        .object => jsonStringField(value, "document_id") orelse jsonStringField(value, "doc_key") orelse jsonStringField(value, "key") orelse jsonStringField(value, "id") orelse jsonStringField(value, "local_id") orelse if (value.object.get("doc_ref")) |doc_ref| jsonEndpointDocumentId(doc_ref) else null,
        else => null,
    };
}

fn jsonEndpointDocumentIdResolved(value: std.json.Value, artifact_value: std.json.Value) ?[]const u8 {
    return jsonEndpointDocumentId(value) orelse if (resolveGraphEndpointEntity(value, artifact_value)) |entity| jsonEndpointDocumentId(entity) else null;
}

fn resolveGraphEndpointEntity(value: std.json.Value, artifact_value: std.json.Value) ?std.json.Value {
    if (value != .object) return null;
    if (jsonIntegerField(value, "entity_index")) |entity_index| return graphArtifactEntityAtIndex(artifact_value, entity_index);
    const entity_id = jsonStringField(value, "entity_id") orelse jsonStringField(value, "id") orelse jsonStringField(value, "local_id") orelse return null;
    return findGraphArtifactEntity(artifact_value, entity_id);
}

fn findGraphArtifactEntity(artifact_value: std.json.Value, entity_id: []const u8) ?std.json.Value {
    if (artifact_value != .object) return null;
    const entities = artifact_value.object.get("_entities") orelse artifact_value.object.get("entities") orelse return null;
    return switch (entities) {
        .array => |array| blk: {
            for (array.items) |entity| {
                const id = jsonStringField(entity, "id") orelse jsonStringField(entity, "local_id") orelse continue;
                if (std.mem.eql(u8, id, entity_id)) break :blk entity;
            }
            break :blk null;
        },
        .object => entities.object.get(entity_id),
        else => null,
    };
}

fn graphArtifactEntityAtIndex(artifact_value: std.json.Value, entity_index: i64) ?std.json.Value {
    if (entity_index < 0 or artifact_value != .object) return null;
    const entities = artifact_value.object.get("_entities") orelse artifact_value.object.get("entities") orelse return null;
    if (entities != .array) return null;
    const index: usize = @intCast(entity_index);
    if (index >= entities.array.items.len) return null;
    return entities.array.items[index];
}

fn jsonStringField(value: std.json.Value, field: []const u8) ?[]const u8 {
    if (value != .object) return null;
    const found = value.object.get(field) orelse return null;
    return if (found == .string) found.string else null;
}

fn jsonIntegerField(value: std.json.Value, field: []const u8) ?i64 {
    if (value != .object) return null;
    const found = value.object.get(field) orelse return null;
    return switch (found) {
        .integer => found.integer,
        else => null,
    };
}

fn jsonFloatField(value: std.json.Value, field: []const u8) ?f64 {
    if (value != .object) return null;
    const found = value.object.get(field) orelse return null;
    return switch (found) {
        .float => found.float,
        .integer => @floatFromInt(found.integer),
        else => null,
    };
}

const OwnedGraphMutations = struct {
    alloc: Allocator,
    writes: []types.GraphEdgeWrite = &.{},
    deletes: []types.GraphEdgeDelete = &.{},

    fn deinit(self: *OwnedGraphMutations) void {
        for (self.writes) |write| {
            self.alloc.free(@constCast(write.index_name));
            self.alloc.free(@constCast(write.source));
            self.alloc.free(@constCast(write.target));
            self.alloc.free(@constCast(write.edge_type));
            if (write.metadata_json.len > 0) self.alloc.free(@constCast(write.metadata_json));
        }
        if (self.writes.len > 0) self.alloc.free(self.writes);

        for (self.deletes) |delete| {
            self.alloc.free(@constCast(delete.index_name));
            self.alloc.free(@constCast(delete.source));
            self.alloc.free(@constCast(delete.target));
            self.alloc.free(@constCast(delete.edge_type));
        }
        if (self.deletes.len > 0) self.alloc.free(self.deletes);
        self.* = undefined;
    }
};

const GraphMutationCollectionOptions = struct {
    repair_ctx: ?*const AsyncContext = null,
    sequence: u64 = 0,
};

fn collectGraphMutationsForArtifacts(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    artifact_keys: []const []const u8,
    index_name: []const u8,
    options: GraphMutationCollectionOptions,
) !OwnedGraphMutations {
    var writes = std.ArrayListUnmanaged(types.GraphEdgeWrite).empty;
    errdefer {
        for (writes.items) |write| {
            alloc.free(@constCast(write.index_name));
            alloc.free(@constCast(write.source));
            alloc.free(@constCast(write.target));
            alloc.free(@constCast(write.edge_type));
            if (write.metadata_json.len > 0) alloc.free(@constCast(write.metadata_json));
        }
        writes.deinit(alloc);
    }
    var deletes = std.ArrayListUnmanaged(types.GraphEdgeDelete).empty;
    errdefer {
        for (deletes.items) |delete| {
            alloc.free(@constCast(delete.index_name));
            alloc.free(@constCast(delete.source));
            alloc.free(@constCast(delete.target));
            alloc.free(@constCast(delete.edge_type));
        }
        deletes.deinit(alloc);
    }

    var txn = try store.beginReadTxn();
    defer txn.abort();

    for (artifact_keys) |artifact_key| {
        const parsed = (try internal_keys.parseGraphEdgeArtifactKeyAlloc(alloc, artifact_key)) orelse continue;
        defer {
            alloc.free(parsed.doc_key);
            alloc.free(parsed.index_name);
            alloc.free(parsed.edge_type);
            alloc.free(parsed.target_doc_key);
        }
        if (!std.mem.eql(u8, parsed.index_name, index_name)) continue;

        const raw = txn.get(artifact_key) catch |err| switch (err) {
            error.NotFound => null,
            else => return err,
        };
        if (raw) |value| {
            var decoded = enrichment_artifact_codec.decodeGraphEdgeAlloc(alloc, value) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => {
                    if (options.repair_ctx) |repair_ctx| {
                        const artifact_name = try std.fmt.allocPrint(alloc, "{s}:{s}", .{ parsed.edge_type, parsed.target_doc_key });
                        defer alloc.free(artifact_name);
                        try recordArtifactRepairIssueContext(
                            repair_ctx,
                            .graph,
                            parsed.index_name,
                            parsed.doc_key,
                            "",
                            "",
                            "",
                            artifact_name,
                            artifact_key,
                            null,
                            options.sequence,
                            .corrupt_artifact,
                        );
                        return error.ArtifactRepairRequired;
                    }
                    return err;
                },
            };
            errdefer decoded.deinit(alloc);
            try writes.append(alloc, .{
                .index_name = try alloc.dupe(u8, parsed.index_name),
                .source = try alloc.dupe(u8, parsed.doc_key),
                .target = try alloc.dupe(u8, parsed.target_doc_key),
                .edge_type = try alloc.dupe(u8, parsed.edge_type),
                .weight = decoded.weight,
                .created_at = decoded.created_at,
                .updated_at = decoded.updated_at,
                .metadata_json = decoded.metadata_json,
            });
            decoded.metadata_json = &.{};
            decoded.deinit(alloc);
        } else {
            try deletes.append(alloc, .{
                .index_name = try alloc.dupe(u8, parsed.index_name),
                .source = try alloc.dupe(u8, parsed.doc_key),
                .target = try alloc.dupe(u8, parsed.target_doc_key),
                .edge_type = try alloc.dupe(u8, parsed.edge_type),
            });
        }
    }

    return .{
        .alloc = alloc,
        .writes = try writes.toOwnedSlice(alloc),
        .deletes = try deletes.toOwnedSlice(alloc),
    };
}

fn collectManagedSyncTargets(
    alloc: Allocator,
    index_manager: *index_manager_mod.IndexManager,
    batch: derived_types.DerivedBatch,
) !ManagedSyncTargets {
    const managed_indexes = try index_manager.managedIndexes(alloc);
    defer {
        for (managed_indexes) |index_ref| alloc.free(@constCast(index_ref.name));
        alloc.free(managed_indexes);
    }

    var full_text_indexes = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (full_text_indexes.items) |name| alloc.free(@constCast(name));
        full_text_indexes.deinit(alloc);
    }
    var all_indexes = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (all_indexes.items) |name| alloc.free(@constCast(name));
        all_indexes.deinit(alloc);
    }

    for (managed_indexes) |index_ref| {
        if (!batchAffectsManagedIndex(index_manager, batch, index_ref)) continue;
        try appendUniqueOwnedName(alloc, &all_indexes, index_ref.name);
        if (index_ref.kind == .full_text) {
            try appendUniqueOwnedName(alloc, &full_text_indexes, index_ref.name);
        }
    }

    return .{
        .full_text_indexes = try full_text_indexes.toOwnedSlice(alloc),
        .all_indexes = try all_indexes.toOwnedSlice(alloc),
    };
}

fn appendUniqueOwnedName(
    alloc: Allocator,
    items: *std.ArrayListUnmanaged([]const u8),
    value: []const u8,
) !void {
    for (items.items) |existing| {
        if (std.mem.eql(u8, existing, value)) return;
    }
    try items.append(alloc, try alloc.dupe(u8, value));
}

fn waitForManagedIndexesApplied(self: *DB, sequence: u64, index_names: []const []const u8) !void {
    if (sequence == 0 or index_names.len == 0) return;
    _ = self;
    // runDerivedUntil()/waitForAll() returns after the relevant workers have
    // applied the sequence. Persisted watermarks are replay-retention state and
    // may be coalesced independently of foreground visibility.
}

fn waitForManagedIndexesAppliedContext(
    ctx: *const BatchExecutionContext,
    sequence: u64,
    index_names: []const []const u8,
) !void {
    if (sequence == 0 or index_names.len == 0) return;
    _ = ctx;
    // runDerivedUntilContext()/waitForAll() returns after the relevant workers
    // have applied the sequence. Persisted watermarks are replay-retention state
    // and may be coalesced independently of foreground visibility.
}

fn applyGraphDocClearsForIndex(ctx: *const AsyncContext, clears: []const derived_types.DerivedGraphDocClear, index_name: []const u8) !void {
    for (clears) |clear| {
        for (clear.index_names) |clear_index_name| {
            if (!std.mem.eql(u8, clear_index_name, index_name)) continue;
            try ctx.index_manager.deleteGraphDocInIndexes(clear.key, &.{index_name});
            break;
        }
    }
}

fn applyDerivedBatchToIndexReplay(ctx_ptr: *anyopaque, batch: derived_types.DerivedBatch, index_ref: index_manager_mod.ManagedIndexRef) !bool {
    const replay_ctx: *ReplayApplyContext = @ptrCast(@alignCast(ctx_ptr));
    const self = replay_ctx.db;
    const resources = self.core.asyncResources();
    if (!try batchAdvancesManagedIndexApplyStateForReplay(resources.index_manager, batch, index_ref)) return false;
    const ctx = AsyncContext{
        .alloc = self.alloc,
        .store = resources.store,
        .applied_sequence_checkpoint_path = resources.applied_sequence_checkpoint_path,
        .index_manager = resources.index_manager,
        .apply_mutex = resources.apply_mutex,
        .dense_bulk_session_scope = replay_ctx.dense_bulk_session_scope,
        .require_graph_resolution_contract = true,
    };
    try applyDerivedBatchToIndexContext(&ctx, batch, index_ref);
    return true;
}

fn beginDerivedCatchUpWindow(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef) !void {
    if (index_ref.kind != .dense_vector) return;
    const replay_ctx: *ReplayApplyContext = @ptrCast(@alignCast(ctx_ptr));
    try replay_ctx.db.core.batchExecutionResources().index_manager.beginDenseStreamingReplaySessionByName(index_ref.name);
}

fn finishDerivedCatchUpWindow(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef, success: bool) !void {
    if (index_ref.kind != .dense_vector) return;
    const replay_ctx: *ReplayApplyContext = @ptrCast(@alignCast(ctx_ptr));
    const resources = replay_ctx.db.core.batchExecutionResources();
    if (!success) {
        resources.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
        return;
    }
    errdefer resources.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
    const finish_start_ns = monotonicTimeNs();
    try resources.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_ref.name, denseCatchUpFinishOptions());
    try resources.index_manager.checkpointLsmWalForManagedIndex(index_ref);
    if (resources.index_manager.resource_manager) |manager| {
        manager.noteDenseReplayWindowResult(.{ .finish_ns = elapsedSince(finish_start_ns) });
    }
}

fn beginDerivedCatchUpWindowContext(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef) !void {
    if (index_ref.kind != .dense_vector) return;
    const replay_ctx: *ReplayApplyContextBatch = @ptrCast(@alignCast(ctx_ptr));
    try replay_ctx.batch.index_manager.beginDenseStreamingReplaySessionByName(index_ref.name);
}

fn finishDerivedCatchUpWindowContext(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef, success: bool) !void {
    if (index_ref.kind != .dense_vector) return;
    const replay_ctx: *ReplayApplyContextBatch = @ptrCast(@alignCast(ctx_ptr));
    if (!success) {
        replay_ctx.batch.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
        return;
    }
    errdefer replay_ctx.batch.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
    const finish_start_ns = monotonicTimeNs();
    try replay_ctx.batch.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_ref.name, denseCatchUpFinishOptions());
    try replay_ctx.batch.index_manager.checkpointLsmWalForManagedIndex(index_ref);
    if (replay_ctx.batch.index_manager.resource_manager) |manager| {
        manager.noteDenseReplayWindowResult(.{ .finish_ns = elapsedSince(finish_start_ns) });
    }
}

fn truncateReplayJournalIfSafe(self: *DB) !void {
    var ctx = self.batchContext();
    return try truncateReplayJournalIfSafeContext(&ctx);
}

fn truncateReplayLogs(ctx: *const BatchExecutionContext, up_to_sequence: u64) !void {
    try ctx.store.truncateReplayUpTo(ctx.alloc, up_to_sequence);
    ctx.executor.releaseBacklogThrough(up_to_sequence);
}

fn resolverReplayRetentionRequired(index_manager: *const index_manager_mod.IndexManager, stats: types.ReplayStageStats) bool {
    if (stats.blocked) return true;
    return index_manager.resolvers.items.len > 0;
}

fn clampReplayTruncationForReplayStage(
    effective: u64,
    index_manager: *const index_manager_mod.IndexManager,
    stats: types.ReplayStageStats,
) u64 {
    if (!resolverReplayRetentionRequired(index_manager, stats)) return effective;
    return @min(effective, stats.applied_sequence);
}

fn clampReplayTruncationForRepairPins(
    alloc: Allocator,
    checkpoint_path: ?[]const u8,
    effective: u64,
) !u64 {
    const path = checkpoint_path orelse return effective;
    var state = index_repair_state.load(alloc, path) catch |err| switch (err) {
        error.FileNotFound => return effective,
        // A malformed local repair checkpoint may have contained a zero or
        // finalized replay pin. Retain everything until an operator repairs
        // the checkpoint; never convert corruption into replay loss.
        error.InvalidIndexRepairState => return 0,
        else => return err,
    };
    defer state.deinit(alloc);
    const pin = state.minimumRetainAfterSequence() orelse return effective;
    return @min(effective, pin);
}

fn truncateReplaySequenceAsync(ctx_ptr: *anyopaque, sequence: u64) !void {
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    if (ctx.repair_replay_mutex) |mutex| lockAtomic(mutex);
    defer if (ctx.repair_replay_mutex) |mutex| mutex.unlock();
    var effective = sequence;
    // The resolution/promotion stages consume the replay journal but are not
    // executor workers. Clamp truncation to their applied watermarks whenever a
    // resolver is configured, even before the synchronous driver has raised the
    // stage target for the newest write. Resolver removal drains or refuses
    // pending stage work before deleting catalog state, so a never-configured
    // resolver pipeline does not pin generic replay hints.
    if (ctx.resolution_runtime) |runtime| {
        effective = clampReplayTruncationForReplayStage(effective, ctx.index_manager, runtime.stats());
    }
    if (ctx.promotion_runtime) |runtime| {
        effective = clampReplayTruncationForReplayStage(effective, ctx.index_manager, runtime.stats());
    }
    effective = try clampReplayTruncationForRepairPins(ctx.alloc, ctx.index_repair_checkpoint_path, effective);
    try ctx.store.truncateReplayUpTo(ctx.alloc, effective);
}

fn truncateReplayJournalIfSafeContext(ctx: *const BatchExecutionContext) !void {
    if (ctx.repair_replay_mutex) |mutex| lockAtomic(mutex);
    defer if (ctx.repair_replay_mutex) |mutex| mutex.unlock();
    if (!ctx.index_manager.hasManagedIndexes()) return;

    const managed_indexes = try ctx.index_manager.managedIndexes(ctx.alloc);
    defer {
        for (managed_indexes) |index_ref| ctx.alloc.free(@constCast(index_ref.name));
        ctx.alloc.free(managed_indexes);
    }
    if (managed_indexes.len == 0) return;

    var min_applied: u64 = std.math.maxInt(u64);
    for (managed_indexes) |index_ref| {
        const applied = try apply_state.loadAppliedSequenceWithCheckpoint(
            ctx.alloc,
            ctx.store,
            ctx.applied_sequence_checkpoint_path,
            index_ref.name,
        );
        min_applied = @min(min_applied, applied);
    }
    if (ctx.index_manager.hasGeneratedEnrichmentTargets()) {
        const enrichment_applied = try enrichment_state.loadAppliedSequence(
            ctx.alloc,
            ctx.store,
            enrichment_runtime_mod.scope_name,
        );
        min_applied = @min(min_applied, enrichment_applied);
    }
    if (ctx.resolution_runtime) |runtime| {
        const stats = runtime.stats();
        if (resolverReplayRetentionRequired(ctx.index_manager, stats)) {
            min_applied = @min(min_applied, stats.applied_sequence);
        }
    }
    if (ctx.promotion_runtime) |runtime| {
        const stats = runtime.stats();
        if (resolverReplayRetentionRequired(ctx.index_manager, stats)) {
            min_applied = @min(min_applied, stats.applied_sequence);
        }
    }
    min_applied = try clampReplayTruncationForRepairPins(ctx.alloc, ctx.index_repair_checkpoint_path, min_applied);
    if (min_applied == 0 or min_applied == std.math.maxInt(u64)) return;
    try truncateReplayLogs(ctx, min_applied);
}

fn startAsyncWorkers(self: *DB) !void {
    const managed_indexes = try self.core.managedIndexes(self.alloc);
    defer {
        for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
        self.alloc.free(managed_indexes);
    }

    for (managed_indexes) |index_ref| {
        const applied = try self.core.loadAppliedSequence(self.alloc, index_ref.name);
        try self.executor.addWorker(index_ref.name, index_ref, applied);
    }
}

fn applyDerivedBatchToShadowIfNeeded(self: *DB, batch: derived_types.DerivedBatch) !void {
    const shadow = self.shadow orelse return;
    const state = self.core.splitState() orelse return;
    if (state.phase != .splitting) return;

    const managed_indexes = try shadow.manager.managedIndexes(self.alloc);
    defer {
        for (managed_indexes) |index_ref| self.alloc.free(@constCast(index_ref.name));
        self.alloc.free(managed_indexes);
    }

    const async_resources = self.core.asyncResources();
    const ctx = AsyncContext{
        .alloc = self.alloc,
        .store = async_resources.store,
        .applied_sequence_checkpoint_path = async_resources.applied_sequence_checkpoint_path,
        .index_manager = shadow.manager,
        .apply_mutex = async_resources.apply_mutex,
        .allow_graph_materialization = false,
    };

    for (managed_indexes) |index_ref| {
        if (!batchAffectsManagedIndex(shadow.manager, batch, index_ref)) continue;
        try applyDerivedBatchToIndexContext(&ctx, batch, index_ref);
    }
}

const OpenedSplitDestinationStore = struct {
    store: docstore_mod.DocStore,
    owner: db_core.PrimaryStoreOwner = .none,

    fn close(self: *OpenedSplitDestinationStore, alloc: Allocator) void {
        self.store.close();
        self.owner.close(alloc);
        self.* = undefined;
    }
};

fn openSplitDestinationStore(self: *DB, dest_dir: []const u8) !OpenedSplitDestinationStore {
    const dest_path_z = try self.alloc.dupeZ(u8, dest_dir);
    defer self.alloc.free(dest_path_z);

    return switch (splitDestinationStorePlan(self)) {
        .lmdb => .{
            .store = try docstore_mod.DocStore.open(self.alloc, dest_path_z, .{
                .no_sync = true,
                .no_meta_sync = true,
            }),
        },
        .lsm => |split_opts| blk: {
            var dest_opts = split_opts;
            dest_opts.background_executor = null;
            var handle = try lsm_backend_mod.BackendHandle.open(self.alloc, dest_dir, dest_opts);
            errdefer handle.close();

            var runtime_store = try handle.backend.runtimeStore(self.alloc, .{ .name = "docs" });
            errdefer runtime_store.deinit();

            break :blk .{
                .store = try docstore_mod.DocStore.openRuntime(self.alloc, runtime_store),
                .owner = .{ .lsm = .{
                    .handle = handle,
                    .split_options = null,
                } },
            };
        },
        .unsupported => error.Unsupported,
    };
}

fn tryPreparePrimarySplitFast(self: *DB, split_lower: []const u8, dest_dir: []const u8) !bool {
    const owner_fast = try self.core.primary_store_owner.prepareSplitRightToDir(split_lower, dest_dir);
    if (owner_fast) return true;

    return try self.core.splitRightStoreToDir(split_lower, dest_dir);
}

fn tryFinalizePrimarySplitFast(self: *DB, split_lower: []const u8) !bool {
    const owner_fast = try self.core.primary_store_owner.rewriteLeftInPlace(split_lower);
    if (owner_fast) return true;

    return try self.core.rewriteLeftStoreInPlace(split_lower);
}

fn identityMetadataRange() struct { lower: [1]u8, upper: [1]u8 } {
    return .{
        .lower = .{internal_keys.identity_namespace},
        .upper = .{internal_keys.identity_namespace + 1},
    };
}

fn putIdentityMetadataRows(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    rows: []const docstore_mod.OwnedKVPair,
) !void {
    if (rows.len == 0) return;

    var writes = try alloc.alloc(docstore_mod.KVPair, rows.len);
    defer alloc.free(writes);
    for (rows, 0..) |row, i| {
        writes[i] = .{
            .key = row.key,
            .value = row.value,
        };
    }
    try store.putBatch(writes, &.{});
}

fn copyIdentityMetadataToStore(
    alloc: Allocator,
    src_store: *docstore_mod.DocStore,
    dest_store: *docstore_mod.DocStore,
) !void {
    const range = identityMetadataRange();
    const rows = try src_store.scanRange(alloc, range.lower[0..], range.upper[0..]);
    defer docstore_mod.DocStore.freeResults(alloc, rows);
    try putIdentityMetadataRows(alloc, dest_store, rows);
}

fn finalizePrimarySplitPreservingIdentity(self: *DB, split_lower: []const u8) !void {
    const range = identityMetadataRange();
    const identity_rows = try self.core.store.scanRange(self.alloc, range.lower[0..], range.upper[0..]);
    defer docstore_mod.DocStore.freeResults(self.alloc, identity_rows);

    _ = try tryFinalizePrimarySplitFast(self, split_lower);
    try putIdentityMetadataRows(self.alloc, self.core.store, identity_rows);
}

fn prepareSplitDestination(self: *DB, byte_range: types.ByteRange, dest_dir: []const u8) !void {
    try ensureDirPath(dest_dir);
    const split_lower = try documentRangeLowerAlloc(self.alloc, byte_range.start);
    defer self.alloc.free(split_lower);

    const page_split_built = try tryPreparePrimarySplitFast(self, split_lower, dest_dir);

    var opened_dest_store = try openSplitDestinationStore(self, dest_dir);
    defer opened_dest_store.close(self.alloc);
    const dest_store = &opened_dest_store.store;
    var dest_indexes = try index_manager_mod.IndexManager.initWithOptions(
        self.alloc,
        dest_dir,
        self.index_backends,
    );
    defer dest_indexes.deinit();
    dest_indexes.setRelaxedSplitDurability(true);
    const dest_applied_sequence_checkpoint_path = try apply_state.checkpointPathAlloc(self.alloc, dest_dir);
    defer self.alloc.free(dest_applied_sequence_checkpoint_path);
    dest_indexes.setAppliedSequenceCheckpointPath(dest_applied_sequence_checkpoint_path);

    try clearSplitMetadataFromStore(self.alloc, dest_store);
    try clearSystemMetadataFromSplitDestination(self.alloc, dest_store);
    try copyIdentityMetadataToStore(self.alloc, self.core.store, dest_store);
    const replay_floor = self.core.nextDerivedAppendSequence();
    try ensureReplayFloor(dest_store, replay_floor);

    const split_doc_frontier = if (page_split_built)
        try collectSplitFrontierDocKeys(self.alloc, dest_store, byte_range.start, byte_range.end)
    else
        &.{};
    defer {
        for (split_doc_frontier) |key| self.alloc.free(key);
        if (split_doc_frontier.len > 0) self.alloc.free(split_doc_frontier);
    }

    dest_indexes.updateRange(byte_range);
    try range_state_mod.saveRange(dest_store, byte_range);
    try self.core.saveSchemaCloneTo(dest_store);

    const configs = try self.core.listIndexes(self.alloc);
    defer types.freeIndexConfigs(self.alloc, configs);
    try registerSplitDestinationIndexesDirect(self.alloc, dest_store, dest_applied_sequence_checkpoint_path, &dest_indexes, configs, replay_floor -| 1);
    const collect_skip_doc_keys = true;
    var split_handoffs = try self.core.collectSplitIndexHandoffs(
        &dest_indexes,
        dest_store,
        split_doc_frontier,
        byte_range,
        collect_skip_doc_keys,
    );
    defer split_handoffs.deinit(self.alloc);
    _ = try dest_indexes.copyGraphSplitDestinationFrom(self.core.index_manager, byte_range.start, byte_range.end);
    _ = try dest_indexes.rebuildGraphSplitDestination(byte_range.start, byte_range.end);
    if (page_split_built) {
        try applySplitEmbeddingArtifactsInRange(
            self.alloc,
            byte_range.start,
            byte_range.end,
            dest_store,
            &dest_indexes,
            split_handoffs.dense,
            split_handoffs.sparse,
        );
    }
    if (page_split_built) {
        if (dest_indexes.splitDestinationNeedsDocumentIndexing(split_handoffs.dense, split_handoffs.text, split_handoffs.sparse)) {
            if (!collect_skip_doc_keys) return error.UnexpectedSplitResidualIndexing;
            try indexExistingSplitDestinationDirect(
                self.alloc,
                byte_range.start,
                byte_range.end,
                dest_store,
                &dest_indexes,
                split_handoffs.dense,
                split_handoffs.text,
                split_handoffs.sparse,
            );
        }
    } else {
        try streamRangeIntoSplitDestinationDirect(
            self.alloc,
            self,
            byte_range.start,
            byte_range.end,
            dest_store,
            &dest_indexes,
            split_handoffs.dense,
            split_handoffs.text,
            split_handoffs.sparse,
        );
    }
    try applySplitGraphArtifactsInRange(
        self.alloc,
        byte_range.start,
        byte_range.end,
        dest_store,
        &dest_indexes,
    );

    try dest_indexes.syncAll(true);
    try dest_store.sync(true);
}

fn collectSplitFrontierDocKeys(alloc: Allocator, store: *docstore_mod.DocStore, lower: []const u8, upper: []const u8) ![][]u8 {
    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);

    const scanned = try store.scanRange(alloc, store_lower, if (store_upper) |buf| buf else "");
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var keys = std.ArrayListUnmanaged([]u8).empty;
    errdefer {
        for (keys.items) |key| alloc.free(key);
        keys.deinit(alloc);
    }

    for (scanned) |entry| {
        if (!isPrimaryDocumentStoreKey(entry.key)) continue;
        const raw = (try internal_keys.decodePrimaryDocumentKeyAlloc(alloc, entry.key)) orelse continue;
        try keys.append(alloc, raw);
    }

    return try keys.toOwnedSlice(alloc);
}

fn registerSplitDestinationIndexesDirect(
    alloc: Allocator,
    dest_store: *docstore_mod.DocStore,
    applied_sequence_checkpoint_path: ?[]const u8,
    dest_indexes: *index_manager_mod.IndexManager,
    configs: []const types.IndexConfig,
    applied_sequence: u64,
) !void {
    if (configs.len == 0) return;

    try dest_indexes.addAllNoBackfill(dest_store, configs);
    var updates = try alloc.alloc(apply_state.AppliedSequenceUpdate, configs.len);
    defer alloc.free(updates);
    for (configs, 0..) |cfg, i| {
        updates[i] = .{
            .index_name = cfg.name,
            .sequence = applied_sequence,
            .config_hash = types.indexConfigHash(cfg),
        };
    }
    try saveDenseProjectionMetadataForAppliedSequenceUpdates(dest_indexes, updates);
    try apply_state.saveAppliedSequencesWithCheckpoint(alloc, dest_store, applied_sequence_checkpoint_path, updates);
}

fn streamRangeIntoSplitDestinationDirect(
    alloc: Allocator,
    src: *DB,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    text_handoffs: []const index_manager_mod.TextSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    const batch_size = 8192;

    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);

    const scanned = try src.core.scanStoreRange(alloc, store_lower, if (store_upper) |buf| buf else "");
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
    defer writes.deinit(alloc);
    for (scanned) |entry| {
        if (isSplitMetadataKey(entry.key) or std.mem.startsWith(u8, entry.key, "\x00\x00__metadata__:")) continue;
        try writes.append(alloc, .{
            .key = entry.key,
            .value = entry.value,
        });
        if (writes.items.len == batch_size) {
            try putIndexedSplitBatchDirect(dest_store, dest_indexes, writes.items, dense_handoffs, text_handoffs, sparse_handoffs);
            writes.clearRetainingCapacity();
        }
    }

    if (writes.items.len > 0) try putIndexedSplitBatchDirect(dest_store, dest_indexes, writes.items, dense_handoffs, text_handoffs, sparse_handoffs);
}

fn copyGraphEdgeRangeIntoSplitDestination(
    alloc: Allocator,
    src: *DB,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
) !void {
    const batch_size = 1024;

    const scanned = try src.core.scanStoreRange(alloc, lower, upper);
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer writes.deinit(alloc);
    for (scanned) |entry| {
        if (!docstore_mod.KeyEncoder.isEdgeKey(entry.key)) continue;
        try writes.append(alloc, .{
            .key = entry.key,
            .value = entry.value,
        });
        if (writes.items.len == batch_size) {
            try dest_store.putBatch(writes.items, &.{});
            writes.clearRetainingCapacity();
        }
    }

    if (writes.items.len > 0) try dest_store.putBatch(writes.items, &.{});
}

fn putIndexedSplitBatchDirect(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    writes: []const types.BatchWrite,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    text_handoffs: []const index_manager_mod.TextSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    if (writes.len == 0) return;

    const raw_writes: []const docstore_mod.KVPair = @ptrCast(writes);
    try dest_store.putBatch(raw_writes, &.{});

    try applySplitEmbeddingArtifactsFromBatch(dest_store, dest_indexes, writes, dense_handoffs, sparse_handoffs);

    var logical_writes = try dest_indexes.alloc.alloc(types.BatchWrite, writes.len);
    defer dest_indexes.alloc.free(logical_writes);
    var owned_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_keys.items) |key| dest_indexes.alloc.free(key);
        owned_keys.deinit(dest_indexes.alloc);
    }

    for (writes, 0..) |write, i| {
        if (internal_keys.isPrimaryDocumentKey(write.key)) {
            const raw = (try internal_keys.decodePrimaryDocumentKeyAlloc(dest_indexes.alloc, write.key)) orelse return error.InvalidInternalUserKey;
            try owned_keys.append(dest_indexes.alloc, raw);
            logical_writes[i] = .{
                .key = raw,
                .value = write.value,
            };
        } else {
            logical_writes[i] = write;
        }
    }

    try dest_indexes.indexSplitBatch(dest_store, logical_writes, dense_handoffs, text_handoffs, sparse_handoffs);
}

fn findDenseSplitHandoffLocal(handoffs: []const index_manager_mod.DenseSplitHandoff, index_name: []const u8) ?*const index_manager_mod.DenseSplitHandoff {
    for (handoffs) |*handoff| {
        if (std.mem.eql(u8, handoff.index_name, index_name)) return handoff;
    }
    return null;
}

fn findSparseSplitHandoffLocal(handoffs: []const index_manager_mod.SparseSplitHandoff, index_name: []const u8) ?*const index_manager_mod.SparseSplitHandoff {
    for (handoffs) |*handoff| {
        if (std.mem.eql(u8, handoff.index_name, index_name)) return handoff;
    }
    return null;
}

fn collectEmbeddingArtifactKeysFromBatch(
    alloc: Allocator,
    writes: []const types.BatchWrite,
) ![][]const u8 {
    var keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer keys.deinit(alloc);

    for (writes) |write| {
        if (!internal_keys.isEmbeddingArtifactKey(write.key) and !internal_keys.isDerivedEmbeddingArtifactKey(write.key)) continue;
        try keys.append(alloc, write.key);
    }

    return try keys.toOwnedSlice(alloc);
}

fn collectEmbeddingArtifactKeysInRangeAlloc(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    lower: []const u8,
    upper: []const u8,
) ![][]const u8 {
    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);

    const scanned = try store.scanRange(alloc, store_lower, if (store_upper) |buf| buf else "");
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (keys.items) |key| alloc.free(@constCast(key));
        keys.deinit(alloc);
    }

    for (scanned) |entry| {
        if (!internal_keys.isEmbeddingArtifactKey(entry.key) and !internal_keys.isDerivedEmbeddingArtifactKey(entry.key)) continue;
        const owned = try alloc.dupe(u8, entry.key);
        try keys.append(alloc, owned);
    }

    return try keys.toOwnedSlice(alloc);
}

fn collectGraphArtifactKeysInRangeAlloc(
    alloc: Allocator,
    store: *docstore_mod.DocStore,
    lower: []const u8,
    upper: []const u8,
) ![][]const u8 {
    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);

    const scanned = try store.scanRange(alloc, store_lower, if (store_upper) |buf| buf else "");
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var keys = std.ArrayListUnmanaged([]const u8).empty;
    errdefer {
        for (keys.items) |key| alloc.free(@constCast(key));
        keys.deinit(alloc);
    }

    for (scanned) |entry| {
        if (!internal_keys.isGraphEdgeArtifactKey(entry.key)) continue;
        const owned = try alloc.dupe(u8, entry.key);
        try keys.append(alloc, owned);
    }

    return try keys.toOwnedSlice(alloc);
}

fn freeOwnedConstStringSlice(alloc: Allocator, keys: []const []const u8) void {
    for (keys) |key| alloc.free(@constCast(key));
    if (keys.len > 0) alloc.free(keys);
}

fn applySplitDenseEmbeddingArtifacts(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
    index_name: []const u8,
    handoff: ?*const index_manager_mod.DenseSplitHandoff,
) !void {
    var dense_embeddings = try collectDenseEmbeddingWritesForArtifacts(
        dest_indexes.alloc,
        dest_indexes,
        artifact_keys,
        index_name,
    );
    defer dense_embeddings.deinit();
    if (dense_embeddings.writes.len == 0) return;

    if (handoff) |skip| {
        var filtered = std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite).empty;
        defer filtered.deinit(dest_indexes.alloc);
        for (dense_embeddings.writes) |write| {
            if (skip.shouldSkip(write.doc_key)) continue;
            try filtered.append(dest_indexes.alloc, write);
        }
        if (filtered.items.len == 0) return;
        try dest_indexes.applyDenseEmbeddingWritesByNameWithOptions(dest_store, index_name, filtered.items, .{ .mode = .bulk_ingest });
        return;
    }

    try dest_indexes.applyDenseEmbeddingWritesByNameWithOptions(dest_store, index_name, dense_embeddings.writes, .{ .mode = .bulk_ingest });
}

fn applySplitSparseEmbeddingArtifacts(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
    index_name: []const u8,
    handoff: ?*const index_manager_mod.SparseSplitHandoff,
) !void {
    var sparse_embeddings = try collectSparseEmbeddingWritesForArtifacts(
        dest_indexes.alloc,
        dest_indexes,
        artifact_keys,
        index_name,
    );
    defer sparse_embeddings.deinit();
    if (sparse_embeddings.writes.len == 0) return;

    if (handoff) |skip| {
        var filtered = std.ArrayListUnmanaged(mapper.SparseEmbeddingWrite).empty;
        defer filtered.deinit(dest_indexes.alloc);
        for (sparse_embeddings.writes) |write| {
            if (skip.shouldSkip(write.doc_key)) continue;
            try filtered.append(dest_indexes.alloc, write);
        }
        if (filtered.items.len == 0) return;
        try dest_indexes.applySparseEmbeddingWritesByNameWithOptions(dest_store, index_name, filtered.items, .{ .mode = .bulk_ingest });
        return;
    }

    try dest_indexes.applySparseEmbeddingWritesByNameWithOptions(dest_store, index_name, sparse_embeddings.writes, .{ .mode = .bulk_ingest });
}

fn applySplitEmbeddingArtifacts(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    if (artifact_keys.len == 0) return;

    for (dest_indexes.dense_indexes.items) |entry| {
        try applySplitDenseEmbeddingArtifacts(
            dest_store,
            dest_indexes,
            artifact_keys,
            entry.config.name,
            findDenseSplitHandoffLocal(dense_handoffs, entry.config.name),
        );
    }

    for (dest_indexes.sparse_indexes.items) |entry| {
        try applySplitSparseEmbeddingArtifacts(
            dest_store,
            dest_indexes,
            artifact_keys,
            entry.config.name,
            findSparseSplitHandoffLocal(sparse_handoffs, entry.config.name),
        );
    }
}

fn applySplitEmbeddingArtifactsFromBatch(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    writes: []const types.BatchWrite,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    const artifact_keys = try collectEmbeddingArtifactKeysFromBatch(dest_indexes.alloc, writes);
    defer if (artifact_keys.len > 0) dest_indexes.alloc.free(artifact_keys);
    try applySplitEmbeddingArtifacts(dest_store, dest_indexes, artifact_keys, dense_handoffs, sparse_handoffs);
}

fn applySplitEmbeddingArtifactsInRange(
    alloc: Allocator,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    const artifact_keys = try collectEmbeddingArtifactKeysInRangeAlloc(alloc, dest_store, lower, upper);
    defer freeOwnedConstStringSlice(alloc, artifact_keys);
    try applySplitEmbeddingArtifacts(dest_store, dest_indexes, artifact_keys, dense_handoffs, sparse_handoffs);
}

fn applySplitGraphArtifacts(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
) !void {
    if (artifact_keys.len == 0) return;

    for (dest_indexes.graph_indexes.items) |entry| {
        _ = try applySplitGraphArtifactsForIndex(dest_store, dest_indexes, artifact_keys, entry.config.name);
    }
}

fn applySplitGraphArtifactsForIndex(
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    artifact_keys: []const []const u8,
    index_name: []const u8,
) !usize {
    _ = dest_indexes.graphIndex(index_name) orelse return error.IndexNotFound;
    if (artifact_keys.len == 0) return 0;

    var graph_mutations = try collectGraphMutationsForArtifacts(
        dest_indexes.alloc,
        dest_store,
        artifact_keys,
        index_name,
        .{},
    );
    defer graph_mutations.deinit();
    const mutation_count = graph_mutations.writes.len + graph_mutations.deletes.len;
    try dest_indexes.applyGraphMutationsByName(index_name, graph_mutations.writes, graph_mutations.deletes);
    return mutation_count;
}

fn applySplitGraphArtifactsForIndexStreaming(
    alloc: Allocator,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    index_name: []const u8,
    batch_size: usize,
) !usize {
    _ = dest_indexes.graphIndex(index_name) orelse return error.IndexNotFound;
    const store_lower = try documentRangeLowerAlloc(alloc, "");
    defer alloc.free(store_lower);
    const effective_batch_size = @max(batch_size, 1);

    const ScanState = struct {
        alloc: Allocator,
        dest_store: *docstore_mod.DocStore,
        dest_indexes: *index_manager_mod.IndexManager,
        index_name: []const u8,
        batch_size: usize,
        keys: std.ArrayListUnmanaged([]const u8) = .empty,
        mutation_count: usize = 0,

        fn freeKeys(state: *@This()) void {
            for (state.keys.items) |key| state.alloc.free(@constCast(key));
            state.keys.clearRetainingCapacity();
        }

        fn deinit(state: *@This()) void {
            state.freeKeys();
            state.keys.deinit(state.alloc);
        }

        fn flush(state: *@This()) !void {
            if (state.keys.items.len == 0) return;
            if (comptime builtin.is_test) {
                _ = test_graph_repair_stream_flushes.fetchAdd(1, .monotonic);
            }
            state.mutation_count += try applySplitGraphArtifactsForIndex(
                state.dest_store,
                state.dest_indexes,
                state.keys.items,
                state.index_name,
            );
            state.freeKeys();
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, _: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            if (!internal_keys.isGraphEdgeArtifactKey(key)) return .@"continue";
            const owned = try state.alloc.dupe(u8, key);
            errdefer state.alloc.free(owned);
            try state.keys.append(state.alloc, owned);
            if (state.keys.items.len >= state.batch_size) try state.flush();
            return .@"continue";
        }
    };

    var state = ScanState{
        .alloc = alloc,
        .dest_store = dest_store,
        .dest_indexes = dest_indexes,
        .index_name = index_name,
        .batch_size = effective_batch_size,
    };
    defer state.deinit();

    try dest_store.scanWithContext(store_lower, "", .{}, &state, ScanState.scanEntry);
    try state.flush();
    return state.mutation_count;
}

fn applySplitGraphArtifactsForIndexStreamingContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    batch_size: usize,
) !usize {
    _ = ctx.index_manager.graphIndex(index_name) orelse return error.IndexNotFound;
    const store_lower = try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(store_lower);
    const effective_batch_size = @max(batch_size, 1);

    const ScanState = struct {
        ctx: *AsyncContext,
        index_name: []const u8,
        batch_size: usize,
        writes: std.ArrayListUnmanaged(types.GraphEdgeWrite) = .empty,
        mutation_count: usize = 0,

        fn freeWrites(state: *@This()) void {
            for (state.writes.items) |write| {
                state.ctx.alloc.free(@constCast(write.index_name));
                state.ctx.alloc.free(@constCast(write.source));
                state.ctx.alloc.free(@constCast(write.target));
                state.ctx.alloc.free(@constCast(write.edge_type));
                if (write.metadata_json.len > 0) state.ctx.alloc.free(@constCast(write.metadata_json));
            }
            state.writes.clearRetainingCapacity();
        }

        fn deinit(state: *@This()) void {
            state.freeWrites();
            state.writes.deinit(state.ctx.alloc);
        }

        fn flush(state: *@This()) !void {
            try checkAsyncRepairCancelled(state.ctx);
            if (state.writes.items.len == 0) return;
            try checkAsyncRepairCapacityBoundary(state.ctx);
            if (comptime builtin.is_test) {
                _ = test_graph_repair_stream_flushes.fetchAdd(1, .monotonic);
            }
            try state.ctx.index_manager.applyGraphMutationsByName(state.index_name, state.writes.items, &.{});
            state.mutation_count += state.writes.items.len;
            state.freeWrites();
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            if (!internal_keys.isGraphEdgeArtifactKey(key)) return .@"continue";
            try checkAsyncRepairCancelled(state.ctx);
            const parsed = (try internal_keys.parseGraphEdgeArtifactKeyAlloc(state.ctx.alloc, key)) orelse return .@"continue";
            defer {
                state.ctx.alloc.free(parsed.doc_key);
                state.ctx.alloc.free(parsed.index_name);
                state.ctx.alloc.free(parsed.edge_type);
                state.ctx.alloc.free(parsed.target_doc_key);
            }
            if (!std.mem.eql(u8, parsed.index_name, state.index_name)) return .@"continue";

            var decoded = enrichment_artifact_codec.decodeGraphEdgeAlloc(state.ctx.alloc, value) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => {
                    const artifact_name = try std.fmt.allocPrint(state.ctx.alloc, "{s}:{s}", .{ parsed.edge_type, parsed.target_doc_key });
                    defer state.ctx.alloc.free(artifact_name);
                    try recordArtifactRepairIssueContext(
                        state.ctx,
                        .graph,
                        parsed.index_name,
                        parsed.doc_key,
                        "",
                        "",
                        "",
                        artifact_name,
                        key,
                        null,
                        state.ctx.repair_sequence,
                        .corrupt_artifact,
                    );
                    return .@"continue";
                },
            };
            errdefer decoded.deinit(state.ctx.alloc);
            try state.writes.append(state.ctx.alloc, .{
                .index_name = try state.ctx.alloc.dupe(u8, parsed.index_name),
                .source = try state.ctx.alloc.dupe(u8, parsed.doc_key),
                .target = try state.ctx.alloc.dupe(u8, parsed.target_doc_key),
                .edge_type = try state.ctx.alloc.dupe(u8, parsed.edge_type),
                .weight = decoded.weight,
                .created_at = decoded.created_at,
                .updated_at = decoded.updated_at,
                .metadata_json = decoded.metadata_json,
            });
            decoded.metadata_json = &.{};
            decoded.deinit(state.ctx.alloc);
            if (state.writes.items.len >= state.batch_size) try state.flush();
            return .@"continue";
        }
    };

    var state = ScanState{
        .ctx = ctx,
        .index_name = index_name,
        .batch_size = effective_batch_size,
    };
    defer state.deinit();

    try scanStoreForRebuildContext(ctx, store_lower, "", .{}, &state, ScanState.scanEntry);
    try state.flush();
    return state.mutation_count;
}

fn applySplitGraphArtifactsInRange(
    alloc: Allocator,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
) !void {
    const artifact_keys = try collectGraphArtifactKeysInRangeAlloc(alloc, dest_store, lower, upper);
    defer freeOwnedConstStringSlice(alloc, artifact_keys);
    try applySplitGraphArtifacts(dest_store, dest_indexes, artifact_keys);
}

fn indexExistingSplitDestinationDirect(
    alloc: Allocator,
    lower: []const u8,
    upper: []const u8,
    dest_store: *docstore_mod.DocStore,
    dest_indexes: *index_manager_mod.IndexManager,
    dense_handoffs: []const index_manager_mod.DenseSplitHandoff,
    text_handoffs: []const index_manager_mod.TextSplitHandoff,
    sparse_handoffs: []const index_manager_mod.SparseSplitHandoff,
) !void {
    const batch_size = 8192;

    const store_lower = try documentRangeLowerAlloc(alloc, lower);
    defer alloc.free(store_lower);
    const store_upper = if (upper.len > 0) try documentRangeUpperAlloc(alloc, upper) else null;
    defer if (store_upper) |buf| alloc.free(buf);

    const scanned = try dest_store.scanRange(alloc, store_lower, if (store_upper) |buf| buf else "");
    defer docstore_mod.DocStore.freeResults(alloc, scanned);

    var writes = std.ArrayListUnmanaged(types.BatchWrite).empty;
    defer writes.deinit(alloc);
    for (scanned) |entry| {
        if (isSplitMetadataKey(entry.key)) continue;
        try writes.append(alloc, .{
            .key = entry.key,
            .value = entry.value,
        });
        if (writes.items.len == batch_size) {
            try putIndexedSplitBatchDirect(dest_store, dest_indexes, writes.items, dense_handoffs, text_handoffs, sparse_handoffs);
            writes.clearRetainingCapacity();
        }
    }

    if (writes.items.len > 0) try putIndexedSplitBatchDirect(dest_store, dest_indexes, writes.items, dense_handoffs, text_handoffs, sparse_handoffs);
}

fn finalizeSplitLocked(self: *DB, new_range: types.ByteRange) !void {
    const split_state = self.core.splitState() orelse return error.SplitInProgress;
    if (!std.mem.eql(u8, split_state.split_key, new_range.end)) return error.KeyOutOfRange;
    const replay_floor = self.core.nextDerivedAppendSequence();

    const split_lower = try documentRangeLowerAlloc(self.alloc, split_state.split_key);
    defer self.alloc.free(split_lower);
    try markSplitOffDocumentArtifactChildRangesLocked(self, split_state, split_lower);
    try finalizePrimarySplitPreservingIdentity(self, split_lower);
    try ensureReplayFloor(self.core.store, replay_floor);
    try self.core.pruneSplitRangeFromPrimaryIndexes(split_state.split_key, split_state.original_range_end);
    try self.rebaseManagedIndexAppliedSequencesIfNeeded();

    if (split_state.phase == .prepare) {
        try self.core.completeSplitTransition(split_state.new_shard_id, split_state.split_key);
    } else if (split_state.phase != .splitting and split_state.phase != .finalizing) {
        return error.SplitInProgress;
    }

    try self.core.finalizeSplitState();
    try self.refreshManagedIndexWorkersLocked();
    try self.closeShadowIndexManager();
    try self.refreshManagedIndexWorkersLocked();
}

fn markSplitOffDocumentArtifactChildRangesLocked(
    self: *DB,
    split_state: shard_mod.SplitState,
    split_lower: []const u8,
) !void {
    if (split_state.new_shard_id == 0) return;

    const parent_lower = try documentRangeLowerAlloc(self.alloc, self.core.byteRange().start);
    defer self.alloc.free(parent_lower);
    const parent_upper = split_lower;
    const split_upper = if (split_state.original_range_end.len > 0)
        try documentRangeUpperAlloc(self.alloc, split_state.original_range_end)
    else
        null;
    defer if (split_upper) |upper| self.alloc.free(upper);

    const scanned = try self.core.scanStoreRange(self.alloc, parent_lower, parent_upper);
    defer docstore_mod.DocStore.freeResults(self.alloc, scanned);

    var writes = std.ArrayListUnmanaged(docstore_mod.KVPair).empty;
    defer writes.deinit(self.alloc);
    var owned_values = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (owned_values.items) |value| self.alloc.free(value);
        owned_values.deinit(self.alloc);
    }
    var changed_artifact_keys = std.ArrayListUnmanaged([]u8).empty;
    defer {
        for (changed_artifact_keys.items) |key| self.alloc.free(key);
        changed_artifact_keys.deinit(self.alloc);
    }

    for (scanned) |entry| {
        if (std.mem.indexOf(u8, entry.value, "\"child_ranges\"") == null) continue;
        var artifact_ref = (try decodeArtifactRefIfKnownAlloc(self.alloc, entry.key)) orelse continue;
        defer artifact_ref.deinit(self.alloc);
        if (artifact_ref.kind != .asset or artifact_ref.unit_id != null) continue;

        var arena = std.heap.ArenaAllocator.init(self.alloc);
        defer arena.deinit();
        const arena_alloc = arena.allocator();
        var manifest_value = try std.json.parseFromSliceLeaky(std.json.Value, arena_alloc, entry.value, .{ .allocate = .alloc_always });
        if (manifest_value != .object) continue;
        const child_ranges = manifest_value.object.getPtr("child_ranges") orelse continue;
        if (child_ranges.* != .array) continue;

        var changed = false;
        for (child_ranges.array.items) |*item| {
            if (item.* != .object) continue;
            if (!documentArtifactChildRangeMovedBySplit(item.object, split_lower, split_upper)) continue;
            try putLeakyJsonStringField(arena_alloc, &item.object, "placement", "remote");
            try putLeakyJsonU64Field(arena_alloc, &item.object, "owner_group_id", split_state.new_shard_id);
            try putLeakyJsonU64Field(arena_alloc, &item.object, "placement_generation", (try jsonObjectOptionalU64(item.object, "placement_generation") orelse 0) + 1);
            try putLeakyJsonStringField(arena_alloc, &item.object, "route_status", "remote_committed");
            try item.object.put(arena_alloc, "split_eligible", .{ .bool = false });
            changed = true;
        }
        if (!changed) continue;

        const updated_manifest = try std.json.Stringify.valueAlloc(self.alloc, manifest_value, .{});
        errdefer self.alloc.free(updated_manifest);
        try owned_values.append(self.alloc, updated_manifest);
        try writes.append(self.alloc, .{
            .key = entry.key,
            .value = updated_manifest,
        });
        try appendUniqueOwnedKey(self.alloc, &changed_artifact_keys, entry.key);
    }

    if (writes.items.len == 0) return;
    const sequence = self.core.reserveDerivedAppendSequence();
    const replay_payload = try encodeChangeRecordPayload(&self.batchContext(), .{
        .sequence = sequence,
        .changed_artifact_keys = changed_artifact_keys.items,
    }, sequence);
    defer self.alloc.free(replay_payload);
    try self.core.store.putBatchWithReplay(self.backend_runtime.io(), writes.items, &.{}, .{
        .sequence = sequence,
        .payload = replay_payload,
    });
    self.mirrorHAReplayPayloadBestEffort(replay_payload);
    if (shouldAppendSplitDelta(self)) {
        try self.core.appendSplitDelta(currentTimeNs(), writes.items, &.{});
    }
    self.executor.trackBacklogBytes(sequence, @intCast(replay_payload.len)) catch {};
}

fn documentArtifactChildRangeMovedBySplit(
    object: std.json.ObjectMap,
    split_lower: []const u8,
    split_upper: ?[]const u8,
) bool {
    const split_eligible = blk: {
        const value = object.get("split_eligible") orelse break :blk false;
        if (value != .bool) return false;
        break :blk value.bool;
    };
    if (!split_eligible) return false;

    const placement = object.get("placement") orelse return false;
    if (placement != .string) return false;
    if (std.mem.eql(u8, placement.string, "remote")) return false;

    if (object.get("owner_group_id")) |owner| {
        if (owner == .integer and owner.integer > 0) return false;
    }

    const route_status = object.get("route_status") orelse null;
    if (route_status) |status| {
        if (status != .string) return false;
        if (std.mem.eql(u8, status.string, "remote_committed")) return false;
    }

    const start_key = object.get("start_key") orelse return false;
    if (start_key != .string) return false;
    if (std.mem.order(u8, start_key.string, split_lower) == .lt) return false;
    const end_key = object.get("end_key_exclusive") orelse return false;
    if (end_key != .string) return false;
    if (split_upper) |upper| {
        if (end_key.string.len == 0) return false;
        if (std.mem.order(u8, end_key.string, upper) == .gt) return false;
    }
    return true;
}

fn byteRangesEqual(a: types.ByteRange, b: types.ByteRange) bool {
    return std.mem.eql(u8, a.start, b.start) and std.mem.eql(u8, a.end, b.end);
}

fn isSplitMetadataKey(key: []const u8) bool {
    return std.mem.startsWith(u8, key, "splitstate:") or std.mem.startsWith(u8, key, "splitdelta:");
}

fn clearSplitMetadataFromStore(alloc: Allocator, dest_store: *docstore_mod.DocStore) !void {
    try deleteKeysWithPrefixFromStore(alloc, dest_store, "splitstate:");
    try deleteKeysWithPrefixFromStore(alloc, dest_store, "splitdelta:");
}

fn clearSystemMetadataFromSplitDestination(alloc: Allocator, dest_store: *docstore_mod.DocStore) !void {
    try deleteKeysWithPrefixFromStore(alloc, dest_store, "\x00\x00__metadata__:");
}

fn ensureReplayFloor(store: *docstore_mod.DocStore, next_sequence: u64) !void {
    try store.ensureReplayNextSequenceAtLeast(next_sequence);
}

fn deleteKeysWithPrefixFromStore(alloc: Allocator, dest_store: *docstore_mod.DocStore, prefix: []const u8) !void {
    const keys = try dest_store.scanPrefix(alloc, prefix);
    defer docstore_mod.DocStore.freeResults(alloc, keys);
    if (keys.len == 0) return;

    var deletes = std.ArrayListUnmanaged([]const u8).empty;
    defer deletes.deinit(alloc);
    for (keys) |item| {
        try deletes.append(alloc, item.key);
    }
    try dest_store.putBatch(&.{}, deletes.items);
}

fn copyFileIfPresent(src_dir: []const u8, dst_dir: []const u8, name: []const u8) !u64 {
    const src_path = try std.fmt.allocPrint(std.heap.page_allocator, "{s}/{s}", .{ src_dir, name });
    defer std.heap.page_allocator.free(src_path);
    const dst_path = try std.fmt.allocPrint(std.heap.page_allocator, "{s}/{s}", .{ dst_dir, name });
    defer std.heap.page_allocator.free(dst_path);

    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();

    std.Io.Dir.accessAbsolute(io, src_path, .{}) catch |err| switch (err) {
        error.FileNotFound => return 0,
        else => return err,
    };

    var src_file = try std.Io.Dir.openFileAbsolute(io, src_path, .{});
    defer src_file.close(io);
    const src_stat = try src_file.stat(io);

    var dst_file = try fs_paths.createFilePortable(io, dst_path, .{ .truncate = true });
    defer dst_file.close(io);

    var writer_buf: [1024]u8 = undefined;
    var writer = dst_file.writer(io, &writer_buf);
    var src_reader: std.Io.File.Reader = .initSize(src_file, io, &.{}, src_stat.size);
    _ = writer.interface.sendFileAll(&src_reader, .unlimited) catch |err| switch (err) {
        error.ReadFailed => return src_reader.err.?,
        error.WriteFailed => return writer.err.?,
    };
    try writer.flush();
    return src_stat.size;
}

fn ensureDirPath(path: []const u8) !void {
    if (path.len == 0) return;
    var io_impl = threadedIo();
    defer io_impl.deinit();
    try fs_paths.createDirPathPortable(io_impl.io(), path);
}

fn directoryUsageBytes(alloc: Allocator, path: []const u8) !u64 {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    var dir = std.Io.Dir.cwd().openDir(io_impl.io(), path, .{ .iterate = true }) catch |err| switch (err) {
        error.FileNotFound => return 0,
        else => return err,
    };
    defer dir.close(io_impl.io());
    var total: u64 = 0;
    var walker = try dir.walk(alloc);
    defer walker.deinit();
    while (try walker.next(io_impl.io())) |entry| {
        if (entry.kind != .file) continue;
        const stat = try dir.statFile(io_impl.io(), entry.path, .{});
        total +|= stat.size;
    }
    return total;
}

fn createUniqueRepairShadowBase(alloc: Allocator, base_path: []const u8) ![]u8 {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();
    try fs_paths.createDirPathPortable(io, base_path);

    for (0..64) |_| {
        const candidate = try std.fmt.allocPrint(alloc, "{s}/.repair-shadow-{d}-{x}", .{
            base_path,
            monotonicTimeNs(),
            repair_shadow_nonce.fetchAdd(1, .monotonic),
        });
        errdefer alloc.free(candidate);
        std.Io.Dir.cwd().createDir(io, candidate, .default_dir) catch |err| switch (err) {
            error.PathAlreadyExists => {
                alloc.free(candidate);
                continue;
            },
            else => return err,
        };
        errdefer std.Io.Dir.cwd().deleteTree(io, candidate) catch {};
        try fs_paths.syncDirPortable(io, base_path);
        return candidate;
    }
    return error.PathAlreadyExists;
}

fn resetPath(path: []const u8) !void {
    var io_impl = threadedIo();
    defer io_impl.deinit();
    const io = io_impl.io();
    std.Io.Dir.cwd().deleteTree(io, path) catch {};
    try fs_paths.createDirPathPortable(io, path);
}

fn applyDerivedBatchToIndexAsync(ctx_ptr: *anyopaque, batch: derived_types.DerivedBatch, index_ref: index_manager_mod.ManagedIndexRef) !bool {
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    if (!try batchAffectsManagedIndexForReplay(ctx.index_manager, batch, index_ref)) return false;
    if (index_ref.kind == .dense_vector and ctx.active_external_dense_bulk_sessions.load(.acquire) != 0) {
        return error.ReplayDocumentNotVisible;
    }

    try applyDerivedBatchToIndexContext(ctx, batch, index_ref);

    if (index_ref.kind == .dense_vector) {
        setDenseCatchUpProgress(ctx, .{
            .sequence = batch.sequence,
            .target_sequence = ctx.store.lastReplaySequence(0),
            .scanned_entries = 0,
            .applied_entries = 1,
            .active = true,
        });
    }
    if (index_ref.kind == .full_text) if (ctx.text_merge_runtime) |runtime| {
        if (ctx.text_merge_deferred.load(.acquire)) return true;
        runtime.notify();
        runtime.applyBackpressure();
    };
    if (index_ref.kind == .sparse_vector) if (ctx.sparse_compaction_runtime) |runtime| {
        runtime.notify();
    };
    return true;
}

fn beginDenseStreamingReplaySessionForAsyncCatchUp(ctx: *AsyncContext, index_ref: index_manager_mod.ManagedIndexRef) !void {
    var index_apply_guard = try ctx.index_manager.lockManagedIndexApply(index_ref);
    defer index_apply_guard.unlock();
    try ctx.index_manager.beginDenseStreamingReplaySessionByName(index_ref.name);
}

fn finishDenseStreamingReplaySessionForAsyncCatchUp(
    ctx: *AsyncContext,
    index_ref: index_manager_mod.ManagedIndexRef,
    options: backend_types.BulkIngestFinishOptions,
) !void {
    var index_apply_guard = try ctx.index_manager.lockManagedIndexApply(index_ref);
    defer index_apply_guard.unlock();
    try ctx.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_ref.name, options);
}

fn abortDenseStreamingReplaySessionForAsyncCatchUp(ctx: *AsyncContext, index_ref: index_manager_mod.ManagedIndexRef) void {
    var index_apply_guard = ctx.index_manager.lockManagedIndexApply(index_ref) catch return;
    defer index_apply_guard.unlock();
    ctx.index_manager.abortDenseStreamingReplaySessionByName(index_ref.name);
}

fn beginDerivedCatchUpSessionAsync(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef) !void {
    if (index_ref.kind != .dense_vector) return;
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    if (ctx.active_external_dense_bulk_sessions.load(.acquire) != 0) return error.ReplayDocumentNotVisible;

    try beginDenseCatchUpSessionTracked(ctx, index_ref.name);
    errdefer finishDenseCatchUpSessionTracked(ctx, index_ref.name);
    try beginDenseStreamingReplaySessionForAsyncCatchUp(ctx, index_ref);
    errdefer abortDenseStreamingReplaySessionForAsyncCatchUp(ctx, index_ref);
    _ = ctx.stats.dense_catch_up.begin_calls.fetchAdd(1, .monotonic);
}

fn finishDerivedCatchUpSessionAsync(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef, success: bool) !void {
    if (index_ref.kind != .dense_vector) return;
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));

    if (!success) {
        _ = ctx.stats.dense_catch_up.abort_calls.fetchAdd(1, .monotonic);
        var seq_lock = lockAtomicWithBackoffProfiled(&ctx.applied_sequence_mutex, &ctx.stats.applied_sequence_mutex);
        ctx.applied_sequence_coalescer.removePending(ctx.alloc, index_ref.name);
        seq_lock.unlock();
        abortDenseStreamingReplaySessionForAsyncCatchUp(ctx, index_ref);
        finishDenseCatchUpSessionTracked(ctx, index_ref.name);
        return;
    }
    var catch_up_tracked = true;
    errdefer if (catch_up_tracked) finishDenseCatchUpSessionTracked(ctx, index_ref.name);
    var streaming_session_finished = false;
    errdefer if (!streaming_session_finished) abortDenseStreamingReplaySessionForAsyncCatchUp(ctx, index_ref);
    const finish_start_ns = monotonicTimeNs();
    const before_lsm_stats = denseLsmWriteStatsSnapshot(ctx, index_ref.name);

    // Keep async dense catch-up finishes bounded and durable, but leave LSM maintenance
    // to the explicit maintenance paths instead of paying it on every replay catch-up finish.
    const maintenance_steps: usize = 0;
    const maintenance_ns: u64 = 0;
    // Dense catch-up finish needs a durable watermark for the completed dense index itself.
    // Flushing every unrelated pending index here turns one dense session close into a
    // source-wide sync storm. Leave other indexes on the normal coalesced flush path.
    setDenseCatchUpPhase(ctx, .bulk_finish);
    var finish_options = denseCatchUpFinishOptions();
    finish_options.progress_ctx = ctx;
    finish_options.progress_fn = noteDenseBulkFinishProgress;
    const finalize_start_ns = monotonicTimeNs();
    try finishDenseStreamingReplaySessionForAsyncCatchUp(ctx, index_ref, finish_options);
    streaming_session_finished = true;
    const finalize_ns = elapsedSince(finalize_start_ns);
    setDenseCatchUpPhase(ctx, .applied_sequence_flush);
    const published_visibility = blk: {
        var seq_lock = lockAtomicWithBackoffProfiled(
            &ctx.applied_sequence_mutex,
            &ctx.stats.applied_sequence_mutex,
        );
        defer seq_lock.unlock();
        const published = try flushFinishedDenseAppliedSequenceLocked(ctx, index_ref.name);
        break :blk published;
    };
    const after_lsm_stats = denseLsmWriteStatsSnapshot(ctx, index_ref.name);
    const finish_ns = elapsedSince(finish_start_ns);

    _ = ctx.stats.dense_catch_up.finish_calls.fetchAdd(1, .monotonic);
    _ = ctx.stats.dense_catch_up.finish_ns.fetchAdd(finish_ns, .monotonic);
    atomicMaxU64(&ctx.stats.dense_catch_up.max_finish_ns, finish_ns);
    _ = ctx.stats.dense_catch_up.finalize_ns.fetchAdd(finalize_ns, .monotonic);
    atomicMaxU64(&ctx.stats.dense_catch_up.max_finalize_ns, finalize_ns);
    _ = ctx.stats.dense_catch_up.maintenance_calls.fetchAdd(1, .monotonic);
    _ = ctx.stats.dense_catch_up.maintenance_steps.fetchAdd(@intCast(maintenance_steps), .monotonic);
    _ = ctx.stats.dense_catch_up.maintenance_ns.fetchAdd(maintenance_ns, .monotonic);
    atomicMaxU64(&ctx.stats.dense_catch_up.max_maintenance_ns, maintenance_ns);
    var dense_window_result = resource_manager_mod.DenseReplayWindowResult{ .finish_ns = finish_ns };
    if (before_lsm_stats) |before| if (after_lsm_stats) |after| {
        const delta = denseLsmWriteStatsDelta(after, before);
        _ = ctx.stats.dense_catch_up.manifest_writes.fetchAdd(delta.manifest_writes, .monotonic);
        _ = ctx.stats.dense_catch_up.manifest_ns.fetchAdd(delta.manifest_ns, .monotonic);
        _ = ctx.stats.dense_catch_up.write_pressure_compactions.fetchAdd(delta.write_pressure_compactions, .monotonic);
        _ = ctx.stats.dense_catch_up.write_pressure_ns.fetchAdd(delta.write_pressure_ns, .monotonic);
        dense_window_result.write_pressure_compactions = delta.write_pressure_compactions;
        dense_window_result.write_pressure_ns = delta.write_pressure_ns;
    };
    if (ctx.index_manager.resource_manager) |manager| {
        manager.noteDenseReplayWindowResult(dense_window_result);
    }
    finishDenseCatchUpSessionTracked(ctx, index_ref.name);
    catch_up_tracked = false;
    if (DB.queryVisibilityHook(ctx)) |hook| {
        if (!published_visibility) hook.notify(.publish_consistent);
        hook.notify(.publish_blocking);
    }
}

fn storeHasReplayRecordForHintAfter(
    store: *docstore_mod.DocStore,
    hint: change_journal_mod.TargetHint,
    from_sequence: u64,
) !bool {
    const Context = struct {
        found: bool = false,

        fn handle(self: *@This(), sequence: u64, payload: []const u8) !void {
            _ = sequence;
            _ = payload;
            self.found = true;
        }
    };

    var ctx = Context{};
    const stats = store.forEachReplayLaneFrom(
        @intCast(@intFromEnum(hint)),
        from_sequence + 1,
        1,
        &ctx,
        Context.handle,
    ) catch |err| switch (err) {
        error.ReplayIndexUnavailable => return false,
        else => return err,
    };
    return ctx.found or stats.matched_entries != 0;
}

fn replayRangeHasManagedIndexApplicableRecord(
    ctx: *AsyncContext,
    index_ref: index_manager_mod.ManagedIndexRef,
    from_sequence: u64,
    target_sequence: u64,
) !bool {
    const Context = struct {
        alloc: Allocator,
        index_manager: *index_manager_mod.IndexManager,
        index_ref: index_manager_mod.ManagedIndexRef,
        target_sequence: u64,
        found: bool = false,

        fn handle(self: *@This(), sequence: u64, payload: []const u8) !void {
            if (sequence > self.target_sequence) return replay_source_mod.StopReplayChunk.StopReplayChunk;
            var decoded = try change_journal_mod.decodeRecord(self.alloc, payload);
            defer decoded.deinit();
            switch (managedIndexRecordApplicability(self.index_manager, decoded.record, self.index_ref)) {
                .irrelevant => {},
                .relevant, .missing_dependency => {
                    self.found = true;
                    return replay_source_mod.StopReplayChunk.StopReplayChunk;
                },
            }
        }
    };

    var scan_ctx = Context{
        .alloc = ctx.alloc,
        .index_manager = ctx.index_manager,
        .index_ref = index_ref,
        .target_sequence = target_sequence,
    };
    _ = ctx.store.forEachReplayLaneFrom(
        @intCast(@intFromEnum(managedIndexReplayHint(index_ref.kind))),
        from_sequence + 1,
        0,
        &scan_ctx,
        Context.handle,
    ) catch |err| switch (err) {
        error.ReplayIndexUnavailable => return try storeHasReplayRecordForHintAfter(ctx.store, managedIndexReplayHint(index_ref.kind), from_sequence),
        replay_source_mod.StopReplayChunk.StopReplayChunk => return scan_ctx.found,
        else => return err,
    };
    return scan_ctx.found;
}

fn canAdvanceDerivedToTargetAsync(ctx_ptr: *anyopaque, index_ref: index_manager_mod.ManagedIndexRef, from_sequence: u64, target_sequence: u64) !bool {
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    const persisted_applied = try apply_state.loadAppliedSequenceWithCheckpoint(
        ctx.alloc,
        ctx.store,
        ctx.applied_sequence_checkpoint_path,
        index_ref.name,
    );
    if (persisted_applied >= target_sequence) return true;

    if (try replayRangeHasManagedIndexApplicableRecord(ctx, index_ref, from_sequence, target_sequence)) return false;
    if (!ctx.index_manager.indexLoadComplete(index_ref.name)) return false;
    if (index_ref.kind != .dense_vector) return true;

    ctx.apply_mutex.lockExclusive();
    defer ctx.apply_mutex.unlockExclusive();

    const entry = ctx.index_manager.denseIndex(index_ref.name) orelse return true;
    if (!denseIndexIsArtifactBacked(entry)) return true;
    if (asyncContextHasActiveExternalDenseBulkWork(ctx)) return false;
    if (ctx.active_dense_catch_up_sessions.load(.acquire) != 0) return true;

    const expected_doc_count = (try denseTargetCountForIndexContext(ctx, index_ref.name)) orelse {
        std.log.warn(
            "dense replay target advance deferred by missing durable artifact counter index={s}",
            .{index_ref.name},
        );
        return false;
    };
    const active_count = entry.index.stats().active_count;
    if (denseCoverageMatchesTarget(active_count, expected_doc_count)) return true;

    const now_ns = monotonicTimeNs();
    if (!shouldRunTargetAdvanceRepair(ctx, index_ref.name, now_ns)) return false;
    try noteTargetAdvanceRepairRun(ctx, index_ref.name, now_ns);

    std.log.warn(
        "dense replay target advance blocked by coverage mismatch index={s} indexed={} expected_docs={}",
        .{ index_ref.name, active_count, expected_doc_count },
    );

    // Replaying artifacts can fill a deficit, but it cannot delete a vector
    // whose source artifact no longer exists. Leave surplus reconstruction to
    // the rebuild planner: it owns the reset lifecycle and invalidates any
    // persisted scan cursor. Closing the active HBC handle from this ordinary
    // replay path would race published searches despite the apply fence.
    if (active_count > expected_doc_count) {
        return false;
    }
    _ = rebuildDenseIndexForTargetCoverageContext(ctx, index_ref.name, 2048) catch |err| {
        std.log.warn(
            "dense replay target advance repair deferred index={s} err={s}",
            .{ index_ref.name, @errorName(err) },
        );
        return false;
    };
    const repaired_entry = ctx.index_manager.denseIndex(index_ref.name) orelse return true;
    return denseCoverageMatchesTarget(repaired_entry.index.stats().active_count, expected_doc_count);
}

fn denseIndexIsArtifactBacked(entry: anytype) bool {
    return entry.external or entry.chunk_name != null or entry.embedding_name != null;
}

fn denseCoverageMatchesTarget(active_count: u64, expected_count: u64) bool {
    return active_count == expected_count;
}

fn denseTargetCountForIndexContext(ctx: *AsyncContext, index_name: []const u8) !?u64 {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return 0;
    if (denseIndexIsArtifactBacked(entry)) {
        return try DB.loadDenseArtifactTargetCounter(ctx.alloc, ctx.store, index_name);
    }
    return try densePrimaryVectorTargetCountForIndexContext(ctx, index_name);
}

fn denseArtifactTargetCountForIndexContext(ctx: *AsyncContext, index_name: []const u8) !u64 {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return 0;
    const expected_name = DB.denseArtifactNameForEntry(entry);
    const expected_dims = entry.dims;

    const lower = try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);

    const ScanState = struct {
        alloc: Allocator,
        expected_name: []const u8,
        expected_dims: u32,
        count: u64 = 0,

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            if (!internal_keys.isInternalUserKey(key)) return .@"continue";

            var artifact_ref = (try decodeArtifactRefIfKnownAlloc(state.alloc, key)) orelse return .@"continue";
            defer artifact_ref.deinit(state.alloc);
            if (artifact_ref.kind != .embedding) return .@"continue";
            if (!std.mem.eql(u8, artifact_ref.name, state.expected_name)) return .@"continue";

            const dims = enrichment_artifact_codec.decodeDenseEmbeddingDims(value) catch |err| {
                if (DB.isRecoverableEmbeddingArtifactError(err)) return .@"continue";
                return err;
            };
            if (dims != state.expected_dims) return .@"continue";

            state.count += 1;
            return .@"continue";
        }
    };

    var state = ScanState{
        .alloc = ctx.alloc,
        .expected_name = expected_name,
        .expected_dims = expected_dims,
    };
    try scanStoreForRebuildContext(ctx, lower, "", .{}, &state, ScanState.scanEntry);
    return state.count;
}

fn scanStoreForRebuildContext(
    ctx: *AsyncContext,
    lower: []const u8,
    upper: []const u8,
    options: docstore_mod.DocStore.ScanOptions,
    scan_ctx: ?*anyopaque,
    callback: docstore_mod.DocStore.ScanWithContextCallback,
) !void {
    if (ctx.snapshot_read_txn) |txn| {
        return try ctx.store.scanReadTxnWithContext(txn, lower, upper, options, scan_ctx, callback);
    }
    return try ctx.store.scanWithContext(lower, upper, options, scan_ctx, callback);
}

fn densePrimaryVectorTargetCountForIndexContext(ctx: *AsyncContext, index_name: []const u8) !u64 {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return 0;
    const field_name = entry.field_name;
    const dims = entry.dims;

    const lower = try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);

    const ScanState = struct {
        alloc: Allocator,
        field_name: []const u8,
        dims: u32,
        count: u64 = 0,

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            if (!isPrimaryDocumentStoreKey(key)) return .@"continue";
            if (try mapper.extractDenseVectorField(state.alloc, value, state.field_name, state.dims)) |vector| {
                state.alloc.free(vector);
                state.count += 1;
            }
            return .@"continue";
        }
    };

    var state = ScanState{
        .alloc = ctx.alloc,
        .field_name = field_name,
        .dims = dims,
    };
    try scanStoreForRebuildContext(ctx, lower, "", .{}, &state, ScanState.scanEntry);
    return state.count;
}

fn freePrimaryVectorRebuildWrites(alloc: Allocator, writes: *std.ArrayListUnmanaged(types.BatchWrite)) void {
    for (writes.items) |write| {
        alloc.free(@constCast(write.key));
        alloc.free(@constCast(write.value));
    }
    writes.clearRetainingCapacity();
}

fn flushDensePrimaryVectorRebuildChunkContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    writes: *std.ArrayListUnmanaged(types.BatchWrite),
) !void {
    defer freePrimaryVectorRebuildWrites(ctx.alloc, writes);
    if (writes.items.len == 0) return;
    try checkAsyncRepairCancelled(ctx);
    try checkAsyncRepairCapacityBoundary(ctx);
    try ctx.index_manager.indexDenseBatchByNameWithOptions(
        ctx.store,
        index_name,
        writes.items,
        .{ .mode = .bulk_ingest },
    );
}

const DenseRebuildSliceResult = struct {
    rebuilt: usize = 0,
    /// Owned source-store key. A non-null value means the candidate was
    /// durably closed at a cooperative yield boundary and the next pass must
    /// resume strictly after this key.
    resume_key: ?[]u8 = null,

    fn deinit(self: *@This(), alloc: Allocator) void {
        if (self.resume_key) |key| alloc.free(key);
        self.* = undefined;
    }

    fn complete(self: @This()) bool {
        return self.resume_key == null;
    }
};

fn denseRepairYieldRequested(ctx: *AsyncContext) bool {
    if (ctx.repair_options.yield_check) |check| return check.requested();
    return false;
}

fn rebuildDenseIndexFromPrimaryVectorsContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
) !usize {
    var result = try rebuildDenseIndexFromPrimaryVectorsSliceContext(ctx, index_name, rebuild_chunk_size, null);
    defer result.deinit(ctx.alloc);
    std.debug.assert(result.complete());
    return result.rebuilt;
}

fn rebuildDenseIndexFromPrimaryVectorsSliceContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
    resume_key: ?[]const u8,
) !DenseRebuildSliceResult {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return .{};
    const field_name = entry.field_name;
    const dims = entry.dims;

    const lower = if (resume_key) |key| try ctx.alloc.dupe(u8, key) else try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);

    const resumable = ctx.repair_options.yield_check != null;
    if (resumable) {
        try ctx.index_manager.beginDenseStreamingReplaySessionByName(index_name);
    } else {
        try ctx.index_manager.beginDenseBulkIngestSessionByName(index_name);
    }
    var session_open = true;
    errdefer if (session_open) {
        if (resumable) {
            ctx.index_manager.abortDenseStreamingReplaySessionByName(index_name);
        } else {
            ctx.index_manager.abortDenseBulkIngestSessionByName(index_name);
        }
    };

    const ScanState = struct {
        ctx: *AsyncContext,
        index_name: []const u8,
        field_name: []const u8,
        dims: u32,
        rebuild_chunk_size: usize,
        writes: std.ArrayListUnmanaged(types.BatchWrite) = .empty,
        rebuilt: usize = 0,
        scanned_since_yield_check: usize = 0,
        resume_key: ?[]u8 = null,

        fn deinit(state: *@This()) void {
            freePrimaryVectorRebuildWrites(state.ctx.alloc, &state.writes);
            state.writes.deinit(state.ctx.alloc);
            if (state.resume_key) |key| state.ctx.alloc.free(key);
        }

        fn flush(state: *@This()) !void {
            try flushDensePrimaryVectorRebuildChunkContext(state.ctx, state.index_name, &state.writes);
        }

        fn yieldAfter(state: *@This(), key: []const u8) !docstore_mod.DocStore.ScanAction {
            if (!denseRepairYieldRequested(state.ctx)) return .@"continue";
            try state.flush();
            state.resume_key = try state.ctx.alloc.dupe(u8, key);
            return .stop;
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            state.scanned_since_yield_check += 1;
            if (!isPrimaryDocumentStoreKey(key)) {
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            }
            try checkAsyncRepairCancelled(state.ctx);
            if (try mapper.extractDenseVectorField(state.ctx.alloc, value, state.field_name, state.dims)) |vector| {
                state.ctx.alloc.free(vector);
            } else {
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            }
            const doc_key = (try internal_keys.decodePrimaryDocumentKeyAlloc(state.ctx.alloc, key)) orelse return .@"continue";
            errdefer state.ctx.alloc.free(doc_key);
            const doc_value = try state.ctx.alloc.dupe(u8, value);
            errdefer state.ctx.alloc.free(doc_value);
            try state.writes.append(state.ctx.alloc, .{
                .key = doc_key,
                .value = doc_value,
            });
            state.rebuilt += 1;

            if (state.writes.items.len >= state.rebuild_chunk_size) {
                try state.flush();
                state.scanned_since_yield_check = 0;
                return try state.yieldAfter(key);
            }
            return .@"continue";
        }
    };

    var state = ScanState{
        .ctx = ctx,
        .index_name = index_name,
        .field_name = field_name,
        .dims = dims,
        .rebuild_chunk_size = rebuild_chunk_size,
    };
    defer state.deinit();

    try scanStoreForRebuildContext(ctx, lower, "", .{ .lower_exclusive = resume_key != null }, &state, ScanState.scanEntry);
    if (state.writes.items.len > 0) try state.flush();

    if (resumable) {
        try ctx.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_name, denseRepairFinishOptions(ctx));
    } else {
        try ctx.index_manager.finishDenseBulkIngestSessionByNameWithOptions(index_name, denseRepairFinishOptions(ctx));
    }
    session_open = false;
    const owned_resume_key = state.resume_key;
    state.resume_key = null;
    return .{ .rebuilt = state.rebuilt, .resume_key = owned_resume_key };
}

fn flushDenseArtifactRebuildChunkContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    writes: *std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite),
) !void {
    defer DB.freeDenseArtifactRebuildWrites(ctx.alloc, writes);
    if (writes.items.len == 0) return;
    try checkAsyncRepairCancelled(ctx);
    try checkAsyncRepairCapacityBoundary(ctx);
    try ctx.index_manager.applyDenseEmbeddingWritesByNameWithOptions(
        ctx.store,
        index_name,
        writes.items,
        .{ .mode = .bulk_ingest },
    );
}

fn rebuildDenseIndexFromStoredEmbeddingArtifactsContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
) !usize {
    var result = try rebuildDenseIndexFromStoredEmbeddingArtifactsSliceContext(ctx, index_name, rebuild_chunk_size, null);
    defer result.deinit(ctx.alloc);
    std.debug.assert(result.complete());
    return result.rebuilt;
}

fn rebuildDenseIndexFromStoredEmbeddingArtifactsSliceContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
    resume_key: ?[]const u8,
) !DenseRebuildSliceResult {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return .{};
    const expected_name = DB.denseArtifactNameForEntry(entry);
    const expected_dims = entry.dims;

    const lower = if (resume_key) |key| try ctx.alloc.dupe(u8, key) else try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);

    const resumable = ctx.repair_options.yield_check != null;
    if (resumable) {
        try ctx.index_manager.beginDenseStreamingReplaySessionByName(index_name);
    } else {
        try ctx.index_manager.beginDenseBulkIngestSessionByName(index_name);
    }
    var session_open = true;
    errdefer if (session_open) {
        if (resumable) {
            ctx.index_manager.abortDenseStreamingReplaySessionByName(index_name);
        } else {
            ctx.index_manager.abortDenseBulkIngestSessionByName(index_name);
        }
    };

    const ScanState = struct {
        ctx: *AsyncContext,
        index_name: []const u8,
        expected_name: []const u8,
        expected_dims: u32,
        rebuild_chunk_size: usize,
        writes: std.ArrayListUnmanaged(mapper.DenseEmbeddingWrite) = .empty,
        rebuilt: usize = 0,
        scanned_since_yield_check: usize = 0,
        resume_key: ?[]u8 = null,

        fn deinit(state: *@This()) void {
            DB.freeDenseArtifactRebuildWrites(state.ctx.alloc, &state.writes);
            state.writes.deinit(state.ctx.alloc);
            if (state.resume_key) |key| state.ctx.alloc.free(key);
        }

        fn flush(state: *@This()) !void {
            try flushDenseArtifactRebuildChunkContext(state.ctx, state.index_name, &state.writes);
        }

        fn yieldAfter(state: *@This(), key: []const u8) !docstore_mod.DocStore.ScanAction {
            if (!denseRepairYieldRequested(state.ctx)) return .@"continue";
            try state.flush();
            state.resume_key = try state.ctx.alloc.dupe(u8, key);
            return .stop;
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            state.scanned_since_yield_check += 1;
            if (!internal_keys.isInternalUserKey(key)) {
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            }
            try checkAsyncRepairCancelled(state.ctx);

            const dims = enrichment_artifact_codec.decodeDenseEmbeddingDims(value) catch |err| {
                if (DB.isRecoverableEmbeddingArtifactError(err)) {
                    if (state.scanned_since_yield_check >= 1024) {
                        state.scanned_since_yield_check = 0;
                        return try state.yieldAfter(key);
                    }
                    return .@"continue";
                }
                return err;
            };
            if (dims != state.expected_dims) {
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            }

            var identity = (try decodeEmbeddingArtifactWriteIdentityAlloc(state.ctx.alloc, key, state.expected_name)) orelse {
                if (state.scanned_since_yield_check >= 1024) {
                    state.scanned_since_yield_check = 0;
                    return try state.yieldAfter(key);
                }
                return .@"continue";
            };
            var write_transferred = false;
            errdefer if (!write_transferred) identity.deinit(state.ctx.alloc);

            const owned_index_name = try state.ctx.alloc.dupe(u8, state.index_name);
            errdefer if (!write_transferred) state.ctx.alloc.free(owned_index_name);
            const artifact_key = try state.ctx.alloc.dupe(u8, key);
            errdefer if (!write_transferred) state.ctx.alloc.free(artifact_key);
            try state.writes.append(state.ctx.alloc, .{
                .index_name = owned_index_name,
                .doc_key = identity.doc_key,
                .parent_doc_key = identity.parent_doc_key,
                .artifact_key = artifact_key,
                .vector = &.{},
            });
            write_transferred = true;
            state.rebuilt += 1;

            if (state.writes.items.len >= state.rebuild_chunk_size) {
                try state.flush();
                state.scanned_since_yield_check = 0;
                return try state.yieldAfter(key);
            }
            return .@"continue";
        }
    };

    var state = ScanState{
        .ctx = ctx,
        .index_name = index_name,
        .expected_name = expected_name,
        .expected_dims = expected_dims,
        .rebuild_chunk_size = rebuild_chunk_size,
    };
    defer state.deinit();

    try scanStoreForRebuildContext(ctx, lower, "", .{ .lower_exclusive = resume_key != null }, &state, ScanState.scanEntry);
    if (state.writes.items.len > 0) try state.flush();

    if (resumable) {
        try ctx.index_manager.finishDenseStreamingReplaySessionByNameWithOptions(index_name, denseRepairFinishOptions(ctx));
    } else {
        try ctx.index_manager.finishDenseBulkIngestSessionByNameWithOptions(index_name, denseRepairFinishOptions(ctx));
    }
    session_open = false;
    const owned_resume_key = state.resume_key;
    state.resume_key = null;
    return .{ .rebuilt = state.rebuilt, .resume_key = owned_resume_key };
}

fn rebuildDenseIndexForTargetCoverageContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
) !usize {
    var result = try rebuildDenseIndexForTargetCoverageSliceContext(ctx, index_name, rebuild_chunk_size, null);
    defer result.deinit(ctx.alloc);
    std.debug.assert(result.complete());
    return result.rebuilt;
}

fn rebuildDenseIndexForTargetCoverageSliceContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
    resume_key: ?[]const u8,
) !DenseRebuildSliceResult {
    const entry = ctx.index_manager.denseIndex(index_name) orelse return .{};
    if (!denseIndexIsArtifactBacked(entry)) {
        return try rebuildDenseIndexFromPrimaryVectorsSliceContext(ctx, index_name, rebuild_chunk_size, resume_key);
    }
    return try rebuildDenseIndexFromStoredEmbeddingArtifactsSliceContext(ctx, index_name, rebuild_chunk_size, resume_key);
}

fn flushSparseArtifactRebuildChunkContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    writes: *std.ArrayListUnmanaged(mapper.SparseEmbeddingWrite),
) !void {
    defer DB.freeSparseArtifactRebuildWrites(ctx.alloc, writes);
    if (writes.items.len == 0) return;
    try checkAsyncRepairCancelled(ctx);
    try checkAsyncRepairCapacityBoundary(ctx);
    try ctx.index_manager.applySparseEmbeddingWritesByNameWithOptions(
        ctx.store,
        index_name,
        writes.items,
        .{ .mode = .bulk_ingest },
    );
}

fn rebuildSparseIndexFromStoredEmbeddingArtifactsContext(
    ctx: *AsyncContext,
    index_name: []const u8,
    rebuild_chunk_size: usize,
) !usize {
    const expected_name = ctx.index_manager.sparseEmbeddingName(index_name) orelse index_name;

    const lower = try documentRangeLowerAlloc(ctx.alloc, "");
    defer ctx.alloc.free(lower);

    const ScanState = struct {
        ctx: *AsyncContext,
        index_name: []const u8,
        expected_name: []const u8,
        rebuild_chunk_size: usize,
        writes: std.ArrayListUnmanaged(mapper.SparseEmbeddingWrite) = .empty,
        rebuilt: usize = 0,

        fn deinit(state: *@This()) void {
            DB.freeSparseArtifactRebuildWrites(state.ctx.alloc, &state.writes);
            state.writes.deinit(state.ctx.alloc);
        }

        fn flush(state: *@This()) !void {
            try flushSparseArtifactRebuildChunkContext(state.ctx, state.index_name, &state.writes);
        }

        fn scanEntry(scan_ctx: ?*anyopaque, key: []const u8, value: []const u8) anyerror!docstore_mod.DocStore.ScanAction {
            const state: *@This() = @ptrCast(@alignCast(scan_ctx orelse return error.InvalidArgument));
            if (!internal_keys.isInternalUserKey(key)) return .@"continue";
            try checkAsyncRepairCancelled(state.ctx);

            const identity = (try internal_keys.parseEmbeddingArtifactKeyView(key)) orelse return .@"continue";
            if (!std.mem.eql(u8, identity.artifact_name, state.expected_name)) return .@"continue";

            var sparse = enrichment_artifact_codec.decodeSparseEmbeddingAlloc(state.ctx.alloc, value) catch |err| {
                if (DB.isRecoverableEmbeddingArtifactError(err)) return .@"continue";
                return err;
            };
            errdefer sparse.deinit(state.ctx.alloc);
            const doc_key = try state.ctx.alloc.dupe(u8, identity.doc_key);
            errdefer state.ctx.alloc.free(doc_key);
            const indices = sparse.indices;
            sparse.indices = &.{};
            errdefer state.ctx.alloc.free(indices);
            const values = sparse.values;
            sparse.values = &.{};
            errdefer state.ctx.alloc.free(values);

            try state.writes.append(state.ctx.alloc, .{
                .index_name = @constCast(state.index_name),
                .doc_key = doc_key,
                .artifact_key = null,
                .indices = indices,
                .values = values,
            });
            state.rebuilt += 1;

            if (state.writes.items.len >= state.rebuild_chunk_size) try state.flush();
            return .@"continue";
        }
    };

    var state = ScanState{
        .ctx = ctx,
        .index_name = index_name,
        .expected_name = expected_name,
        .rebuild_chunk_size = rebuild_chunk_size,
    };
    defer state.deinit();

    try scanStoreForRebuildContext(ctx, lower, "", .{}, &state, ScanState.scanEntry);
    if (state.writes.items.len > 0) try state.flush();
    return state.rebuilt;
}

fn persistAppliedSequenceAsync(ctx_ptr: *anyopaque, index_name: []const u8, sequence: u64, force: bool) !bool {
    const ctx: *AsyncContext = @ptrCast(@alignCast(ctx_ptr));
    if (force) {
        var seq_lock = lockAtomicWithBackoffProfiled(&ctx.applied_sequence_mutex, &ctx.stats.applied_sequence_mutex);
        defer seq_lock.unlock();
        _ = ctx.stats.applied_sequence.note_calls.fetchAdd(1, .monotonic);
        _ = ctx.stats.applied_sequence.forced_flush_calls.fetchAdd(1, .monotonic);
        try ctx.applied_sequence_coalescer.note(ctx.alloc, index_name, sequence);
        return try flushPendingAppliedSequencesLocked(ctx, true);
    }
    if (!ctx.applied_sequence_mutex.tryLock()) {
        _ = ctx.stats.applied_sequence.skipped_flush_calls.fetchAdd(1, .monotonic);
        return false;
    }
    defer ctx.applied_sequence_mutex.unlock();
    _ = ctx.stats.applied_sequence.note_calls.fetchAdd(1, .monotonic);
    try ctx.applied_sequence_coalescer.note(ctx.alloc, index_name, sequence);
    if (shouldDeferAppliedSequenceFlush(ctx, false)) {
        _ = ctx.stats.applied_sequence.skipped_flush_calls.fetchAdd(1, .monotonic);
        return false;
    }
    if (!ctx.applied_sequence_coalescer.shouldFlush(monotonicTimeNs())) {
        _ = ctx.stats.applied_sequence.skipped_flush_calls.fetchAdd(1, .monotonic);
        return false;
    }
    return try flushPendingAppliedSequencesLocked(ctx, false);
}

fn finalizeCoveredDenseProjectionCheckpoint(ctx: *AsyncContext, index_name: []const u8, applied_sequence: u64) !void {
    const checkpoint = ctx.index_manager.denseProjectionCheckpointMetadata(index_name) orelse return;
    if (checkpoint.status != .rebuilding) return;
    if (asyncContextHasActiveExternalDenseBulkWork(ctx) or ctx.active_dense_catch_up_sessions.load(.acquire) != 0) return;

    const expected_count = (try denseTargetCountForIndexContext(ctx, index_name)) orelse return;
    const entry = ctx.index_manager.denseIndex(index_name) orelse return;
    if (entry.index.stats().active_count != expected_count) return;

    const clean_checkpoint: apply_state.ProjectionCheckpoint = .{
        .applied_sequence = applied_sequence,
        .status = .clean,
        .generation = checkpoint.generation +| 1,
        .config_hash = checkpoint.config_hash,
    };
    try ctx.index_manager.saveDenseProjectionCheckpointMetadata(index_name, clean_checkpoint);
    try apply_state.saveProjectionCheckpointWithSidecar(
        ctx.alloc,
        ctx.store,
        ctx.applied_sequence_checkpoint_path,
        index_name,
        clean_checkpoint,
    );
}

fn flushFinishedDenseAppliedSequenceLocked(ctx: *AsyncContext, index_name: []const u8) !bool {
    const pending = ctx.applied_sequence_coalescer.takePending(index_name) orelse return false;
    defer ctx.alloc.free(pending.owned_name);

    const flush_start_ns = monotonicTimeNs();
    const save_start_ns = monotonicTimeNs();
    // Checkpointing managed projection effects reaches into live index
    // backends. Hold a shared apply lease so concurrent persistence remains
    // parallel while catalog replacement's exclusive lease cannot retire a
    // backend underneath this durability boundary.
    ctx.apply_mutex.lockShared();
    defer ctx.apply_mutex.unlockShared();
    const raw_update = [_]apply_state.AppliedSequenceUpdate{.{
        .index_name = pending.owned_name,
        .sequence = pending.sequence,
    }};
    const enriched_updates = try appliedSequenceUpdatesWithConfigHashes(ctx.alloc, ctx.index_manager, &raw_update);
    defer ctx.alloc.free(enriched_updates);
    try saveDenseProjectionMetadataForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
    try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
    try apply_state.saveAppliedSequencesWithCheckpoint(ctx.alloc, ctx.store, ctx.applied_sequence_checkpoint_path, enriched_updates);
    try finalizeCoveredDenseProjectionCheckpoint(ctx, pending.owned_name, pending.sequence);
    try DB.saveIndexStatusSnapshots(ctx.alloc, ctx.store, ctx.index_manager, enriched_updates);
    const save_ns = elapsedSince(save_start_ns);

    ctx.applied_sequence_coalescer.last_flush_ns = monotonicTimeNs();
    const flush_ns = elapsedSince(flush_start_ns);
    _ = ctx.stats.applied_sequence.flush_calls.fetchAdd(1, .monotonic);
    _ = ctx.stats.applied_sequence.flushed_indexes.fetchAdd(1, .monotonic);
    _ = ctx.stats.applied_sequence.save_ns.fetchAdd(save_ns, .monotonic);
    _ = ctx.stats.applied_sequence.flush_ns.fetchAdd(flush_ns, .monotonic);
    atomicMaxU64(&ctx.stats.applied_sequence.max_flush_ns, flush_ns);
    DB.notifyQueryVisibilityHook(ctx, .status);
    return true;
}

fn flushPendingAppliedSequencesLocked(ctx: *AsyncContext, force: bool) !bool {
    if (ctx.applied_sequence_coalescer.pending.count() == 0) return false;

    const flush_start_ns = monotonicTimeNs();
    var updates = std.ArrayListUnmanaged(apply_state.AppliedSequenceUpdate).empty;
    defer updates.deinit(ctx.alloc);

    var it = ctx.applied_sequence_coalescer.pending.iterator();
    while (it.next()) |entry| {
        if (!force and shouldDeferAppliedSequenceFlush(ctx, false)) continue;
        try updates.append(ctx.alloc, .{
            .index_name = entry.key_ptr.*,
            .sequence = entry.value_ptr.*,
        });
    }
    if (updates.items.len == 0) return false;
    const enriched_updates = try appliedSequenceUpdatesWithConfigHashes(ctx.alloc, ctx.index_manager, updates.items);
    defer ctx.alloc.free(enriched_updates);
    const sync_ns: u64 = 0;

    const save_start_ns = monotonicTimeNs();
    // Keep the complete metadata/checkpoint/status transaction on one stable
    // index generation. Shared holders may proceed concurrently; index
    // replacement and teardown require the exclusive lease.
    ctx.apply_mutex.lockShared();
    defer ctx.apply_mutex.unlockShared();
    try saveDenseProjectionMetadataForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
    try checkpointManagedProjectionEffectsForAppliedSequenceUpdates(ctx.index_manager, enriched_updates);
    try apply_state.saveAppliedSequencesWithCheckpoint(
        ctx.alloc,
        ctx.store,
        ctx.applied_sequence_checkpoint_path,
        enriched_updates,
    );
    for (enriched_updates) |update| try finalizeCoveredDenseProjectionCheckpoint(ctx, update.index_name, update.sequence);
    try DB.saveIndexStatusSnapshots(ctx.alloc, ctx.store, ctx.index_manager, enriched_updates);
    const save_ns = elapsedSince(save_start_ns);
    ctx.applied_sequence_coalescer.clearPending(ctx.alloc);
    ctx.applied_sequence_coalescer.last_flush_ns = monotonicTimeNs();
    const flush_ns = elapsedSince(flush_start_ns);
    _ = ctx.stats.applied_sequence.flush_calls.fetchAdd(1, .monotonic);
    _ = ctx.stats.applied_sequence.flushed_indexes.fetchAdd(@intCast(updates.items.len), .monotonic);
    _ = ctx.stats.applied_sequence.sync_ns.fetchAdd(sync_ns, .monotonic);
    _ = ctx.stats.applied_sequence.save_ns.fetchAdd(save_ns, .monotonic);
    _ = ctx.stats.applied_sequence.flush_ns.fetchAdd(flush_ns, .monotonic);
    atomicMaxU64(&ctx.stats.applied_sequence.max_flush_ns, flush_ns);
    DB.notifyQueryVisibilityHook(ctx, .status);
    return true;
}

