        .kind = .chunk,
        .field = "text",
        .source_artifact_name = "document_units_v1",
        .chunk_size = 16,
        .chunk_overlap = 0,
        .full_text_index = true,
    });
    try db.addIndex(.{
        .name = "ft_document_chunks",
