    try std.testing.expectError(error.InvalidArgument, db.preflightSearchRequest(alloc, .{
        .graph_queries = &.{
            .{
                .name = "k_zero",
                .query = .{
                    .query_type = .k_shortest_paths,
                    .index_name = "graph_v1",
                    .start_nodes = .{ .keys = &.{"doc:a"} },
                    .target_nodes = .{ .keys = &.{"doc:b"} },
                    .k = 0,
                },
            },
        },
    }, 0));
    try std.testing.expectError(error.InvalidArgument, db.preflightSearchRequest(alloc, .{
        .graph_queries = &.{
            .{
                .name = "pattern_with_target",
                .query = .{
                    .query_type = .pattern,
                    .index_name = "graph_v1",
                    .start_nodes = .{ .keys = &.{"doc:a"} },
                    .target_nodes = .{ .keys = &.{"doc:b"} },
                    .pattern = &.{
                        .{
                            .alias = "src",
                            .edge = .{},
                        },
                    },
                },
            },
