    );
    try std.testing.expectError(
        error.HAReadOnlyStandby,
        db.finishPrimaryStoreAutoBulkIngestSessionWithOptions(.{}),
    );
    try std.testing.expectError(
        error.HAReadOnlyStandby,
        db.updateRange(.{ .start = "doc:a", .end = "doc:z" }),
