        (try DB.loadDenseArtifactCounterBootstrap(alloc, reopened.core.store, cfg.name)).?.delta,
    );
    try reopened.batch(.{
        .deletes = &.{"doc:a"},
        .sync_level = .write,
    });
    try std.testing.expectEqual(
        @as(i64, 0),
        (try DB.loadDenseArtifactCounterBootstrap(alloc, reopened.core.store, cfg.name)).?.delta,
    );

    const snapshot_count = try reopened.countDenseArtifactsForConfigFromReadTxn(
