test "db index sort schema change requires a new text index generation" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
    });
    defer db.close();

    const sortable_schema_json =
        \\{"version":1,"default_type":"doc","enforce_types":false,"document_schemas":{"doc":{"schema":{"type":"object","additionalProperties":true,"properties":{"body":{"type":"string","x-antfly-field":{"type":"text"}},"price":{"type":"number","x-antfly-field":{"type":"number","sortable":true}}}}}}}
    ;
    try db.setSchemaJson(alloc, sortable_schema_json);

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:b", .value = "{\"body\":\"common old\",\"price\":2}" },
            .{ .key = "doc:d", .value = "{\"body\":\"common old\",\"price\":4}" },
        },
        .sync_level = .full_index,
    });

    const index_sort_schema_json =
        \\{"version":2,"default_type":"doc","enforce_types":false,"index_sort":[{"field":"price","order":"asc"},{"field":"_id","order":"asc"}],"document_schemas":{"doc":{"schema":{"type":"object","additionalProperties":true,"properties":{"body":{"type":"string","x-antfly-field":{"type":"text"}},"price":{"type":"number","x-antfly-field":{"type":"number","sortable":true}}}}}}}
    ;
    try db.setSchemaJson(alloc, index_sort_schema_json);

    try db.addIndex(.{
        .name = "ft_v2",
        .kind = .full_text,
        .config_json = "{}",
    });

    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:a", .value = "{\"body\":\"common new\",\"price\":1}" },
            .{ .key = "doc:c", .value = "{\"body\":\"common new\",\"price\":3}" },
        },
        .sync_level = .full_index,
    });

    const order_by = [_]types.SortField{
        .{ .field = "price" },
        .{ .field = "_id" },
    };
    var original_generation = try db.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .match_all = {} },
        .order_by = &order_by,
        .include_stored = false,
        .profile = true,
        .limit = 4,
    });
    defer original_generation.deinit();

    try std.testing.expectEqual(@as(usize, 4), original_generation.hits.len);
    try std.testing.expectEqualStrings("doc:a", original_generation.hits[0].id);
    try std.testing.expectEqualStrings("doc:b", original_generation.hits[1].id);
    try std.testing.expectEqualStrings("doc:c", original_generation.hits[2].id);
    try std.testing.expectEqualStrings("doc:d", original_generation.hits[3].id);
    const original_profile = original_generation.sort_profile orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("native_doc_values_top_n", original_profile.plan);
    try std.testing.expectEqualStrings("doc_values_collector", original_profile.source);
    try std.testing.expectEqualStrings("doc_values_collector", original_profile.selection_reason);
    try std.testing.expect(!original_profile.index_sort_match);
    try std.testing.expect(!original_profile.sorted_segment_executor_available);
    try std.testing.expectEqualStrings("request_mismatch", original_profile.index_sort_coverage);
    try std.testing.expectEqual(@as(u64, 0), original_profile.stored_json_load_count);

    var next_generation = try db.search(alloc, .{
        .index_name = "ft_v2",
        .query = .{ .match_all = {} },
        .order_by = &order_by,
        .include_stored = false,
        .profile = true,
        .limit = 4,
    });
    defer next_generation.deinit();

    try std.testing.expectEqual(@as(usize, 4), next_generation.hits.len);
    try std.testing.expectEqualStrings("doc:a", next_generation.hits[0].id);
    try std.testing.expectEqualStrings("doc:b", next_generation.hits[1].id);
    try std.testing.expectEqualStrings("doc:c", next_generation.hits[2].id);
    try std.testing.expectEqualStrings("doc:d", next_generation.hits[3].id);
    {
        var txn = try db.core.store.beginProbeTxn();
        defer txn.abort();
        for (next_generation.hits) |hit| {
            const ordinal = try doc_identity.lookupOrdinalTxn(alloc, &txn, hit.id);
            try std.testing.expectEqual(ordinal, hit.doc_ordinal);
        }
    }
    const next_profile = next_generation.sort_profile orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("sorted_segment_seek", next_profile.plan);
    try std.testing.expectEqualStrings("sorted_segment_scan", next_profile.source);
    try std.testing.expectEqualStrings("index_sort_sorted_segment_seek", next_profile.selection_reason);
    try std.testing.expectEqualStrings("covered_with_bounds", next_profile.index_sort_coverage);
    try std.testing.expect(next_profile.index_sort_match);
    try std.testing.expect(next_profile.sorted_segment_executor_available);
    try std.testing.expect(next_profile.sorted_segment_bounds_available);
    try std.testing.expectEqual(@as(u64, 0), next_profile.stored_json_load_count);
}

test "db text compaction preserves ordinal filters across reopen" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    const expected_ordinal: doc_set.DocOrdinal = 9;
    {
        var db = try DB.open(alloc, std.mem.span(path), .{
            .start_index_workers = false,
        });
        defer db.close();

        try db.addIndex(.{
            .name = "ft_v1",
            .kind = .full_text,
            .config_json = "{}",
        });

        for (0..12) |i| {
            const key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i});
            defer alloc.free(key);
            const value = try std.fmt.allocPrint(alloc, "{{\"body\":\"common token {d}\"}}", .{i});
            defer alloc.free(value);

            try db.batch(.{
                .writes = &.{.{ .key = key, .value = value }},
                .sync_level = .full_index,
            });
        }

        var include = try db.resolveDocSetForIdsAlloc(alloc, &.{"doc:8"});
        errdefer include.deinit(alloc);
        const resolved_ordinal = switch (include) {
            .ordinals => |ordinals| blk: {
                try std.testing.expectEqual(@as(usize, 1), ordinals.len);
                break :blk ordinals[0];
            },
            else => return error.ExpectedOrdinalDocSet,
        };
        try std.testing.expectEqual(expected_ordinal, resolved_ordinal);

        var filter = doc_set.ResolvedDocFilter{
            .include = include,
            .exclude = .none,
        };
        include = .all;
        defer filter.deinit(alloc);

        try db.forceCompactTextIndexes();

        const text_index = db.core.index_manager.textIndex("ft_v1").?;
        try std.testing.expect(text_index.snapshot().segments.len <= index_manager_mod.default_text_merge_max_segments_per_tier);

        var result = try db.search(alloc, .{
            .index_name = "ft_v1",
            .query = .{ .match = .{ .field = "body", .text = "common" } },
            .limit = 20,
            .resolved_doc_filter = &filter,
        });
        defer result.deinit();

        try std.testing.expectEqual(@as(u32, 1), result.total_hits);
        try std.testing.expectEqual(@as(usize, 1), result.hits.len);
        try std.testing.expectEqualStrings("doc:8", result.hits[0].id);
        try std.testing.expectEqual(@as(?doc_set.DocOrdinal, expected_ordinal), result.hits[0].doc_ordinal);
    }

    {
        var reopened = try DB.open(alloc, std.mem.span(path), .{
            .start_index_workers = false,
        });
        defer reopened.close();

        var include = try reopened.resolveDocSetForIdsAlloc(alloc, &.{"doc:8"});
        errdefer include.deinit(alloc);
        const resolved_ordinal = switch (include) {
            .ordinals => |ordinals| blk: {
                try std.testing.expectEqual(@as(usize, 1), ordinals.len);
                break :blk ordinals[0];
            },
            else => return error.ExpectedOrdinalDocSet,
        };
        try std.testing.expectEqual(expected_ordinal, resolved_ordinal);

        var filter = doc_set.ResolvedDocFilter{
            .include = include,
            .exclude = .none,
        };
        include = .all;
        defer filter.deinit(alloc);

        const text_index = reopened.core.index_manager.textIndex("ft_v1").?;
        try std.testing.expect(text_index.snapshot().segments.len <= index_manager_mod.default_text_merge_max_segments_per_tier);

        var result = try reopened.search(alloc, .{
            .index_name = "ft_v1",
            .query = .{ .match = .{ .field = "body", .text = "common" } },
            .limit = 20,
            .resolved_doc_filter = &filter,
        });
        defer result.deinit();

        try std.testing.expectEqual(@as(u32, 1), result.total_hits);
        try std.testing.expectEqual(@as(usize, 1), result.hits.len);
        try std.testing.expectEqualStrings("doc:8", result.hits[0].id);
        try std.testing.expectEqual(@as(?doc_set.DocOrdinal, expected_ordinal), result.hits[0].doc_ordinal);
    }
}

test "db provisioning schema is persisted before configured full text indexes open" {
    const alloc = std.testing.allocator;
    const table_schema_api = @import("../../schema/mod.zig");

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    // Persist the target-generation catalog entry while the shard still has
    // no target schema. This is the state an interrupted migration presents
    // to the next provisioning open.
    {
        var db = try DB.open(alloc, std.mem.span(path), .{ .start_index_workers = false });
        defer db.close();
        try db.addIndex(.{
            .name = "full_text_index_v1",
            .kind = .full_text,
            .config_json = "{}",
        });
    }

    const schema_json =
        \\{
        \\  "version": 1,
        \\  "default_type": "doc",
        \\  "enforce_types": true,
        \\  "document_schemas": {
        \\    "doc": {
        \\      "schema": {
        \\        "type": "object",
        \\        "additionalProperties": false,
        \\        "properties": {
        \\          "body": {
        \\            "type": "string",
        \\            "x-antfly-types": ["text"],
        \\            "x-antfly-include-in-all": false
        \\          }
        \\        },
        \\        "required": ["body"]
        \\      }
        \\    }
        \\  }
        \\}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);

    var reopened = try DB.open(alloc, std.mem.span(path), .{
        .start_index_workers = false,
        .schema_before_index_load = runtime_schema,
    });
    defer reopened.close();

    const entry = reopened.core.index_manager.textIndexEntry("full_text_index_v1") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u32, 1), entry.runtime_schema.?.version);
    try reopened.batch(.{
        .writes = &.{.{ .key = "doc:1", .value = "{\"body\":\"alpha beta\"}" }},
        .sync_level = .full_text,
    });

    const snapshot = entry.persistent.snapshot();
    try std.testing.expectEqual(@as(u32, 1), try snapshot.termDocFreq(alloc, "body", "alpha"));
    try std.testing.expectEqual(@as(u32, 0), try snapshot.termDocFreq(alloc, "body.keyword", "alpha beta"));
    try std.testing.expectEqual(@as(u32, 0), try snapshot.termDocFreq(alloc, "_all", "alpha"));
}

test "db best effort force compact leaves text merge debt under pressure" {
    const alloc = std.testing.allocator;
    const table_schema_api = @import("../../schema/mod.zig");

    var budgets = resource_manager_mod.Options.defaultBudgets();
    budgets[@intFromEnum(resource_manager_mod.Slice.text_merge_buffers)] = .{
        .soft_limit_bytes = 1,
        .hard_limit_bytes = 1024 * 1024,
    };
    var policies = resource_manager_mod.Options.defaultPolicies();
    policies[@intFromEnum(resource_manager_mod.Slice.text_merge_buffers)] = .{
        .soft_action = .defer_background_work,
        .hard_action = .defer_background_work,
    };
    var resource_manager = resource_manager_mod.ResourceManager.init(.{
        .budgets = budgets,
        .policies = policies,
    });
    var tracked_usage: u64 = 0;
    resource_manager.observeUsage(.text_merge_buffers, &tracked_usage, 2);
    defer resource_manager.observeUsage(.text_merge_buffers, &tracked_usage, 0);

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .resource_manager = &resource_manager,
        .text_merge = .{ .enabled = false },
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    const schema_json =
        \\{
        \\  "default_type": "doc",
        \\  "document_schemas": {
        \\    "doc": {
        \\      "schema": {
        \\        "type": "object",
        \\        "properties": {
        \\          "body": {
        \\            "type": "string",
        \\            "x-antfly-types": ["text"]
        \\          }
        \\        }
        \\      }
        \\    }
        \\  }
        \\}
    ;
    var parsed_schema = try table_schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const runtime_schema = try table_schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer schema_mod.freeSchema(alloc, runtime_schema);
    try db.setSchema(runtime_schema);

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });

    for (0..12) |i| {
        const key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i});
        defer alloc.free(key);
        const value = try std.fmt.allocPrint(alloc, "{{\"body\":\"common token {d}\"}}", .{i});
        defer alloc.free(value);

        try db.batch(.{
            .writes = &.{.{ .key = key, .value = value }},
            .sync_level = .full_text,
        });
    }

    const text_index_before = db.core.index_manager.textIndex("ft_v1").?;
    try std.testing.expect(text_index_before.snapshot().segments.len > 1);

    try db.bestEffortForceCompactTextIndexes();

    const text_index_after = db.core.index_manager.textIndex("ft_v1").?;
    try std.testing.expect(text_index_after.snapshot().segments.len > 1);

    var result = try db.search(alloc, .{
        .index_name = "ft_v1",
        .query = .{ .match = .{ .field = "body", .text = "common" } },
        .limit = 20,
    });
    defer result.deinit();

    try std.testing.expectEqual(@as(u32, 12), result.total_hits);
}

test "db runUntilIdle defers full text merge pressure without failing" {
    const alloc = std.testing.allocator;

    var budgets = resource_manager_mod.Options.defaultBudgets();
    budgets[@intFromEnum(resource_manager_mod.Slice.text_merge_buffers)] = .{
        .soft_limit_bytes = 1,
        .hard_limit_bytes = 1,
    };
    var policies = resource_manager_mod.Options.defaultPolicies();
    policies[@intFromEnum(resource_manager_mod.Slice.text_merge_buffers)] = .{
        .soft_action = .defer_background_work,
        .hard_action = .reject_work,
    };
    var resource_manager = resource_manager_mod.ResourceManager.init(.{
        .budgets = budgets,
        .policies = policies,
    });

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    var db = try DB.open(alloc, std.mem.span(path), .{
        .resource_manager = &resource_manager,
        .ttl_cleanup = .{ .enabled = false },
    });
    defer db.close();

    try db.addIndex(.{
        .name = "ft_v1",
        .kind = .full_text,
        .config_json = "{}",
    });

    for (0..12) |i| {
        const key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i});
        defer alloc.free(key);
        const value = try std.fmt.allocPrint(alloc, "{{\"body\":\"common token {d}\"}}", .{i});
        defer alloc.free(value);

        try db.batch(.{
            .writes = &.{.{ .key = key, .value = value }},
            .sync_level = .full_text,
        });
    }

    const before = db.pendingWorkStats().text_merge;
    try std.testing.expect(before.pending_segments > 0);

    try db.runUntilIdle();

    const after = db.pendingWorkStats().text_merge;
    try std.testing.expect(after.pending_segments > 0);
    try std.testing.expect(after.deferred_for_pressure >= before.deferred_for_pressure);

    const text_index = db.core.index_manager.textIndex("ft_v1").?;
    try std.testing.expect(text_index.snapshot().segments.len > 1);
}

test "db phrase query survives text compaction deletes and reopen" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
    const path = tempPath(&path_buf);
    defer cleanupTempDir(path);

    {
        var db = try DB.open(alloc, std.mem.span(path), .{});
        defer db.close();

        try db.addIndex(.{
            .name = "ft_v1",
            .kind = .full_text,
            .config_json = "{}",
        });

        for (0..6) |i| {
            const key = try std.fmt.allocPrint(alloc, "doc:{d}", .{i});
            defer alloc.free(key);

            const body = switch (i) {
                0 => "alpha beta",
                1 => "alpha beta gamma",
                2 => "alpha only",
                3 => "beta only",
                4 => "alpha beta delta",
                else => "gamma delta",
            };
            const value = try std.fmt.allocPrint(
                alloc,
                "{{\"title\":\"both\",\"body\":\"{s}\"}}",
                .{body},
            );
            defer alloc.free(value);

            try db.batch(.{
                .writes = &.{.{
                    .key = key,
                    .value = value,
                }},
                .sync_level = .full_index,
            });
        }

        try db.batch(.{
            .deletes = &.{"doc:1"},
            .sync_level = .full_index,
        });

        const text_index = db.core.index_manager.textIndex("ft_v1").?;
        try std.testing.expect(text_index.snapshot().segments.len < 6);

        var result = try db.search(alloc, .{
            .index_name = "ft_v1",
            .query = .{ .match_phrase = .{ .field = "body", .text = "alpha beta" } },
            .limit = 10,
        });
        defer result.deinit();

        try std.testing.expectEqual(@as(u32, 2), result.total_hits);
        try std.testing.expect(
            (std.mem.eql(u8, result.hits[0].id, "doc:0") and std.mem.eql(u8, result.hits[1].id, "doc:4")) or
                (std.mem.eql(u8, result.hits[0].id, "doc:4") and std.mem.eql(u8, result.hits[1].id, "doc:0")),
        );
    }

    {
        var reopened = try DB.open(alloc, std.mem.span(path), .{});
        defer reopened.close();

        var result = try reopened.search(alloc, .{
            .index_name = "ft_v1",
            .query = .{ .match_phrase = .{ .field = "body", .text = "alpha beta" } },
            .limit = 10,
        });
        defer result.deinit();

        try std.testing.expectEqual(@as(u32, 2), result.total_hits);
        try std.testing.expect(
            (std.mem.eql(u8, result.hits[0].id, "doc:0") and std.mem.eql(u8, result.hits[1].id, "doc:4")) or
                (std.mem.eql(u8, result.hits[0].id, "doc:4") and std.mem.eql(u8, result.hits[1].id, "doc:0")),
        );
    }
}

test "db prefix wildcard and regexp queries use text dictionary filters" {
    const alloc = std.testing.allocator;

    var path_buf: [256]u8 = undefined;
